window.CURSOS_MARA = window.CURSOS_MARA || [];
window.CURSOS_MARA.push({"id":"d-terapias-contextuales","nombre":"Diplomado en Terapias Contextuales: ACT, DBT y Activación Conductual","color":"#0D9488","nivel":"Diplomados","familia":"Salud y bienestar","periodoTipo":null,"periodoNum":null,"desc":"Da el paso de la TCC clásica al enfoque contextual: análisis funcional, formulación con la matriz ACT, los seis procesos de la terapia de aceptación y compromiso, las habilidades de la DBT, la activación conductual, la psicoterapia analítica funcional y el mindfulness con evidencia, con casos ficticios y hojas de cálculo para medir el avance. Es para psicólogos con cédula, estudiantes avanzados de psicología y psicoterapeutas cognitivo-conductuales. Da fundamentos y técnicas; no sustituye la formación clínica supervisada ni las certificaciones de cada modelo, y no habilita para ejercer la psicoterapia.","horas":40,"precio":2490,"publicado":true,"proximamente":false,"modulos":[{"id":"d-terapias-contextuales-m1","titulo":"Módulo 1 — La tercera generación y el enfoque contextual","resumen":"Qué cambia al pasar de la TCC clásica al enfoque contextual, el conductismo funcional y el análisis de la conducta en términos prácticos, el contextualismo funcional, lo que dice (y no dice) la evidencia y un panorama de ACT, DBT, FAP, activación conductual, mindfulness y terapia centrada en la compasión. Cuatro lecciones y una evaluación.","lecciones":[{"id":"d-terapias-contextuales-m1-l1","titulo":"Lección 1 — De la TCC clásica al enfoque contextual","objetivo":"reconocer qué cambia al pasar de la TCC clásica al enfoque contextual y qué te habilita y qué no este diplomado.","bloques":[{"tipo":"destacado","texto":"<b>Antes de empezar.</b> Este es un <b>diplomado libre de capacitación</b> con constancia de Instituto Mara: <b>no tiene validez oficial de la SEP</b> ni es una certificación de CONOCER. Está pensado para <b>psicólogos con cédula, estudiantes avanzados de psicología y psicoterapeutas cognitivo-conductuales</b>. Te da <b>fundamentos y técnicas</b>, pero <b>no sustituye la formación clínica supervisada</b> ni te autoriza a diagnosticar. En México la psicología exige título y <b>cédula profesional</b> (Ley General de Salud, art. 79): si no eres psicólogo, <b>no apliques estas técnicas como psicoterapia</b>; úsalas para entender, acompañar y canalizar.<br><br><b>Sobre certificaciones:</b> la Association for Contextual Behavioral Science (<b>ACBS</b>) declara que <b>no existe una certificación oficial de terapeuta ACT</b>; promueve la formación continua, la supervisión y la revisión entre pares. En DBT, la certificación de clínicos y programas la otorga el <b>DBT-Linehan Board of Certification (DBT-LBC)</b>, un organismo independiente de quienes imparten la formación intensiva, como <b>Behavioral Tech</b>. Este diplomado no equivale a ninguna de ellas."},{"tipo":"texto","texto":"En el <b>Diplomado en TCC</b> del instituto viste el modelo cognitivo: situaciones, pensamientos automáticos, creencias y técnicas para evaluarlos y modificarlos. Aquí no repetimos esos fundamentos; si necesitas repasarlos, vuelve a ese diplomado. Este programa parte de otra pregunta. La TCC clásica suele preguntar <b>«¿este pensamiento es cierto?»</b>. El enfoque contextual pregunta <b>«¿qué función cumple engancharte con este pensamiento aquí y ahora, y te acerca o te aleja de lo que te importa?»</b>."},{"tipo":"tabla","titulo":"Tres «olas» de la terapia conductual (esquema didáctico)","encabezados":["Etapa","Foco principal","Ejemplos"],"filas":[["Primera: terapia de conducta","Conducta observable y sus contingencias","Exposición, desensibilización sistemática, manejo de contingencias"],["Segunda: terapia cognitiva","<b>Contenido</b> de los pensamientos y creencias","Terapia cognitiva de Beck, terapia racional emotiva de Ellis"],["Tercera: enfoque contextual","<b>Función</b> y <b>relación</b> con la experiencia interna; aceptación, valores y flexibilidad","ACT, DBT, FAP, activación conductual, MBCT"]],"nota":"La etiqueta «tercera generación» (Hayes, 2004) es discutida: varios autores señalan que estas terapias comparten mucho con la TCC y que el cambio es más de énfasis que de ruptura. Úsala como mapa, no como ranking."},{"tipo":"comparar","titulo":"La misma sesión, dos énfasis","malTitulo":"Énfasis en el contenido","mal":"Consultante: «Voy a hacer el ridículo en la junta».<br>Terapeuta: «¿Qué evidencia tienes a favor y en contra? ¿Qué pensamiento sería más equilibrado?»","bienTitulo":"Énfasis en la función","bien":"Consultante: «Voy a hacer el ridículo en la junta».<br>Terapeuta: «Tu mente te dice eso otra vez. Si le haces caso, ¿qué haces? ¿Y eso te acerca a la persona que quieres ser en tu trabajo?»"},{"tipo":"relacionar","rotulo":"¿Qué énfasis tiene cada pregunta?","pares":[["¿Qué tan probable es que eso ocurra?","Evaluar el contenido"],["¿Para qué te ha servido evitar esa situación?","Analizar la función"],["¿Qué quieres que represente tu vida en esa área?","Clarificar valores"],["¿Puedes notar esa sensación sin pelear con ella?","Promover la aceptación"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Un psicólogo con cédula termina este diplomado. ¿Qué afirmación es correcta?","ops":["Tiene fundamentos, pero conviene seguir con formación supervisada en el modelo que aplique","Queda certificado en ACT por la ACBS","Queda certificado en DBT por el DBT-LBC"],"correcta":0,"explica":"Ningún diplomado libre sustituye la formación supervisada ni las certificaciones de cada modelo."},{"p":"Según la ACBS, la certificación oficial de terapeuta ACT…","ops":["La da cualquier diplomado de 40 horas","La otorga la SEP","No existe"],"correcta":2},{"p":"Una orientadora escolar sin formación en psicología toma el diplomado. Lo adecuado es…","ops":["Diagnosticar trastornos a sus alumnos","Usarlo para entender, acompañar y canalizar, no para dar psicoterapia","Abrir un consultorio de DBT"],"correcta":1}]},{"tipo":"clave","items":["El enfoque contextual se fija más en la función de la conducta y la relación con la experiencia interna que en su contenido.","Este diplomado no certifica en ACT (no existe certificación oficial) ni en DBT (la otorga el DBT-LBC).","Aplicar psicoterapia en México requiere formación profesional en psicología y cédula."]}]},{"id":"d-terapias-contextuales-m1-l2","titulo":"Lección 2 — Conductismo funcional: forma contra función","objetivo":"describir una conducta por su función y no por su forma usando los principios del reforzamiento, el castigo y la extinción.","bloques":[{"tipo":"texto","texto":"El análisis funcional viene del <b>conductismo radical</b> de Skinner. Su idea práctica es sencilla: <b>la misma conducta puede cumplir funciones muy distintas</b>, y conductas muy distintas pueden cumplir la misma función. Tomarse unas cervezas puede servir para convivir con los compas del trabajo (acceso a lo social) o para dejar de sentir la angustia de las deudas (escape del malestar). La <b>forma</b> (topografía) es igual; la <b>función</b> cambia, y con ella la intervención."},{"tipo":"tabla","titulo":"Los procesos básicos con ejemplos clínicos","encabezados":["Proceso","Qué pasa","Efecto en la conducta","Ejemplo"],"filas":[["Reforzamiento positivo","Aparece algo después de la conducta","Aumenta","Publicar en redes y recibir muchos «me gusta»"],["Reforzamiento negativo","Desaparece o baja algo aversivo","Aumenta","Salir del Metro lleno y sentir que baja la ansiedad"],["Castigo positivo","Aparece algo aversivo","Disminuye","Opinar en la junta y recibir burlas"],["Castigo negativo","Se retira algo agradable","Disminuye","Llegar tarde y perder el bono de puntualidad"],["Extinción","Deja de llegar el reforzador","Disminuye, a veces tras un «estallido» inicial","La pareja deja de responder a los reclamos a gritos"]]},{"tipo":"destacado","texto":"<b>Por qué importa el reforzamiento negativo.</b> Muchas conductas problema se mantienen porque <b>alivian el malestar de inmediato</b>, aunque empeoren las cosas a largo plazo: evitar, beber, revisar el celular, pedir reaseguración. Si solo miras la forma, no entiendes por qué se repiten; si miras la función, sí."},{"tipo":"texto","texto":"El enfoque contextual añade la <b>conducta verbal</b>. La teoría de los marcos relacionales (RFT, por sus siglas en inglés) propone que los humanos relacionamos palabras y experiencias de forma arbitraria, y por eso un recuerdo o una palabra pueden doler como la situación original. También explica la <b>conducta gobernada por reglas</b>: «si me ven nervioso, pensarán que no sirvo». Seguir reglas rígidas nos vuelve menos sensibles a lo que realmente pasa."},{"tipo":"relacionar","rotulo":"Identifica el proceso","pares":[["Faltar a la clase de inglés y sentir alivio","Reforzamiento negativo"],["Recibir elogios del jefe al entregar a tiempo","Reforzamiento positivo"],["Perder el celular una semana por reprobar","Castigo negativo"],["Los berrinches ya no consiguen dulces","Extinción"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Dos personas se encierran en su cuarto: una para evitar a su familia y otra para estudiar. Esto muestra que…","ops":["La misma forma puede tener funciones distintas","Ambas conductas son evitación","La forma define la intervención"],"correcta":0,"explica":"Por eso el análisis funcional pregunta «¿para qué?», no solo «¿qué?»."},{"p":"El reforzamiento negativo…","ops":["Disminuye la conducta","Es lo mismo que el castigo","Aumenta la conducta porque retira algo aversivo"],"correcta":2},{"p":"La conducta gobernada por reglas rígidas suele…","ops":["Desaparecer con la edad","Volvernos menos sensibles a las consecuencias reales","Mejorar siempre la adaptación"],"correcta":1}]},{"tipo":"clave","items":["Analiza la función de la conducta (para qué sirve), no solo su forma.","El reforzamiento negativo mantiene muchas conductas problema porque alivia de inmediato.","La RFT explica por qué las palabras y las reglas rígidas pueden dominar la conducta."]}]},{"id":"d-terapias-contextuales-m1-l3","titulo":"Lección 3 — Contextualismo funcional y qué dice la evidencia","objetivo":"explicar el criterio pragmático del contextualismo funcional y valorar con honestidad la evidencia de las terapias contextuales.","bloques":[{"tipo":"texto","texto":"El <b>contextualismo funcional</b> es la base filosófica de ACT y de la ciencia conductual contextual. Tiene tres ideas clave: la unidad de análisis es el <b>acto en su contexto</b> (no la conducta aislada); el criterio de verdad es <b>pragmático</b>: algo es «verdadero» en la medida en que <b>funciona</b> para lograr una meta definida; y la meta del análisis es <b>predecir e influir</b> en la conducta con precisión, alcance y profundidad. En clínica esto se traduce en preguntar «¿esto te funciona para lo que te importa?» en lugar de «¿esto es racional?»."},{"tipo":"tabla","titulo":"Qué respalda la investigación (resumen honesto)","encabezados":["Intervención","Dónde hay mejor evidencia","Matiz importante"],"filas":[["ACT","Ansiedad, depresión, dolor crónico, uso de sustancias y otras condiciones; una revisión paraguas (Gloster y colaboradores, 2020) la encontró eficaz frente a lista de espera y tratamiento habitual","En general <b>no supera</b> a la TCC tradicional; tiene eficacia comparable"],["DBT","Personas con diagnóstico de trastorno límite de la personalidad con autolesiones o conducta suicida recurrente","Reduce autolesiones y hospitalizaciones; la evidencia es menor para otras poblaciones"],["Activación conductual","Depresión; en un ensayo grande (COBRA, 2016) no fue inferior a la TCC y era más sencilla de entrenar","Requiere buen análisis funcional, no solo «agendar cosas bonitas»"],["MBCT","Prevención de recaídas en depresión recurrente cuando la persona está en remisión","No está diseñada para el episodio agudo grave"],["FAP y terapia centrada en la compasión","Estudios prometedores, más pequeños","Evidencia todavía en desarrollo"]],"nota":"Resumen elaborado con revisiones publicadas al momento de escribir. La evidencia se actualiza: consulta guías como las de NICE y la División 12 de la APA."},{"tipo":"destacado","texto":"<b>No infles la evidencia.</b> Que una terapia sea eficaz en estudios no significa que funcione con cada persona, ni que sus mecanismos propuestos estén demostrados: los estudios de mediación (si el cambio ocurre <i>por</i> la flexibilidad psicológica, por ejemplo) tienen resultados mixtos. Desconfía de frases como «la terapia más avanzada» o «cura la ansiedad en ocho sesiones»."},{"tipo":"comparar","titulo":"Cómo presentar la evidencia a un consultante","malTitulo":"Inflado","mal":"«La ACT es lo más moderno que hay; es mejor que la terapia cognitiva y te va a curar la ansiedad.»","bienTitulo":"Honesto","bien":"«La ACT tiene buena evidencia en ansiedad, con resultados parecidos a los de la TCC. Vamos a medir cómo te va cada semana y, si no avanzas, ajustamos el plan.»"},{"tipo":"completar","rotulo":"Completa","items":[{"frase":"En el contextualismo funcional, algo es verdadero en la medida en que ___ para lograr una meta.","resp":["funciona","sirve"]},{"frase":"La MBCT tiene su mejor evidencia en la prevención de ___ de depresión recurrente.","resp":["recaídas","recaida","recaídas de la depresión"]},{"frase":"En general, la ACT muestra eficacia ___ a la de la TCC tradicional.","resp":["comparable","similar","parecida"]}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"La unidad de análisis del contextualismo funcional es…","ops":["El acto en su contexto","El pensamiento aislado","La estructura del cerebro"],"correcta":0},{"p":"Un colega afirma que la ACT es superior a la TCC en todos los casos. Lo más preciso es responder que…","ops":["Tiene razón","La ACT no tiene evidencia","Las revisiones muestran eficacia comparable, no superioridad general"],"correcta":2,"explica":"Ser honesto con la evidencia protege a los consultantes y a la profesión."},{"p":"La DBT tiene su evidencia más sólida en…","ops":["Insomnio","Personas con diagnóstico de TLP con autolesiones o conducta suicida recurrente","Fobias específicas"],"correcta":1}]},{"tipo":"clave","items":["El contextualismo funcional juzga por lo que funciona para una meta, en su contexto.","ACT, DBT, activación conductual y MBCT tienen evidencia sólida en poblaciones concretas, no universal.","Presenta la evidencia sin inflarla y mide resultados con cada persona."]}]},{"id":"d-terapias-contextuales-m1-l4","titulo":"Lección 4 — Panorama de las terapias contextuales","objetivo":"distinguir el objetivo, el formato y la población principal de ACT, DBT, FAP, activación conductual, MBCT, MBSR y terapia centrada en la compasión.","bloques":[{"tipo":"tabla","titulo":"Mapa rápido","encabezados":["Terapia","Autores de referencia","Idea central","Formato típico"],"filas":[["ACT","Steven Hayes, Kirk Strosahl, Kelly Wilson","Flexibilidad psicológica: abrirse a la experiencia y actuar según valores","Individual o grupal; número de sesiones variable"],["DBT","Marsha Linehan","Equilibrar aceptación y cambio; enseñar habilidades de regulación","Terapia individual, grupo de habilidades, coaching telefónico y equipo de consulta"],["FAP","Robert Kohlenberg, Mavis Tsai","Usar la relación terapéutica para moldear conductas interpersonales","Individual, integrada con otros modelos"],["Activación conductual","Neil Jacobson, Christopher Martell, Sona Dimidjian","Romper la evitación y reconectar con reforzadores y valores","Individual o grupal, estructurada"],["MBSR","Jon Kabat-Zinn","Mindfulness para el estrés y el dolor","Programa grupal de 8 semanas"],["MBCT","Zindel Segal, Mark Williams, John Teasdale","Mindfulness más elementos de TCC para prevenir recaídas","Programa grupal de 8 semanas"],["Terapia centrada en la compasión (CFT)","Paul Gilbert","Cultivar la autocompasión frente a la vergüenza y la autocrítica","Individual o grupal"]]},{"tipo":"texto","texto":"<b>La terapia centrada en la compasión, en resumen.</b> Gilbert propone tres sistemas de regulación emocional: el de <b>amenaza</b> (protección), el de <b>logro o impulso</b> (búsqueda de recursos) y el de <b>calma y afiliación</b> (seguridad y conexión). En personas con mucha vergüenza y autocrítica, el sistema de amenaza domina y el de calma está poco desarrollado. La CFT entrena la compasión hacia uno mismo y hacia otros. Su evidencia es prometedora, aunque con estudios más pequeños que los de ACT o DBT; en este diplomado solo la mencionamos."},{"tipo":"relacionar","rotulo":"Relaciona cada terapia con su rasgo distintivo","pares":[["DBT","Coaching telefónico y grupo de habilidades"],["FAP","Conductas clínicamente relevantes en la sesión"],["MBCT","Prevención de recaídas en depresión recurrente"],["ACT","Seis procesos de flexibilidad psicológica"],["CFT","Sistemas de amenaza, logro y calma"]]},{"tipo":"tarjetas","rotulo":"Repasa conceptos","tarjetas":[{"frente":"Flexibilidad psicológica","reverso":"Capacidad de estar en contacto con el presente, abierto a la experiencia, y actuar según los propios valores."},{"frente":"Dialéctica","reverso":"En DBT, sostener dos verdades a la vez: te acepto como eres y necesitas cambiar."},{"frente":"Evitación experiencial","reverso":"Intentos de cambiar o escapar de pensamientos, emociones o sensaciones aunque cueste a largo plazo."},{"frente":"Mindfulness","reverso":"Prestar atención a propósito al momento presente, sin juzgar."}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"¿Qué terapia incluye un equipo de consulta para los terapeutas como parte del modelo estándar?","ops":["DBT","MBSR","CFT"],"correcta":0},{"p":"Un programa grupal de 8 semanas para personas con depresión recurrente en remisión corresponde a…","ops":["FAP","DBT","MBCT"],"correcta":2},{"p":"La activación conductual se enfoca sobre todo en…","ops":["Modificar creencias centrales","Romper la evitación y reconectar con actividades reforzantes","Analizar sueños"],"correcta":1}]},{"tipo":"reflexion","rotulo":"¿Por dónde empiezas?","pregunta":"Piensa en las personas que atiendes (o atenderás). ¿Qué terapia de este mapa te sería más útil estudiar a fondo primero y por qué?","ayuda":"La mayoría de mis consultantes… por eso me conviene…"},{"tipo":"clave","items":["ACT, DBT, FAP, activación conductual, MBSR, MBCT y CFT comparten el enfoque contextual pero difieren en objetivo y formato.","DBT estándar incluye cuatro componentes; MBSR y MBCT son programas grupales de 8 semanas.","La CFT trabaja la vergüenza y la autocrítica; su evidencia está en desarrollo."]}]}],"quiz":{"titulo":"Evaluación del módulo 1","preguntas":[{"p":"Según la ACBS, la certificación oficial de terapeuta ACT…","ops":["La otorga la SEP","Se obtiene con cualquier diplomado","La otorga el DBT-LBC","No existe"],"correcta":3},{"p":"El organismo que certifica clínicos y programas de DBT es…","ops":["CONOCER","La Sociedad Mexicana de Psicología","El DBT-Linehan Board of Certification","La ACBS"],"correcta":2},{"p":"El enfoque contextual pone más énfasis en…","ops":["La estructura cerebral","La función de la conducta y la relación con la experiencia interna","La veracidad de cada pensamiento","Los sueños y el inconsciente"],"correcta":1},{"p":"Salir de una reunión y sentir que baja la ansiedad es un ejemplo de…","ops":["Reforzamiento negativo","Castigo positivo","Extinción","Reforzamiento positivo"],"correcta":0},{"p":"El criterio de verdad del contextualismo funcional es…","ops":["Que coincida con la realidad objetiva","Que lo diga una autoridad","Que sea lógico","Que algo funcione para una meta definida"],"correcta":3},{"p":"Frente a la TCC tradicional, las revisiones muestran que la ACT tiene en general una eficacia…","ops":["Nula","Inferior en todos los casos","Comparable","Muy superior"],"correcta":2},{"p":"La terapia centrada en la compasión fue desarrollada por…","ops":["Aaron Beck","Paul Gilbert","Marsha Linehan","Jon Kabat-Zinn"],"correcta":1},{"p":"Quien no es psicólogo y toma este diplomado debe…","ops":["Usarlo para entender, acompañar y canalizar, sin dar psicoterapia","Aplicar DBT a sus conocidos","Diagnosticar con la matriz ACT","Anunciarse como terapeuta contextual"],"correcta":0}]}},{"id":"d-terapias-contextuales-m2","titulo":"Módulo 2 — Análisis funcional y formulación contextual","resumen":"El ABC funcional con consecuencias a corto y largo plazo, la evitación experiencial y su costo, la formulación del caso con la matriz ACT y un registro funcional en hoja de cálculo para encontrar patrones. Cuatro lecciones y una evaluación.","lecciones":[{"id":"d-terapias-contextuales-m2-l1","titulo":"Lección 1 — El ABC funcional paso a paso","objetivo":"realizar un análisis ABC funcional que distinga antecedentes internos y externos y consecuencias a corto y largo plazo.","bloques":[{"tipo":"texto","texto":"En el Diplomado en TCC usaste el ABC para unir situación, pensamiento y emoción. El <b>ABC funcional</b> tiene otro propósito: entender <b>qué mantiene</b> una conducta. <b>A</b> son los antecedentes (externos e internos: lugar, personas, hora, pensamientos, emociones, sensaciones), <b>B</b> es la conducta descrita de forma observable y <b>C</b> son las consecuencias, separando lo que pasa <b>de inmediato</b> y lo que pasa <b>a largo plazo</b>. La conducta suele mantenerse por las consecuencias inmediatas, aunque las de largo plazo sean costosas."},{"tipo":"pasos","rotulo":"Cómo hacer un análisis funcional","pasos":["<b>Define la conducta</b> en términos observables: «deja el celular sonar sin contestar», no «es irresponsable».","<b>Identifica antecedentes externos</b>: dónde, cuándo, con quién, qué acababa de pasar.","<b>Identifica antecedentes internos</b>: pensamientos, emociones, sensaciones, recuerdos, impulsos.","<b>Registra consecuencias inmediatas</b>: qué aparece o qué desaparece justo después.","<b>Registra consecuencias a largo plazo</b>: qué pasa con su vida, sus relaciones y sus valores si la conducta se repite.","<b>Plantea una hipótesis de función</b> (por ejemplo, escape del malestar) y verifícala con más registros, no con una sola escena."]},{"tipo":"tabla","titulo":"Caso ficticio: Rodrigo, 34 años, contador en Monterrey","encabezados":["Elemento","Descripción"],"filas":[["A externo","Lunes, 9 a. m.; llega el correo del director con correcciones al cierre del mes"],["A interno","«Otra vez la regué; me van a correr»; opresión en el pecho; vergüenza 8/10"],["B (conducta)","Cierra el correo, abre redes sociales y pospone la respuesta hasta el día siguiente"],["C inmediata","La opresión baja; la vergüenza pasa a 4/10 (reforzamiento negativo)"],["C a largo plazo","Se acumulan pendientes, el director insiste, aumenta la ansiedad del martes y Rodrigo se aleja de su valor de «ser confiable»"],["Hipótesis de función","Escape de la vergüenza y la ansiedad ante la crítica"]]},{"tipo":"plantilla","rotulo":"Plantilla de análisis funcional","texto":"Conducta (observable):\nAntecedentes externos (dónde, cuándo, con quién):\nAntecedentes internos (pensamientos, emociones, sensaciones):\nConsecuencias inmediatas (qué aparece o desaparece):\nConsecuencias a largo plazo (vida, relaciones, valores):\nHipótesis de función:\nQué datos faltan para confirmarla:","nota":"Llénala con la persona, no para ella: el análisis funcional es colaborativo."},{"tipo":"ordenar","rotulo":"Ordena el principio clave","items":[{"frase":"La conducta se mantiene por sus consecuencias inmediatas","es":"Por eso el alivio rápido es tan poderoso"}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"¿Cuál es una descripción observable de la conducta?","ops":["Pasa tres horas en el celular en lugar de estudiar","Es flojo","Tiene baja autoestima"],"correcta":0,"explica":"Las etiquetas no son conductas; describen a la persona, no lo que hace."},{"p":"En el caso de Rodrigo, la baja de la vergüenza justo después de posponer es…","ops":["Una consecuencia a largo plazo","Un antecedente interno","Una consecuencia inmediata que refuerza la evitación"],"correcta":2},{"p":"Una hipótesis de función se confirma mejor…","ops":["Con la opinión del terapeuta","Con varios registros en distintas situaciones","Con una sola escena muy clara"],"correcta":1}]},{"tipo":"clave","items":["El ABC funcional busca qué mantiene la conducta, no solo cómo se relacionan pensamiento y emoción.","Separa consecuencias inmediatas (suelen mantener la conducta) y a largo plazo (suelen mostrar el costo).","Describe conductas observables y confirma la hipótesis con varios registros."]}]},{"id":"d-terapias-contextuales-m2-l2","titulo":"Lección 2 — La evitación experiencial y su costo","objetivo":"identificar la evitación experiencial y evaluar su costo con la persona usando la pregunta de viabilidad.","bloques":[{"tipo":"texto","texto":"La <b>evitación experiencial</b> es la falta de disposición a estar en contacto con experiencias internas incómodas (pensamientos, emociones, recuerdos, sensaciones) y los intentos de cambiar su forma o frecuencia, <b>aun cuando eso cuesta</b> en la vida de la persona. El problema no es sentir ansiedad o tristeza; es que la lucha contra esas experiencias ocupa el lugar de lo que importa."},{"tipo":"lista","items":["<b>Supresión:</b> tratar de no pensar en algo (y pensarlo más).","<b>Escape situacional:</b> salir, no ir, cancelar.","<b>Distracción rígida:</b> series, celular o trabajo sin parar para no sentir.","<b>Consumo:</b> alcohol, cannabis, comida o compras para cambiar el estado interno.","<b>Rumiación y preocupación:</b> «darle vueltas» puede funcionar como evitación de emociones más intensas.","<b>Reaseguración:</b> preguntar una y otra vez «¿seguro que no pasa nada?»."]},{"tipo":"destacado","texto":"<b>No toda evitación es un problema.</b> Distraerte durante una espera en el hospital o dejar una discusión para mañana puede ser flexible y sano. Evalúa la <b>rigidez</b> (¿es la única respuesta?), la <b>frecuencia</b> y el <b>costo</b> en áreas valiosas. No conviertas «evitación» en otra etiqueta para la persona."},{"tipo":"tabla","titulo":"La pregunta de viabilidad (workability)","encabezados":["Pregunta al consultante","Para qué sirve"],"filas":[["¿Qué has intentado para quitarte esta ansiedad?","Hacer un inventario de estrategias de control"],["¿Cómo te funcionó a corto plazo?","Reconocer el alivio real, sin descalificarlo"],["¿Y a largo plazo? ¿La ansiedad se fue de tu vida?","Mostrar que el control no ha resuelto el problema"],["¿Qué te ha costado, en tiempo, relaciones o planes?","Conectar con el costo en valores"],["Si nada de esto ha funcionado, ¿qué te dice tu experiencia?","Abrir la puerta a una alternativa: la disposición"]],"nota":"En ACT a este proceso se le llama «desesperanza creativa». No busca que la persona se sienta sin esperanza, sino que suelte una estrategia que no le ha funcionado."},{"tipo":"comparar","titulo":"Dos posturas ante la ansiedad","malTitulo":"Agenda de control","mal":"«Primero tengo que quitarme los nervios; cuando esté tranquila, busco trabajo.»","bienTitulo":"Disposición","bien":"«Voy a ir a la entrevista con mis nervios; no tienen que irse para que yo haga lo que me importa.»"},{"tipo":"completar","rotulo":"Completa","items":[{"frase":"La evitación experiencial es un problema cuando es rígida y tiene un alto ___ en la vida de la persona.","resp":["costo","coste","precio"]},{"frase":"Intentar no pensar en algo suele hacer que se piense ___.","resp":["más","mas"]},{"frase":"A la alternativa al control, en ACT, se le llama aceptación o ___.","resp":["disposición","disposicion","apertura"]}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"¿Cuál ejemplo describe mejor la evitación experiencial?","ops":["Cancelar todas las reuniones para no sentir ansiedad, aunque pierda amistades","Distraerse con música en una fila larga","Dormirse temprano por cansancio"],"correcta":0},{"p":"La pregunta de viabilidad busca que la persona…","ops":["Admita que se equivoca","Deje de sentir emociones","Contraste el alivio a corto plazo con el costo a largo plazo"],"correcta":2},{"p":"La rumiación puede considerarse evitación cuando…","ops":["Dura menos de un minuto","Funciona para no contactar emociones más dolorosas y no lleva a acciones","Resuelve un problema concreto"],"correcta":1}]},{"tipo":"clave","items":["La evitación experiencial es luchar contra la experiencia interna aunque cueste en la vida.","Evalúa rigidez, frecuencia y costo; no toda evitación es problemática.","La pregunta de viabilidad contrasta el alivio inmediato con el costo a largo plazo."]}]},{"id":"d-terapias-contextuales-m2-l3","titulo":"Lección 3 — Formulación con la matriz ACT","objetivo":"construir una formulación contextual del caso con la matriz ACT y sus cuatro cuadrantes.","bloques":[{"tipo":"texto","texto":"La <b>matriz ACT</b> (Kevin Polk, Benjamin Schoendorff y colaboradores) es una forma visual y rápida de formular. Se dibujan dos ejes: el <b>vertical</b> separa la experiencia de los <b>cinco sentidos</b> (arriba: lo que se ve que haces) de la <b>experiencia mental</b> (abajo: lo que pasa dentro); el <b>horizontal</b> separa los movimientos de <b>alejamiento</b> (izquierda) de los de <b>acercamiento</b> a lo que importa (derecha). En el centro está el <b>tú que nota</b> todo esto."},{"tipo":"tabla","titulo":"Los cuatro cuadrantes","encabezados":["Cuadrante","Pregunta guía"],"filas":[["Abajo a la derecha: lo que importa","¿Quién y qué es importante para ti?"],["Abajo a la izquierda: lo interno que estorba","¿Qué pensamientos, emociones o recuerdos aparecen y te estorban?"],["Arriba a la izquierda: conductas de alejamiento","¿Qué haces, que se pueda ver, para alejarte de eso que estorba?"],["Arriba a la derecha: conductas de acercamiento","¿Qué harías, que se pueda ver, para acercarte a lo que importa?"]],"nota":"Suele llenarse en ese orden: primero lo que importa, luego lo que estorba, luego el alejamiento y al final el acercamiento."},{"tipo":"tabla","titulo":"Caso ficticio: Mariana, 27 años, diseñadora en Puebla","encabezados":["Cuadrante","Contenido"],"filas":[["Lo que importa","Crecer en su profesión, tener amigas cercanas, ser una hermana presente"],["Lo que estorba","«Van a ver que no soy buena», rubor, nudo en el estómago, recuerdo de burlas en la secundaria"],["Alejamiento","No presenta sus propuestas en juntas, cancela salidas, revisa diez veces sus diseños antes de enviarlos"],["Acercamiento","Presentar una propuesta en la junta del jueves, aceptar la comida del sábado, enviar el diseño con dos revisiones"]]},{"tipo":"plantilla","rotulo":"Matriz ACT para llenar en sesión","texto":"Arriba a la izquierda (lo que hago para alejarme):\nArriba a la derecha (lo que haría para acercarme):\nAbajo a la izquierda (lo que aparece dentro y estorba):\nAbajo a la derecha (quién y qué me importa):\nCentro (lo que noto al ver todo junto):\nPregunta de viabilidad: cuando hago lo de arriba a la izquierda, ¿me acerco o me alejo a lo de abajo a la derecha?"},{"tipo":"relacionar","rotulo":"¿A qué cuadrante va cada dato?","pares":[["Quiero ser una mamá paciente","Lo que importa"],["Siento un hueco en el estómago","Lo que estorba"],["Me encierro en el baño a revisar el celular","Alejamiento"],["Me siento a jugar con mi hijo 15 minutos","Acercamiento"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"En la matriz, el eje vertical distingue…","ops":["La experiencia de los cinco sentidos de la experiencia mental","Lo bueno de lo malo","El pasado del futuro"],"correcta":0},{"p":"«Revisar diez veces el diseño» va en…","ops":["Abajo a la derecha (lo que importa)","Abajo a la izquierda (lo que estorba)","Arriba a la izquierda (alejamiento)"],"correcta":2,"explica":"Es una conducta observable que funciona para alejarse del miedo a la crítica."},{"p":"Una ventaja de la matriz es que…","ops":["Da un diagnóstico","Se puede construir con la persona en una sola sesión y en lenguaje cotidiano","Sustituye la evaluación de riesgo"],"correcta":1}]},{"tipo":"clave","items":["La matriz ACT cruza sentidos/mente con alejamiento/acercamiento.","Se llena empezando por lo que importa y termina en conductas de acercamiento.","Complementa, pero no sustituye, la entrevista, la evaluación de riesgo y el análisis funcional."]}]},{"id":"d-terapias-contextuales-m2-l4","titulo":"Lección 4 — Registro funcional en hoja de cálculo","objetivo":"organizar un registro funcional en hoja de cálculo para detectar patrones de evitación y su alivio a corto plazo.","bloques":[{"tipo":"texto","texto":"Un registro funcional semanal permite pasar de anécdotas a <b>patrones</b>. Pide a la persona anotar cada episodio con la situación, lo que hizo, si fue alejamiento (evitación) o acercamiento, y su malestar antes y 10 minutos después. Con eso puedes mostrarle, con sus propios datos, por qué la evitación es tan tentadora: <b>alivia más rápido</b>."},{"tipo":"plantilla","rotulo":"Instrucciones para el consultante","texto":"Cada vez que notes malestar fuerte (7 de 10 o más), anota:\n1) Día y situación.\n2) Qué hiciste.\n3) Si te alejaste o te acercaste a lo que te importa.\n4) Tu malestar antes (0 a 10).\n5) Tu malestar 10 minutos después (0 a 10).\nNo tienes que cambiar nada esta semana: solo observar y anotar.","nota":"Pedir solo observar la primera semana reduce la presión y da una línea base más realista."},{"tipo":"excel","rotulo":"Registro funcional de Rodrigo (ficticio)","datos":[["Día","Situación (A)","Conducta (B)","Función","Malestar antes","Malestar 10 min después","Alivio inmediato"],["Lunes","Correo con correcciones","Cerrar la laptop y ver series","Evitación",8,3,""],["Martes","Invitación a comida familiar","Poner un pretexto por WhatsApp","Evitación",7,2,5],["Miércoles","Pendiente del reporte","Avanzar 20 minutos","Acercamiento",6,5,1],["Jueves","Discusión con su pareja","Caminar y luego hablar","Acercamiento",7,4,3],["Viernes","Llamada del banco","No contestar","Evitación",6,2,4],["Sábado","Reunión con amigos","Ir y quedarse una hora","Acercamiento",8,6,2],["","","","","","",""],["Episodios de evitación",""],["Alivio promedio con evitación",""],["Alivio promedio con acercamiento",""],["Lectura",""]],"retos":[{"celda":"G2","formula":"=E2-F2","esperado":5,"texto":"<b>G2</b>: calcula el alivio inmediato del lunes: malestar antes menos malestar después."},{"celda":"B9","formula":"=CONTAR.SI(D2:D7,\"Evitación\")","esperado":3,"requiere":"CONTAR.SI(","texto":"<b>B9</b>: cuenta cuántos episodios fueron de evitación con CONTAR.SI."},{"celda":"B10","formula":"=REDONDEAR(PROMEDIO.SI(D2:D7,\"Evitación\",G2:G7),2)","esperado":4.67,"requiere":"PROMEDIO.SI(","texto":"<b>B10</b>: promedio del alivio en los episodios de evitación, con PROMEDIO.SI y redondeado a 2 decimales.","pista":"=REDONDEAR(PROMEDIO.SI(D2:D7,\"Evitación\",G2:G7),2)"},{"celda":"B11","formula":"=PROMEDIO.SI(D2:D7,\"Acercamiento\",G2:G7)","esperado":2,"requiere":"PROMEDIO.SI(","texto":"<b>B11</b>: promedio del alivio en los episodios de acercamiento."},{"celda":"B12","formula":"=SI(B10>B11,\"La evitación alivia más rápido\",\"Revisar el registro\")","esperado":"La evitación alivia más rápido","requiere":"SI(","texto":"<b>B12</b>: con SI, si el alivio con evitación es mayor, escribe «La evitación alivia más rápido»; si no, «Revisar el registro».","explica":"Este es el reforzamiento negativo en números: evitar alivia casi 5 puntos; acercarse, solo 2. Por eso la evitación se repite. El trabajo es mostrar también el costo a largo plazo y la ganancia en valores del acercamiento."}]},{"tipo":"destacado","texto":"<b>Cuida los datos.</b> Los registros de salud mental son <b>datos personales sensibles</b>. Guárdalos en un archivo protegido con contraseña, no los compartas por grupos de mensajería y explica al consultante cómo se usarán, según tu aviso de privacidad y la ley de protección de datos personales vigente."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"En el registro, un alivio mayor con evitación que con acercamiento indica…","ops":["Que la evitación está reforzada negativamente","Que la evitación es la mejor estrategia","Un error en los datos"],"correcta":0},{"p":"La primera semana conviene pedir al consultante que…","ops":["Deje de evitar por completo","Registre únicamente los días buenos","Solo observe y anote"],"correcta":2},{"p":"Un registro funcional sirve sobre todo para…","ops":["Sustituir la entrevista","Pasar de anécdotas a patrones que se discuten con la persona","Diagnosticar un trastorno"],"correcta":1}]},{"tipo":"clave","items":["El registro funcional convierte episodios sueltos en patrones visibles.","CONTAR.SI y PROMEDIO.SI muestran con datos cuánto alivia la evitación frente al acercamiento.","Los registros son datos personales sensibles: protégelos."]}]}],"quiz":{"titulo":"Evaluación del módulo 2","preguntas":[{"p":"El objetivo principal del ABC funcional es…","ops":["Encontrar la distorsión cognitiva","Asignar un diagnóstico","Medir la inteligencia","Identificar qué mantiene una conducta"],"correcta":3},{"p":"¿Cuál es una conducta descrita de forma observable?","ops":["Tiene un apego inseguro","Es negativo","No contesta las llamadas de su madre","Es inmaduro"],"correcta":2},{"p":"Las conductas de evitación suelen mantenerse por…","ops":["La mala suerte","El alivio inmediato del malestar","Sus consecuencias a largo plazo","La falta de inteligencia"],"correcta":1},{"p":"La evitación experiencial es problemática cuando…","ops":["Es rígida y cuesta en áreas valiosas de la vida","Aparece una sola vez","Es una distracción breve","Ocurre en una sala de espera"],"correcta":0},{"p":"En la matriz ACT, las conductas de acercamiento van en…","ops":["Abajo a la izquierda","Arriba a la izquierda","El centro","Arriba a la derecha"],"correcta":3},{"p":"La pregunta de viabilidad contrasta…","ops":["El pasado con el futuro","Lo que piensa el terapeuta con lo que piensa el consultante","El alivio a corto plazo con el costo a largo plazo","Los pensamientos verdaderos y falsos"],"correcta":2},{"p":"En una hoja de cálculo, para promediar el alivio solo de los episodios de evitación usas…","ops":["MAX","PROMEDIO.SI","CONTAR.SI","SUMA"],"correcta":1},{"p":"Los registros de salud mental de un consultante son…","ops":["Datos personales sensibles que debes proteger","Información pública","Material para compartir en grupos de colegas sin permiso","Datos sin valor legal"],"correcta":0}]}},{"id":"d-terapias-contextuales-m3","titulo":"Módulo 3 — Terapia de aceptación y compromiso (ACT)","resumen":"Los seis procesos del hexaflex, ejercicios y metáforas de aceptación y defusión, contacto con el presente, yo como contexto, clarificación de valores con un cuestionario propio, acción comprometida y cómo medir la flexibilidad psicológica. Cuatro lecciones y una evaluación.","lecciones":[{"id":"d-terapias-contextuales-m3-l1","titulo":"Lección 1 — El hexaflex y la flexibilidad psicológica","objetivo":"explicar los seis procesos del hexaflex y reconocer su contraparte en el modelo de inflexibilidad psicológica.","bloques":[{"tipo":"texto","texto":"La meta de la ACT es la <b>flexibilidad psicológica</b>: estar en contacto con el momento presente como un ser humano consciente, abierto a lo que se siente y piensa, y <b>persistir o cambiar la conducta</b> según lo que se valora. El modelo se dibuja como un hexágono, el <b>hexaflex</b>, con seis procesos que se influyen entre sí. Cada uno tiene un «opuesto» que ayuda a formular el caso."},{"tipo":"tabla","titulo":"Los seis procesos y sus contrapartes","encabezados":["Proceso de flexibilidad","Qué es","Contraparte (inflexibilidad)"],"filas":[["<b>Aceptación</b>","Hacer espacio a emociones y sensaciones sin luchar contra ellas","Evitación experiencial"],["<b>Defusión cognitiva</b>","Ver los pensamientos como pensamientos, no como órdenes o verdades literales","Fusión cognitiva"],["<b>Momento presente</b>","Atención flexible a lo que pasa aquí y ahora","Rumiación del pasado o preocupación por el futuro"],["<b>Yo como contexto</b>","Perspectiva del «yo que observa», distinta de las historias sobre uno","Apego al yo conceptualizado («yo soy un fracasado»)"],["<b>Valores</b>","Direcciones de vida elegidas que dan sentido","Falta de claridad en valores, vivir por obligación o por evitar"],["<b>Acción comprometida</b>","Pasos concretos y sostenidos en dirección a los valores","Inacción, impulsividad o persistencia evitativa"]]},{"tipo":"destacado","texto":"<b>No es una lista de verificación.</b> Los procesos se trabajan juntos y en el orden que la formulación pida. Muchos clínicos los agrupan en tres: <b>abierto</b> (aceptación y defusión), <b>consciente</b> (presente y yo como contexto) y <b>comprometido</b> (valores y acción)."},{"tipo":"relacionar","rotulo":"Relaciona cada frase con el proceso de inflexibilidad","pares":[["«Soy un inútil, así soy y así seré»","Apego al yo conceptualizado"],["«Si pienso que voy a fallar, es que voy a fallar»","Fusión cognitiva"],["«No voy a ir hasta que se me quite la ansiedad»","Evitación experiencial"],["«Llevo meses sin hacer nada de lo que me importa»","Inacción"]]},{"tipo":"tarjetas","rotulo":"Repasa el hexaflex","tarjetas":[{"frente":"Abierto","reverso":"Aceptación y defusión: dejar de pelear con la experiencia interna."},{"frente":"Consciente","reverso":"Momento presente y yo como contexto: notar desde una perspectiva estable."},{"frente":"Comprometido","reverso":"Valores y acción comprometida: moverse hacia lo que importa."}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"La flexibilidad psicológica incluye…","ops":["Estar abierto a la experiencia y actuar según valores","Eliminar los pensamientos negativos","Controlar todas las emociones"],"correcta":0},{"p":"«Llevo diez años cuidando lo que otros esperan de mí, no sé qué quiero yo» apunta sobre todo a…","ops":["Fusión cognitiva","Momento presente","Falta de claridad en valores"],"correcta":2,"explica":"Sirve para empezar por la clarificación de valores."},{"p":"El opuesto de la defusión cognitiva es…","ops":["La acción comprometida","La fusión cognitiva","La aceptación"],"correcta":1}]},{"tipo":"clave","items":["La ACT busca flexibilidad psicológica: abrirse, estar presente y actuar según valores.","Hexaflex: aceptación, defusión, presente, yo como contexto, valores y acción comprometida.","Cada proceso tiene una contraparte de inflexibilidad útil para formular."]}]},{"id":"d-terapias-contextuales-m3-l2","titulo":"Lección 2 — Aceptación y defusión cognitiva en la práctica","objetivo":"aplicar ejercicios de aceptación y defusión cognitiva adaptados a la persona y a su formulación.","bloques":[{"tipo":"texto","texto":"La <b>aceptación</b> en ACT es activa: hacer espacio a una emoción o sensación incómoda para poder hacer lo que importa. La <b>defusión</b> no busca cambiar el contenido de un pensamiento, sino la <b>relación</b> con él: poder notar «estoy teniendo el pensamiento de que no sirvo» en lugar de vivir dentro de «no sirvo»."},{"tipo":"tabla","titulo":"Ejercicios y metáforas clásicas (descritas en nuestras palabras)","encabezados":["Nombre","En qué consiste","Proceso"],"filas":[["«Estoy teniendo el pensamiento de que…»","Añadir ese prefijo al pensamiento y notar si cambia algo en cómo se siente","Defusión"],["Repetir la palabra","Decir en voz alta una palabra cargada (por ejemplo, «fracaso») rápido durante unos 30 segundos hasta que suene solo a sonido","Defusión"],["Hojas en el río","Imaginar que cada pensamiento se coloca en una hoja que flota y se aleja, sin empujarla ni detenerla","Defusión y presente"],["La cuerda con el monstruo","La persona jala una cuerda contra un monstruo (su ansiedad) y cuanto más jala, más se cansa; la alternativa es soltar la cuerda, no ganar","Aceptación"],["Arenas movedizas","Forcejear hunde más; tenderse y ampliar el contacto con la superficie ayuda a no hundirse","Aceptación"],["Pasajeros del autobús","La persona maneja el autobús y los pensamientos son pasajeros que gritan; puede seguir su ruta aunque sigan ahí","Aceptación, defusión y valores"]],"nota":"Las metáforas se adaptan al lenguaje de cada persona: en México puede ser el microbús, el Metro o la combi."},{"tipo":"comparar","titulo":"Defusión frente a reestructuración","malTitulo":"Reestructuración (TCC clásica)","mal":"Pensamiento: «Voy a fracasar».<br>Pregunta: «¿Qué evidencia tienes? ¿Cuál sería un pensamiento más realista?»","bienTitulo":"Defusión (ACT)","bien":"Pensamiento: «Voy a fracasar».<br>Pregunta: «¿Puedes notar que tu mente te está contando la historia de siempre? ¿Qué harías si esa historia viniera contigo de pasajera?»"},{"tipo":"destacado","texto":"<b>Aceptación no es resignación.</b> Se acepta la <b>experiencia interna</b> (miedo, tristeza, recuerdos), no situaciones dañinas. Nadie debe «aceptar» violencia, abuso o condiciones de trabajo ilegales. Tampoco uses la defusión para minimizar un riesgo real: si alguien dice «me quiero morir», eso se evalúa como riesgo, no se «defusiona»."},{"tipo":"completar","rotulo":"Completa","items":[{"frase":"La defusión cambia la ___ con el pensamiento, no su contenido.","resp":["relación"]},{"frase":"En la metáfora de la cuerda, la alternativa no es ganar sino ___ la cuerda.","resp":["soltar"]},{"frase":"En ACT se acepta la experiencia ___, no las situaciones dañinas.","resp":["interna","privada"]}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Una consultante dice: «Soy una mala madre». Una respuesta de defusión sería…","ops":["«¿Notas que tu mente te está diciendo que eres mala madre? ¿Qué pasa cuando le crees de inmediato?»","«No es cierto, eres buena madre»","«¿Qué evidencia tienes a favor?»"],"correcta":0},{"p":"La metáfora de las arenas movedizas ilustra que…","ops":["Hay que salir corriendo del malestar","El malestar desaparece solo","Luchar contra la experiencia puede empeorarla"],"correcta":2},{"p":"Si una persona expresa ideas de muerte durante un ejercicio de defusión, lo adecuado es…","ops":["Pedirle que lo vea como una hoja en el río","Detener el ejercicio y evaluar el riesgo","Seguir con el ejercicio"],"correcta":1}]},{"tipo":"clave","items":["La defusión cambia la relación con el pensamiento; la aceptación hace espacio a la emoción.","Adapta las metáforas al lenguaje y la cultura de la persona.","Aceptar la experiencia interna no es aceptar el daño; el riesgo se evalúa, no se defusiona."]}]},{"id":"d-terapias-contextuales-m3-l3","titulo":"Lección 3 — Momento presente, yo como contexto y valores","objetivo":"guiar ejercicios de contacto con el presente y de yo observador, y clarificar valores con un cuestionario propio.","bloques":[{"tipo":"texto","texto":"El <b>contacto con el momento presente</b> se entrena con ejercicios breves de atención (notar cinco cosas que ves, la respiración, los pies en el piso) y, sobre todo, <b>dentro de la sesión</b>: «¿Qué notas ahora mismo al hablar de tu papá?». El <b>yo como contexto</b> es la perspectiva desde la que se notan pensamientos y emociones. Una metáfora frecuente es la del <b>cielo y el clima</b>: las tormentas pasan por el cielo, pero el cielo no se daña con ellas."},{"tipo":"tabla","titulo":"Valores frente a metas","encabezados":["Valores","Metas"],"filas":[["Direcciones: se viven, no se terminan","Destinos: se cumplen o no"],["«Ser una pareja cariñosa»","«Salir a cenar con mi pareja el viernes»"],["Elegidos por la persona","A veces impuestos por otros"],["Disponibles hoy, en pequeñas acciones","Dependen de resultados que no controlas del todo"]]},{"tipo":"plantilla","rotulo":"Cuestionario breve de valores (elaborado para este curso)","texto":"Para cada área, responde:\n1) ¿Qué tipo de persona quieres ser en esta área?\n2) ¿Qué tan importante es para ti? (1 a 10)\n3) ¿Qué tanto actuaste así en las últimas dos semanas? (1 a 10)\n4) ¿Qué pequeña acción de esta semana iría en esa dirección?\n\nÁreas: familia, pareja, amistades, trabajo o estudio, salud física, crecimiento personal, comunidad o espiritualidad, recreación.","nota":"No es un instrumento validado: es una guía de conversación. Para medir con rigor usa instrumentos publicados, con su versión en español y respetando sus condiciones de uso."},{"tipo":"destacado","texto":"<b>Valores de quién.</b> Cuida que la persona no elija lo que cree que el terapeuta quiere oír ni lo que «debe» valorar. Pregunta: «Si nadie se fuera a enterar, ¿esto seguiría siendo importante para ti?». Respeta valores culturales como la familia extensa o la fe, sin imponer los tuyos."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"¿Cuál es un valor y no una meta?","ops":["Cuidar mi salud","Bajar 5 kilos antes de diciembre","Correr el medio maratón de la CDMX"],"correcta":0},{"p":"La metáfora del cielo y el clima ilustra…","ops":["La acción comprometida","La exposición","El yo como contexto"],"correcta":2},{"p":"Para evitar que la persona elija valores por complacencia, puedes preguntar…","ops":["«¿Qué opino yo?»","«Si nadie se fuera a enterar, ¿seguiría siendo importante?»","«¿Qué valores tiene tu familia?»"],"correcta":1}]},{"tipo":"reflexion","rotulo":"Prueba el cuestionario contigo","pregunta":"Responde el cuestionario en dos áreas de tu vida. ¿Qué notaste al comparar la importancia con lo que realmente hiciste?","ayuda":"En el área de… la importancia es… pero actué… Una pequeña acción sería…"},{"tipo":"clave","items":["El presente y el yo como contexto se entrenan dentro de la sesión, no solo con ejercicios formales.","Los valores son direcciones elegidas; las metas son pasos que se cumplen.","Un cuestionario propio orienta la conversación; para medir usa instrumentos validados."]}]},{"id":"d-terapias-contextuales-m3-l4","titulo":"Lección 4 — Acción comprometida y medición de la flexibilidad","objetivo":"planear acciones comprometidas y medir en una hoja de cálculo la brecha entre valores y acciones.","bloques":[{"tipo":"texto","texto":"La <b>acción comprometida</b> son pasos concretos en dirección a los valores, que se sostienen <b>con</b> el malestar que aparezca. Se planean como metas pequeñas y medibles, se anticipan las barreras internas («¿qué pensamientos y emociones podrían aparecer?») y externas, y se revisan en la siguiente sesión sin juicio: si no se hizo, es información para el análisis funcional."},{"tipo":"destacado","texto":"<b>Medir la flexibilidad psicológica.</b> El instrumento más usado ha sido el <b>AAQ-II</b> (Bond y colaboradores, 2011): 7 ítems con escala de 1 a 7, donde una puntuación más alta indica más <b>inflexibilidad</b>. Tiene adaptaciones al español. Su principal crítica es que se traslapa mucho con el malestar emocional general, por lo que se han desarrollado otros instrumentos (por ejemplo, el CompACT o el MPFI). No reproducimos sus ítems: consulta la versión validada y sus condiciones de uso. Ninguno de ellos sirve para diagnosticar."},{"tipo":"excel","rotulo":"Brecha entre valores y acciones de Mariana (ficticio)","datos":[["Área","Importancia (1-10)","Congruencia (1-10)","Brecha","Prioridad"],["Familia",10,4,"",""],["Pareja",8,6,2,""],["Trabajo",7,7,0,""],["Amistades",8,3,5,"Prioridad"],["Salud física",9,5,4,"Prioridad"],["Crecimiento personal",6,6,0,""],["","","","",""],["Brecha promedio",""],["Áreas prioritarias",""],["Área con mayor brecha",""]],"retos":[{"celda":"D2","formula":"=B2-C2","esperado":6,"texto":"<b>D2</b>: brecha en familia: importancia menos congruencia."},{"celda":"E2","formula":"=SI(Y(B2>=8,D2>=4),\"Prioridad\",\"\")","esperado":"Prioridad","requiere":"Y(","texto":"<b>E2</b>: con SI y Y, marca «Prioridad» si la importancia es 8 o más y la brecha es 4 o más; si no, deja vacío (\"\")."},{"celda":"B9","formula":"=REDONDEAR(PROMEDIO(D2:D7),2)","esperado":2.83,"requiere":"PROMEDIO(","texto":"<b>B9</b>: brecha promedio de las seis áreas, redondeada a 2 decimales."},{"celda":"B10","formula":"=CONTAR.SI(E2:E7,\"Prioridad\")","esperado":3,"requiere":"CONTAR.SI(","texto":"<b>B10</b>: cuántas áreas quedaron como prioridad."},{"celda":"B11","formula":"=INDICE(A2:A7,COINCIDIR(MAX(D2:D7),D2:D7,0))","esperado":"Familia","requiere":"COINCIDIR(","texto":"<b>B11</b>: con INDICE, COINCIDIR y MAX, muestra el área con la brecha más grande.","pista":"=INDICE(A2:A7,COINCIDIR(MAX(D2:D7),D2:D7,0))","explica":"La brecha orienta dónde empezar la acción comprometida, pero la decisión es de la persona: tal vez prefiera empezar por amistades porque le parece más alcanzable."}]},{"tipo":"plantilla","rotulo":"Plan de acción comprometida","texto":"Valor: ser una hermana presente.\nAcción concreta: llamar a mi hermana el martes a las 8 p. m. por 15 minutos.\nBarreras internas que pueden aparecer: «no tengo nada interesante que contar», culpa por no haber llamado antes.\nQué haré con ellas: notarlas, nombrarlas y marcar de todos modos.\nBarreras externas: salir tarde del trabajo.\nPlan B: mandar un audio el miércoles en la mañana."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"En el AAQ-II, una puntuación más alta indica…","ops":["Más inflexibilidad psicológica","Más flexibilidad psicológica","Un diagnóstico de depresión"],"correcta":0},{"p":"Una crítica frecuente al AAQ-II es que…","ops":["Es demasiado largo","Solo existe en japonés","Se traslapa con el malestar emocional general"],"correcta":2},{"p":"Si la persona no hizo la acción comprometida, lo más útil es…","ops":["Dejar de plantear acciones","Analizar sin juicio qué pasó y qué barreras aparecieron","Regañarla"],"correcta":1}]},{"tipo":"clave","items":["La acción comprometida es concreta, medible y se sostiene con el malestar presente.","El AAQ-II mide inflexibilidad en general; tiene límites y no diagnostica.","La brecha importancia-congruencia orienta dónde actuar, pero decide la persona."]}]}],"quiz":{"titulo":"Evaluación del módulo 3","preguntas":[{"p":"¿Cuál NO es un proceso del hexaflex?","ops":["Defusión cognitiva","Yo como contexto","Acción comprometida","Reestructuración cognitiva"],"correcta":3},{"p":"La contraparte de la aceptación en el modelo de inflexibilidad es…","ops":["La inacción","La falta de valores","La evitación experiencial","La fusión cognitiva"],"correcta":2},{"p":"Decir «estoy teniendo el pensamiento de que no sirvo» es un ejercicio de…","ops":["Relajación","Defusión cognitiva","Exposición interoceptiva","Reestructuración"],"correcta":1},{"p":"En ACT, aceptar significa…","ops":["Hacer espacio a la experiencia interna para actuar según valores","Resignarse a cualquier situación","Aguantar la violencia","Dejar de sentir"],"correcta":0},{"p":"«Salir a correr tres veces esta semana» es…","ops":["Un valor","Un proceso del hexaflex","Una medida de flexibilidad","Una meta al servicio de un valor"],"correcta":3},{"p":"El AAQ-II tiene…","ops":["3 ítems de 0 a 100","50 ítems","7 ítems con escala de 1 a 7","20 ítems de sí o no"],"correcta":2},{"p":"Si una persona expresa ideas de muerte durante un ejercicio, lo adecuado es…","ops":["Asignar una tarea de valores","Evaluar el riesgo de inmediato","Seguir con la defusión","Cambiar de tema"],"correcta":1},{"p":"Para mostrar el área con la brecha más grande en una hoja de cálculo puedes usar…","ops":["INDICE con COINCIDIR y MAX","SUMA con CONTAR","IZQUIERDA con LARGO","PROMEDIO con MIN"],"correcta":0}]}},{"id":"d-terapias-contextuales-m4","titulo":"Módulo 4 — Terapia dialéctica conductual (DBT)","resumen":"El modelo biosocial y la dialéctica entre aceptación y cambio, los cuatro módulos de habilidades (mindfulness, tolerancia al malestar con STOP y TIPP, regulación emocional y efectividad interpersonal con DEAR MAN, GIVE y FAST), la tarjeta diaria en hoja de cálculo, para quién está indicada y el manejo del riesgo suicida. Cuatro lecciones y una evaluación.","lecciones":[{"id":"d-terapias-contextuales-m4-l1","titulo":"Lección 1 — Modelo biosocial y dialéctica","objetivo":"explicar el modelo biosocial de la desregulación emocional y la dialéctica entre aceptación y cambio.","bloques":[{"tipo":"texto","texto":"Marsha Linehan desarrolló la <b>terapia dialéctica conductual</b> (DBT) para personas con conducta suicida crónica y diagnóstico de trastorno límite de la personalidad (TLP). Su <b>modelo biosocial</b> propone que la desregulación emocional surge de la <b>transacción</b> entre una <b>vulnerabilidad emocional</b> de base biológica y un <b>ambiente invalidante</b>. Ninguno de los dos, por sí solo, lo explica todo."},{"tipo":"tabla","titulo":"Los componentes del modelo biosocial","encabezados":["Componente","Qué significa","Ejemplo"],"filas":[["Alta sensibilidad","Reacciona a estímulos emocionales con umbral bajo","Un comentario neutro se vive como rechazo"],["Alta reactividad","Las emociones son muy intensas","La tristeza sube de 2 a 9 en minutos"],["Regreso lento a la línea base","Tarda en recuperarse","El enojo dura toda la tarde"],["Ambiente invalidante","Se descalifica, castiga o ignora la experiencia emocional","«Estás exagerando», «ya deja el drama»"]],"nota":"El modelo es transaccional: la persona y su entorno se influyen mutuamente con el tiempo."},{"tipo":"destacado","texto":"<b>Sin culpas y sin etiquetas.</b> El modelo no busca culpar a la familia, que muchas veces hizo lo que pudo con lo que sabía. Usa lenguaje respetuoso: «persona con diagnóstico de TLP», no «es limítrofe» ni «es manipuladora». En DBT se asume que las personas hacen lo mejor que pueden <b>y</b> necesitan aprender a hacerlo diferente."},{"tipo":"texto","texto":"La <b>dialéctica</b> es el corazón del modelo: sostener dos verdades opuestas a la vez y buscar una síntesis. La más importante es <b>aceptación y cambio</b>: «Te acepto tal como estás hoy, y necesitas cambiar para tener una vida que valga la pena vivir». Por eso la DBT combina estrategias de <b>validación</b> (aceptación) con técnicas conductuales de <b>solución de problemas</b> (cambio)."},{"tipo":"comparar","titulo":"Validar frente a invalidar","malTitulo":"Invalidante","mal":"Consultante: «Me dejó en visto y sentí que me iba a morir».<br>Terapeuta: «Pero si nada más fue un mensaje; no es para tanto.»","bienTitulo":"Validante (y orientada al cambio)","bien":"Consultante: «Me dejó en visto y sentí que me iba a morir».<br>Terapeuta: «Con lo que has vivido, tiene sentido que el silencio te suene a abandono. Y vamos a ver qué hiciste después, porque ahí podemos trabajar.»"},{"tipo":"relacionar","rotulo":"Relaciona el concepto","pares":[["Vulnerabilidad emocional","Sensibilidad, reactividad y regreso lento"],["Ambiente invalidante","Descalificar la experiencia emocional"],["Dialéctica","Sostener aceptación y cambio a la vez"],["Validación","Comunicar que la experiencia tiene sentido"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Según el modelo biosocial, la desregulación emocional surge de…","ops":["La transacción entre vulnerabilidad emocional y ambiente invalidante","Solo la genética","Solo la mala crianza"],"correcta":0,"explica":"El modelo es transaccional, no de culpa."},{"p":"Validar significa…","ops":["Estar de acuerdo con toda conducta","Evitar hablar de cambio","Comunicar que la experiencia tiene sentido en su contexto"],"correcta":2},{"p":"¿Qué frase respeta a la persona?","ops":["Es manipuladora","Persona con diagnóstico de TLP","Es una limítrofe"],"correcta":1}]},{"tipo":"clave","items":["Modelo biosocial: vulnerabilidad emocional en transacción con un ambiente invalidante.","La dialéctica central de la DBT es aceptación y cambio.","Valida la experiencia sin validar toda conducta, y usa lenguaje respetuoso."]}]},{"id":"d-terapias-contextuales-m4-l2","titulo":"Lección 2 — Mindfulness y tolerancia al malestar: STOP y TIPP","objetivo":"enseñar las habilidades de mindfulness y de tolerancia al malestar, incluidas STOP y TIPP, con sus precauciones.","bloques":[{"tipo":"texto","texto":"La DBT estándar tiene cuatro componentes: <b>terapia individual</b>, <b>grupo de entrenamiento en habilidades</b>, <b>coaching telefónico</b> entre sesiones y <b>equipo de consulta</b> para los terapeutas. Las habilidades se agrupan en cuatro módulos: <b>mindfulness</b>, <b>tolerancia al malestar</b>, <b>regulación emocional</b> y <b>efectividad interpersonal</b>. El mindfulness es la base de los otros tres."},{"tipo":"tabla","titulo":"Mindfulness en DBT","encabezados":["Habilidad","Qué es"],"filas":[["<b>Mente sabia</b>","La síntesis entre la «mente emocional» y la «mente racional»"],["Habilidades «qué»","<b>Observar</b>, <b>describir</b> y <b>participar</b>"],["Habilidades «cómo»","<b>Sin juzgar</b>, <b>una cosa a la vez</b> y con <b>efectividad</b> (hacer lo que funciona)"]]},{"tipo":"tabla","titulo":"Dos habilidades de crisis","encabezados":["Siglas (del inglés)","Pasos"],"filas":[["<b>STOP</b>","<b>Para</b> (no reacciones, quédate quieto); <b>toma distancia</b> (da un paso atrás, respira); <b>observa</b> lo que pasa dentro y fuera; <b>procede</b> con atención, pensando en tus metas"],["<b>TIPP</b>","<b>Temperatura</b> (agua fría en la cara para bajar la activación); <b>ejercicio intenso</b> breve; <b>respiración pausada</b> (exhalar más lento que inhalar); <b>relajación muscular</b> apareada con la exhalación"]],"nota":"Las habilidades de crisis sirven para <b>no empeorar la situación</b> en el momento; no resuelven el problema de fondo."},{"tipo":"destacado","texto":"<b>Precauciones con TIPP.</b> El agua fría y el ejercicio intenso cambian la frecuencia cardiaca. Quien tenga problemas del corazón, frecuencia cardiaca baja, un trastorno de la conducta alimentaria u otra condición médica debe consultarlo con su médico antes de usarlos. Enseña primero la respiración pausada, que tiene menos riesgos."},{"tipo":"texto","texto":"Otras habilidades de tolerancia al malestar son la <b>aceptación radical</b> (aceptar por completo una realidad que no se puede cambiar ahora, sin aprobarla), las listas de <b>pros y contras</b> de actuar el impulso, la <b>distracción</b> planeada y el <b>autocalmarse</b> con los cinco sentidos."},{"tipo":"relacionar","rotulo":"¿Qué habilidad es?","pares":[["Meter la cara en agua fría unos segundos","TIPP"],["Quedarse quieto y dar un paso atrás antes de responder","STOP"],["Integrar la emoción y la razón","Mente sabia"],["Reconocer que algo ocurrió aunque no lo apruebes","Aceptación radical"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Las habilidades de crisis sirven sobre todo para…","ops":["No empeorar la situación en el momento","Resolver el problema de fondo","Sustituir la terapia individual"],"correcta":0},{"p":"Antes de enseñar la parte de temperatura de TIPP conviene…","ops":["Pedir que lo hagan con hielo por un minuto","Omitir la respiración","Preguntar por condiciones cardiacas o alimentarias"],"correcta":2},{"p":"¿Cuál es una habilidad «cómo» del mindfulness DBT?","ops":["Describir","Sin juzgar","Observar"],"correcta":1}]},{"tipo":"clave","items":["DBT estándar: terapia individual, grupo de habilidades, coaching telefónico y equipo de consulta.","STOP y TIPP ayudan a atravesar una crisis sin empeorarla.","Revisa condiciones médicas antes de usar temperatura o ejercicio intenso."]}]},{"id":"d-terapias-contextuales-m4-l3","titulo":"Lección 3 — Regulación emocional y la tarjeta diaria","objetivo":"aplicar habilidades de regulación emocional y analizar una tarjeta diaria de DBT en una hoja de cálculo.","bloques":[{"tipo":"texto","texto":"El módulo de <b>regulación emocional</b> enseña a entender y nombrar emociones, reducir la vulnerabilidad y cambiar emociones cuando no ayudan. Tres habilidades clave: <b>verificar los hechos</b> (¿la emoción y su intensidad encajan con lo que pasó?), <b>acción opuesta</b> (actuar contrario al impulso cuando la emoción no encaja con los hechos) y el cuidado de la base física: tratar enfermedades, comer y dormir de forma equilibrada, evitar sustancias que alteran el ánimo y hacer ejercicio."},{"tipo":"tabla","titulo":"Acción opuesta: ejemplos","encabezados":["Emoción","Impulso","Acción opuesta (si no encaja con los hechos)"],"filas":[["Miedo","Evitar","Acercarse poco a poco"],["Tristeza","Aislarse","Activarse y buscar contacto"],["Enojo","Atacar","Alejarse con amabilidad o ser gentil"],["Vergüenza","Esconderse","Mostrarse, si no hay riesgo de rechazo real"]]},{"tipo":"texto","texto":"La <b>tarjeta diaria</b> (diary card) es un registro que la persona llena cada día: intensidad de emociones, impulsos y conductas objetivo (por ejemplo, impulso de autolesión) y habilidades usadas. Se revisa al inicio de cada sesión para decidir la agenda según la <b>jerarquía de objetivos</b>: primero conductas que ponen en riesgo la vida, luego las que interfieren con la terapia y después las que afectan la calidad de vida."},{"tipo":"excel","rotulo":"Tarjeta diaria de Daniela (ficticio)","datos":[["Día","Tristeza (0-5)","Enojo (0-5)","Impulso de autolesión (0-5)","¿Autolesión?","Habilidades usadas","Habilidad principal"],["Lunes",3,2,3,"No",2,"STOP"],["Martes",4,4,4,"No",1,"TIPP"],["Miércoles",2,1,1,"No",3,"Mente sabia"],["Jueves",4,3,2,"No",2,"DEAR MAN"],["Viernes",5,4,4,"No",1,"TIPP"],["Sábado",2,2,2,"No",3,"Acción opuesta"],["Domingo",1,1,1,"No",2,"Mente sabia"],["","","","","","",""],["Promedio de impulso",""],["Días con impulso de 4 o más",""],["Total de habilidades",""],["Habilidades en días de impulso alto",""],["Alerta para la sesión",""]],"retos":[{"celda":"B10","formula":"=REDONDEAR(PROMEDIO(D2:D8),2)","esperado":2.43,"requiere":"PROMEDIO(","texto":"<b>B10</b>: promedio del impulso de autolesión en la semana, redondeado a 2 decimales."},{"celda":"B11","formula":"=CONTAR.SI(D2:D8,\">=4\")","esperado":2,"requiere":"CONTAR.SI(","texto":"<b>B11</b>: cuenta los días con impulso de 4 o más.","pista":"=CONTAR.SI(D2:D8,\">=4\")"},{"celda":"B12","formula":"=SUMA(F2:F8)","esperado":14,"requiere":"SUMA(","texto":"<b>B12</b>: total de habilidades usadas en la semana."},{"celda":"B13","formula":"=SUMAR.SI(D2:D8,\">=4\",F2:F8)","esperado":2,"requiere":"SUMAR.SI(","texto":"<b>B13</b>: con SUMAR.SI, suma las habilidades usadas solo en los días con impulso de 4 o más."},{"celda":"B14","formula":"=SI(MAX(D2:D8)>=4,\"Revisar en sesión\",\"Sin alerta\")","esperado":"Revisar en sesión","requiere":"MAX(","texto":"<b>B14</b>: con SI y MAX, escribe «Revisar en sesión» si algún día el impulso llegó a 4 o más; si no, «Sin alerta».","explica":"Daniela no se autolesionó, pero en los días de impulso alto usó pocas habilidades (una por día). Eso va primero en la agenda: reforzar lo que sí funcionó y planear qué hacer la próxima vez. Si el impulso alto viene con plan o intención, se sigue el protocolo de riesgo de la lección siguiente."}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"La acción opuesta se usa cuando…","ops":["La emoción o su intensidad no encajan con los hechos","Cualquier emoción aparece","La persona está en riesgo inminente"],"correcta":0},{"p":"En la jerarquía de objetivos de la DBT, lo primero en la agenda son…","ops":["Las conductas que interfieren con la terapia","Las metas laborales","Las conductas que ponen en riesgo la vida"],"correcta":2},{"p":"La tarjeta diaria se revisa…","ops":["Cuando la persona quiera","Al inicio de cada sesión","Solo al final del tratamiento"],"correcta":1}]},{"tipo":"clave","items":["Regulación emocional: verificar los hechos, acción opuesta y cuidar la base física.","La tarjeta diaria registra emociones, impulsos, conductas objetivo y habilidades.","La jerarquía de objetivos pone primero lo que amenaza la vida."]}]},{"id":"d-terapias-contextuales-m4-l4","titulo":"Lección 4 — Efectividad interpersonal, indicaciones y riesgo suicida","objetivo":"aplicar DEAR MAN, GIVE y FAST, reconocer para quién está indicada la DBT y actuar ante el riesgo suicida.","bloques":[{"tipo":"tabla","titulo":"DEAR MAN: pedir algo o decir que no","encabezados":["Letra (inglés)","Qué hacer","Ejemplo"],"filas":[["<b>D</b>escribe","Describe los hechos sin juicios","«Esta semana llegué tres días después de las 8 p. m.»"],["<b>E</b>xpresa","Expresa lo que sientes y piensas","«Me siento agotada»"],["<b>A</b>firma","Pide con claridad o di que no","«Necesito salir a las 6 al menos tres días»"],["<b>R</b>efuerza","Explica qué gana la otra persona","«Así rindo mejor en la mañana»"],["<b>M</b>antente atento","No te desvíes; repite si hace falta","«Entiendo, y necesito salir a las 6»"],["<b>A</b>parenta seguridad","Tono y postura firmes","Mirar a los ojos, voz clara"],["<b>N</b>egocia","Busca alternativas","«¿Qué días te acomodan?»"]]},{"tipo":"tabla","titulo":"GIVE y FAST","encabezados":["Habilidad","Para qué","Qué incluye"],"filas":[["<b>GIVE</b>","Cuidar la relación","Ser <b>gentil</b>, mostrar <b>interés</b>, <b>validar</b> y tener un trato <b>tranquilo</b> (easy manner)"],["<b>FAST</b>","Cuidar el respeto a uno mismo","Ser <b>justo</b> (fair), <b>no disculparse de más</b>, <b>sostener tus valores</b> y ser <b>veraz</b>"]]},{"tipo":"tabla","titulo":"¿Para quién está indicada la DBT?","encabezados":["Población","Nivel de evidencia (resumen)"],"filas":[["Adultos con diagnóstico de TLP y autolesiones o conducta suicida recurrente","La más sólida; es la población original del modelo"],["Adolescentes con autolesiones repetidas y desregulación emocional (DBT-A)","Buena evidencia; guías como NICE la consideran en este grupo"],["Otras condiciones (trastornos alimentarios, consumo de sustancias, TDAH en adultos)","Adaptaciones con evidencia menor o en desarrollo"]],"nota":"Un grupo de habilidades por sí solo no es DBT completa. Revisa las guías vigentes al momento de indicar tratamiento."},{"tipo":"destacado","texto":"<b>Riesgo suicida: lo que no puede faltar.</b> Pregunta de forma directa por ideas, planes, intención y acceso a medios; preguntar <b>no</b> aumenta el riesgo. Si hay <b>riesgo inminente</b>, no dejes sola a la persona y llama al <b>911</b> o acompáñala a urgencias. Para orientación y apoyo, la <b>Línea de la Vida 800 911 2000</b> es gratuita, confidencial y funciona las <b>24 horas</b>. El coaching telefónico de la DBT <b>no sustituye</b> los servicios de emergencia. Si no tienes formación en manejo de crisis, deriva y consulta a tu supervisor."},{"tipo":"pasos","rotulo":"Protocolo básico ante ideación suicida en sesión","pasos":["Pregunta directo: «¿Has pensado en quitarte la vida?».","Evalúa plan, intención, acceso a medios, intentos previos y factores de protección.","Si el riesgo es inminente: no dejes sola a la persona, llama al 911 o acompáñala a urgencias.","Si no es inminente: elabora con ella un plan de seguridad por escrito (señales, estrategias, contactos, Línea de la Vida, quitar medios).","Involucra a una persona de apoyo si la persona lo acepta.","Documenta en el expediente y consulta con tu supervisor o equipo."]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"«No me voy a disculpar por pedir mis vacaciones» corresponde a…","ops":["FAST","GIVE","TIPP"],"correcta":0},{"p":"Preguntar directamente por ideas suicidas…","ops":["Siempre aumenta el riesgo","Solo lo puede hacer un psiquiatra","No aumenta el riesgo y es necesario"],"correcta":2},{"p":"Una persona dice que tiene un plan y los medios para quitarse la vida hoy. Lo adecuado es…","ops":["Agendar cita para la próxima semana","No dejarla sola y llamar al 911 o acompañarla a urgencias","Darle la Línea de la Vida y terminar la sesión"],"correcta":1}]},{"tipo":"clave","items":["DEAR MAN para pedir o negarse; GIVE cuida la relación; FAST cuida el respeto a uno mismo.","La DBT tiene su mejor evidencia en conducta suicida y autolesiones con desregulación emocional.","Riesgo inminente: no dejes sola a la persona y llama al 911; Línea de la Vida 800 911 2000, 24 horas."]}]}],"quiz":{"titulo":"Evaluación del módulo 4","preguntas":[{"p":"El modelo biosocial explica la desregulación emocional como…","ops":["Un defecto de carácter","Un problema solo genético","Falta de voluntad","La transacción entre vulnerabilidad emocional y ambiente invalidante"],"correcta":3},{"p":"La dialéctica central de la DBT es…","ops":["Pasado y futuro","Cuerpo y mente","Aceptación y cambio","Razón y fe"],"correcta":2},{"p":"¿Cuál NO es un componente de la DBT estándar?","ops":["Equipo de consulta","Hipnosis grupal","Grupo de habilidades","Coaching telefónico"],"correcta":1},{"p":"La «P» de STOP indica…","ops":["Proceder con atención","Pelear","Pensar en el pasado","Pedir perdón"],"correcta":0},{"p":"Antes de usar agua fría (TIPP) conviene descartar…","ops":["Miopía","Alergia al polen","Insomnio leve","Problemas cardiacos o trastornos de la conducta alimentaria"],"correcta":3},{"p":"La acción opuesta al miedo que no encaja con los hechos es…","ops":["Atacar","Esconderse","Acercarse poco a poco","Evitar"],"correcta":2},{"p":"DEAR MAN sirve sobre todo para…","ops":["Diagnosticar TLP","Pedir algo o decir que no con eficacia","Regular la temperatura corporal","Medir el ánimo"],"correcta":1},{"p":"El número de la Línea de la Vida es…","ops":["800 911 2000","911 800 2000","800 290 0024","089"],"correcta":0}]}},{"id":"d-terapias-contextuales-m5","titulo":"Módulo 5 — Activación conductual, FAP y mindfulness con evidencia","resumen":"La activación conductual contextual para la depresión con programación de actividades guiada por valores, sus obstáculos frecuentes, la psicoterapia analítica funcional y las conductas clínicamente relevantes en la sesión, y lo que realmente dice la evidencia sobre el mindfulness. Cuatro lecciones y una evaluación.","lecciones":[{"id":"d-terapias-contextuales-m5-l1","titulo":"Lección 1 — Activación conductual guiada por valores","objetivo":"programar actividades guiadas por valores y medir su efecto en el ánimo con una hoja de cálculo.","bloques":[{"tipo":"texto","texto":"En el Diplomado en TCC viste la programación de actividades de placer y dominio. La <b>activación conductual</b> contextual (Martell, Dimidjian y colaboradores) va un paso más allá: parte de que en la depresión la vida pierde fuentes de reforzamiento y la persona responde con <b>evitación</b> (quedarse en cama, aislarse, rumiar), que alivia a corto plazo pero reduce aún más el reforzamiento. El trabajo es <b>analizar la función</b> de esas conductas y reemplazarlas por acciones conectadas con lo que importa, <b>de afuera hacia adentro</b>: actuar aunque no haya ganas, sin esperar a sentirse mejor."},{"tipo":"tabla","titulo":"De TRAP a TRAC","encabezados":["Paso","Pregunta","Ejemplo (Lucía, 41 años, Toluca)"],"filas":[["<b>T</b>rigger (disparador)","¿Qué pasó?","Le negaron el ascenso"],["<b>R</b>esponse (respuesta)","¿Qué sentiste?","Tristeza y cansancio"],["<b>A</b>voidance <b>P</b>attern (patrón de evitación)","¿Qué hiciste para no sentir?","Se acostó toda la tarde y canceló la comida con su hermana"],["<b>A</b>lternative <b>C</b>oping (afrontamiento alternativo)","¿Qué podrías hacer en su lugar?","Caminar 15 minutos y mantener la comida, aunque sea una hora"]]},{"tipo":"excel","rotulo":"Programación de actividades de Lucía (ficticio)","datos":[["Día","Actividad","Valor","Estado","Ánimo antes (0-10)","Ánimo después (0-10)","Cambio"],["Lunes","Caminar 20 minutos","Salud","Hecha",3,5,""],["Martes","Llamar a mi hermana","Familia","Hecha",4,6,2],["Miércoles","Enviar un CV","Trabajo","No hecha",3,3,0],["Jueves","Cocinar con mi hijo","Familia","Hecha",4,7,3],["Viernes","Ir al grupo de corredores","Salud","No hecha",3,3,0],["Sábado","Comida con amigas","Amistad","Hecha",5,7,2],["","","","","","",""],["Actividades hechas",""],["Porcentaje de cumplimiento",""],["Cambio promedio en actividades hechas",""],["Actividades de familia hechas",""]],"retos":[{"celda":"G2","formula":"=F2-E2","esperado":2,"texto":"<b>G2</b>: cambio de ánimo del lunes: después menos antes."},{"celda":"B9","formula":"=CONTAR.SI(D2:D7,\"Hecha\")","esperado":4,"requiere":"CONTAR.SI(","texto":"<b>B9</b>: cuenta las actividades con estado «Hecha»."},{"celda":"B10","formula":"=REDONDEAR(B9/CONTARA(D2:D7)*100,0)","esperado":67,"requiere":"CONTARA(","texto":"<b>B10</b>: porcentaje de cumplimiento: hechas entre el total de actividades (CONTARA) por 100, redondeado a entero."},{"celda":"B11","formula":"=PROMEDIO.SI(D2:D7,\"Hecha\",G2:G7)","esperado":2.25,"requiere":"PROMEDIO.SI(","texto":"<b>B11</b>: cambio promedio de ánimo solo en las actividades hechas."},{"celda":"B12","formula":"=CONTAR.SI.CONJUNTO(C2:C7,\"Familia\",D2:D7,\"Hecha\")","esperado":2,"requiere":"CONTAR.SI.CONJUNTO(","texto":"<b>B12</b>: con CONTAR.SI.CONJUNTO, cuenta las actividades de familia que sí se hicieron.","explica":"Las actividades hechas subieron el ánimo en promedio 2.25 puntos. Las dos que no se hicieron eran más difíciles (CV y grupo nuevo): la siguiente semana conviene partirlas en pasos más pequeños."}]},{"tipo":"destacado","texto":"<b>Evidencia y límites.</b> La activación conductual tiene buena evidencia en depresión: en el ensayo COBRA (Reino Unido, 2016), aplicada por personal con menos formación, no fue inferior a la TCC. Aun así, en depresión moderada o grave coordina con un médico, que es quien valora el tratamiento farmacológico, y evalúa siempre el riesgo suicida. Si aparece riesgo, sigue el protocolo del módulo 4."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"En la activación conductual, «de afuera hacia adentro» significa…","ops":["Actuar según el plan aunque no haya ganas, sin esperar a sentirse mejor","Esperar a tener motivación para actuar","Cambiar primero los pensamientos"],"correcta":0},{"p":"En TRAP, la «AP» se refiere a…","ops":["El afrontamiento alternativo","El disparador","El patrón de evitación"],"correcta":2},{"p":"Si una actividad planeada no se hizo, lo más útil es…","ops":["Asignar tres actividades más difíciles","Analizar qué la bloqueó y dividirla en pasos más pequeños","Quitarla de la lista para siempre"],"correcta":1}]},{"tipo":"clave","items":["La activación conductual analiza la función de la evitación y la reemplaza por acciones con valor.","TRAP describe el patrón de evitación; TRAC, la alternativa.","Mide cumplimiento y cambio de ánimo, y parte en pasos pequeños lo que no se logra."]}]},{"id":"d-terapias-contextuales-m5-l2","titulo":"Lección 2 — Obstáculos frecuentes en la activación conductual","objetivo":"resolver obstáculos frecuentes de la activación conductual, incluida la rumiación como conducta de evitación.","bloques":[{"tipo":"texto","texto":"La activación conductual parece sencilla, y ahí está su trampa: <b>no es solo «haz cosas bonitas»</b>. Fracasa cuando las actividades no se eligen por su función ni por los valores de la persona, cuando son demasiado grandes o cuando se ignora que la rumiación también es una conducta que se puede analizar."},{"tipo":"tabla","titulo":"Obstáculos y qué hacer","encabezados":["Obstáculo","Qué hacer"],"filas":[["«No tengo ganas»","Recordar el principio de afuera hacia adentro; empezar con 5 o 10 minutos"],["La actividad es demasiado grande","Graduarla: «buscar trabajo» se vuelve «actualizar una sección del CV»"],["Rumiación («¿por qué me pasa esto?»)","Analizar su función: ¿te ayuda a resolver algo o te aleja de actuar? Redirigir la atención a la experiencia de la actividad"],["La actividad no se conecta con nada importante","Revisar valores: una actividad «agradable» genérica puede no ser reforzante para esa persona"],["Obstáculos del contexto (dinero, tiempo, cuidado de hijos)","Buscar alternativas accesibles y gratuitas; resolver problemas con la persona"]]},{"tipo":"comparar","titulo":"Dos formas de asignar la tarea","malTitulo":"Genérica","mal":"«Esta semana haz algo que te guste, como ir al cine o al gimnasio.»","bienTitulo":"Funcional y graduada","bien":"«Dijiste que la familia es lo más importante y que cancelas las comidas con tu hermana. ¿Qué tal si el domingo vas una hora, aunque no tengas ganas, y anotas tu ánimo antes y después?»"},{"tipo":"ordenar","rotulo":"Ordena la pregunta funcional sobre la rumiación","items":[{"frase":"Darle vueltas te acerca o te aleja de actuar","es":"La rumiación se analiza por su función"}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Una consultante rumia dos horas cada noche sobre su divorcio. Desde la activación conductual, lo primero es…","ops":["Analizar la función de la rumiación y sus consecuencias","Pedirle que deje de pensar en eso","Darle la razón en todo"],"correcta":0},{"p":"«Buscar trabajo» es una actividad…","ops":["Ideal para la primera semana","Imposible de programar","Demasiado grande: conviene graduarla"],"correcta":2},{"p":"Una actividad «agradable» puede no funcionar si…","ops":["Es gratuita","No es reforzante para esa persona ni conecta con sus valores","Dura menos de una hora"],"correcta":1}]},{"tipo":"reflexion","rotulo":"Tu propia trampa","pregunta":"Piensa en una actividad que te cuesta iniciar. ¿Qué haces en su lugar y qué función cumple eso? ¿Cómo la graduarías?","ayuda":"Cuando toca… en su lugar hago… eso me sirve para… un primer paso de 10 minutos sería…"},{"tipo":"clave","items":["La activación conductual no es «haz cosas bonitas»: se elige por función y valores.","Gradúa las actividades y empieza con pocos minutos.","La rumiación se analiza como conducta: ¿te acerca o te aleja de actuar?"]}]},{"id":"d-terapias-contextuales-m5-l3","titulo":"Lección 3 — Psicoterapia analítica funcional (FAP)","objetivo":"identificar conductas clínicamente relevantes (CCR1, CCR2 y CCR3) y responder a ellas en la sesión.","bloques":[{"tipo":"texto","texto":"La <b>psicoterapia analítica funcional</b> (FAP), de Robert Kohlenberg y Mavis Tsai, parte de una idea: los problemas interpersonales de la persona <b>aparecen también en la relación terapéutica</b>. Si alguien evita la cercanía con todos, probablemente también lo haga contigo. La sesión se vuelve un laboratorio donde esas conductas se notan, se evocan con cuidado y se refuerzan de forma natural cuando mejoran."},{"tipo":"tabla","titulo":"Conductas clínicamente relevantes (CCR)","encabezados":["Tipo","Qué es","Ejemplo"],"filas":[["<b>CCR1</b>","Conductas problema que ocurren en la sesión","Cambia de tema cada vez que se habla de lo que siente por ti o por la terapia"],["<b>CCR2</b>","Mejoras que ocurren en la sesión","Dice por primera vez: «Me molestó que llegaras tarde»"],["<b>CCR3</b>","Interpretaciones de la persona sobre su propia conducta","«Me doy cuenta de que con mi jefe hago lo mismo que aquí: me callo»"]]},{"tipo":"pasos","rotulo":"Las cinco reglas de la FAP (resumen)","pasos":["<b>Observa</b> las CCR en la sesión.","<b>Evoca</b> las CCR de forma ética y con un propósito terapéutico claro.","<b>Refuerza de forma natural</b> las CCR2 (con tu interés, cercanía o reconocimiento genuino).","<b>Observa el efecto</b> de tu respuesta en la persona.","<b>Promueve interpretaciones funcionales</b> y la generalización a su vida diaria."]},{"tipo":"destacado","texto":"<b>Cercanía con límites.</b> La FAP pide autenticidad y cercanía, nunca cruzar límites: nada de relaciones duales, contacto físico fuera de lo profesional ni revelaciones personales que sirvan a tus necesidades y no a las del consultante. Explica el enfoque y obtén su consentimiento. Su evidencia es prometedora pero proviene de estudios más pequeños; suele integrarse con ACT o TCC, y conviene aplicarla con supervisión."},{"tipo":"relacionar","rotulo":"Clasifica la conducta","pares":[["Pide perdón cada vez que expresa una opinión en sesión","CCR1"],["Por primera vez dice que no está de acuerdo contigo","CCR2"],["«Creo que me disculpo tanto porque temo que se vayan»","CCR3"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"La idea central de la FAP es que…","ops":["Los problemas interpersonales aparecen también en la relación terapéutica","La relación terapéutica no importa","Solo se trabaja con tareas en casa"],"correcta":0},{"p":"Reforzar de forma natural una CCR2 significa…","ops":["Dar un premio material","Ignorarla para no incomodar","Responder con interés genuino, como lo haría una persona cercana"],"correcta":2},{"p":"Una revelación personal del terapeuta es inadecuada cuando…","ops":["Se planeó en supervisión","Sirve a las necesidades del terapeuta y no a las del consultante","Es breve y con un propósito terapéutico"],"correcta":1}]},{"tipo":"clave","items":["La FAP usa la relación terapéutica como laboratorio de conductas interpersonales.","CCR1 son problemas, CCR2 mejoras y CCR3 interpretaciones, todas dentro de la sesión.","Cercanía auténtica, con consentimiento, límites claros y supervisión."]}]},{"id":"d-terapias-contextuales-m5-l4","titulo":"Lección 4 — Mindfulness con evidencia: MBCT, MBSR y cuándo no conviene","objetivo":"valorar con realismo los efectos del mindfulness y reconocer cuándo no conviene o hay que adaptarlo.","bloques":[{"tipo":"texto","texto":"El <b>mindfulness</b> se volvió moda y con la moda llegaron las exageraciones. La investigación muestra <b>efectos reales pero modestos</b>: una revisión sistemática para la Agencia de Investigación y Calidad en Salud de EE. UU. (Goyal y colaboradores, 2014) encontró evidencia moderada de mejoras pequeñas a moderadas en ansiedad, depresión y dolor, comparables a las de otros tratamientos activos, no superiores."},{"tipo":"tabla","titulo":"Qué sabemos","encabezados":["Programa","Evidencia más sólida","Qué NO es"],"filas":[["MBCT (8 semanas, grupal)","Reduce el riesgo de recaída en depresión recurrente en personas en remisión (análisis de datos individuales de Kuyken y colaboradores, 2016)","Un tratamiento para el episodio depresivo agudo grave"],["MBSR (8 semanas, grupal)","Mejoras modestas en estrés, ansiedad y afrontamiento del dolor","Un sustituto de tratamiento médico o psicológico específico"],["Apps y cursos breves","Algunos efectos pequeños en estrés","Terapia; su calidad varía mucho"]]},{"tipo":"lista","items":["<b>Psicosis activa</b> o episodio maniaco: la práctica intensiva no es recomendable sin supervisión especializada.","<b>Trauma y TEPT</b>: la atención sostenida al cuerpo puede detonar recuerdos; usa prácticas breves, con ojos abiertos y con opción de detenerse (enfoque sensible al trauma).","<b>Depresión aguda grave</b>: MBCT fue diseñada para prevenir recaídas, no para el episodio agudo.","<b>Retiros intensivos</b>: se han reportado efectos adversos (ansiedad, despersonalización); pregúntale a la persona cómo le va con la práctica."]},{"tipo":"comparar","titulo":"Cómo hablar del mindfulness","malTitulo":"Con neuromitos y promesas","mal":"«La meditación reprograma tu cerebro y cura la ansiedad y la depresión.»","bienTitulo":"Con evidencia","bien":"«Practicar atención plena tiene efectos modestos en ansiedad y estrés, parecidos a otras terapias. Vamos a probarlo unas semanas y medir si te ayuda.»"},{"tipo":"completar","rotulo":"Completa","items":[{"frase":"Los efectos del mindfulness en ansiedad y depresión son en general ___, no espectaculares.","resp":["modestos","pequeños","moderados"]},{"frase":"La MBCT tiene su mejor evidencia en prevenir ___ en depresión recurrente.","resp":["recaídas","recaidas"]},{"frase":"Con personas con trauma, conviene usar prácticas breves y con los ojos ___.","resp":["abiertos"]}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"¿Qué afirmación sobre el mindfulness es más precisa?","ops":["Tiene efectos modestos, comparables a otros tratamientos activos","Es superior a cualquier terapia","No tiene ningún efecto"],"correcta":0},{"p":"Una persona en un episodio psicótico activo quiere ir a un retiro de meditación de 10 días. Lo prudente es…","ops":["Animarla a ir","Recomendarle más horas de práctica","Desaconsejarlo y coordinar con su psiquiatra"],"correcta":2},{"p":"Un consultante con TEPT se agita en un escaneo corporal. Lo adecuado es…","ops":["Aumentar la duración","Detener o adaptar la práctica y usar anclas externas","Pedirle que siga hasta el final"],"correcta":1}]},{"tipo":"clave","items":["El mindfulness tiene efectos reales pero modestos; no lo vendas como cura.","MBCT previene recaídas en depresión recurrente; no es para el episodio agudo grave.","En psicosis, trauma y depresión aguda, adapta la práctica o no la uses."]}]}],"quiz":{"titulo":"Evaluación del módulo 5","preguntas":[{"p":"En la depresión, la activación conductual considera que la evitación…","ops":["Siempre es sana","Es un rasgo fijo de personalidad","No se relaciona con el ánimo","Alivia a corto plazo pero reduce el reforzamiento a largo plazo"],"correcta":3},{"p":"El principio «de afuera hacia adentro» significa…","ops":["Cambiar pensamientos antes de actuar","Hacer solo lo que da placer","Actuar según el plan aunque no haya ganas","Esperar a tener motivación"],"correcta":2},{"p":"En el ensayo COBRA, la activación conductual frente a la TCC…","ops":["Fue dañina","No fue inferior","Fue mucho peor","No tuvo efecto"],"correcta":1},{"p":"Para contar actividades de un valor que sí se hicieron, en hoja de cálculo usas…","ops":["CONTAR.SI.CONJUNTO","SUMA","MAX","IZQUIERDA"],"correcta":0},{"p":"En FAP, una CCR2 es…","ops":["Una conducta problema en la sesión","Una tarea para casa","Un diagnóstico","Una mejora que ocurre en la sesión"],"correcta":3},{"p":"Un riesgo ético de la FAP es…","ops":["Usar tarjetas diarias","Hacer análisis funcional","Cruzar límites en nombre de la cercanía","Medir el ánimo"],"correcta":2},{"p":"La MBCT está diseñada principalmente para…","ops":["Tratar el insomnio en niños","Prevenir recaídas en depresión recurrente","Tratar la psicosis aguda","Curar el TEPT"],"correcta":1},{"p":"¿En cuál de estos casos conviene NO usar mindfulness intensivo sin supervisión especializada?","ops":["Psicosis activa","Estrés laboral leve","Curiosidad por la práctica","Dolor de espalda crónico"],"correcta":0}]}},{"id":"d-terapias-contextuales-m6","titulo":"Módulo 6 — Integración, medición y ética","resumen":"Cómo elegir la intervención a partir de la formulación, medir resultados sesión a sesión en una hoja de cálculo, trabajar con supervisión y dentro de tus límites de competencia según el código ético, y un caso integrador ficticio completo. Cuatro lecciones y una evaluación.","lecciones":[{"id":"d-terapias-contextuales-m6-l1","titulo":"Lección 1 — Elegir la intervención según la formulación","objetivo":"seleccionar la intervención contextual más adecuada a partir de la formulación del caso, la evidencia y las preferencias de la persona.","bloques":[{"tipo":"texto","texto":"Las terapias contextuales no son un menú para elegir por gusto del terapeuta. La decisión se basa en tres fuentes: la <b>formulación</b> (qué mantiene el problema), la <b>evidencia</b> para ese problema y esa población, y las <b>preferencias y circunstancias</b> de la persona. A esto se le llama práctica basada en la evidencia."},{"tipo":"tabla","titulo":"Guía orientativa (no es un algoritmo)","encabezados":["Si la formulación muestra…","Considera…"],"filas":[["Evitación experiencial amplia, fusión con reglas rígidas, vida desconectada de valores","ACT"],["Desregulación emocional intensa con autolesiones o conducta suicida recurrente","DBT (con equipo y formación específica) o derivación a un programa DBT"],["Depresión mantenida por evitación y pérdida de reforzadores","Activación conductual"],["Depresión recurrente, ahora en remisión","MBCT para prevenir recaídas"],["Problemas interpersonales que aparecen también en la sesión","Integrar FAP a tu modelo base"],["Mucha vergüenza y autocrítica","Elementos de terapia centrada en la compasión"],["Fobia específica, pánico o TOC con evitación clara","Exposición (ver el Diplomado en TCC), que puede integrarse con ACT"]],"nota":"La guía no sustituye tu juicio clínico ni las guías vigentes (NICE, APA). Ante riesgo, psicosis o consumo grave, prioriza la seguridad y la atención médica."},{"tipo":"comparar","titulo":"Dos formas de decidir","malTitulo":"Por preferencia del terapeuta","mal":"«Yo trabajo con ACT, así que a todos mis consultantes les doy ACT.»","bienTitulo":"Por formulación","bien":"«Tu análisis muestra que la depresión se mantiene por evitación y aislamiento. La activación conductual tiene buena evidencia para eso. ¿Te parece si empezamos por ahí y medimos cada semana?»"},{"tipo":"destacado","texto":"<b>Cuándo derivar.</b> Si la persona necesita una intervención que no dominas (por ejemplo, DBT completa para autolesiones frecuentes), la opción ética es <b>derivar</b> a un servicio que la ofrezca o trabajar bajo supervisión de alguien formado. Derivar no es fallar: es cuidar."},{"tipo":"practica","rotulo":"¿Qué considerarías primero?","preguntas":[{"p":"Joven de 19 años con autolesiones semanales, cambios emocionales intensos y dos visitas a urgencias este año.","ops":["DBT o derivación a un programa DBT, priorizando la seguridad","MBCT grupal","Solo defusión cognitiva"],"correcta":0,"explica":"La población con mejor evidencia de DBT; además, el riesgo va primero."},{"p":"Hombre de 52 años con depresión: dejó el futbol, no ve a sus amigos y pasa el día en el sillón.","ops":["FAP como único tratamiento","Retiro de meditación","Activación conductual"],"correcta":2},{"p":"Mujer de 38 años con tres episodios depresivos previos, ahora estable, que teme recaer.","ops":["Nada, porque está estable","MBCT para prevenir recaídas","DBT estándar"],"correcta":1}]},{"tipo":"relacionar","rotulo":"Relaciona el dato de la formulación con la intervención","pares":[["Reglas rígidas y vida desconectada de valores","ACT"],["Aislamiento y pérdida de actividades reforzantes","Activación conductual"],["Se calla en sesión igual que con su jefe","FAP"],["Autocrítica y vergüenza intensas","Terapia centrada en la compasión"]]},{"tipo":"clave","items":["Elige por formulación, evidencia y preferencias de la persona, no por gusto del terapeuta.","Ante riesgo, psicosis o consumo grave, la seguridad y la atención médica van primero.","Derivar cuando no dominas la intervención es una decisión ética."]}]},{"id":"d-terapias-contextuales-m6-l2","titulo":"Lección 2 — Medir resultados sesión a sesión","objetivo":"registrar medidas breves en cada sesión y calcular en una hoja de cálculo el cambio confiable y las alertas de alianza.","bloques":[{"tipo":"texto","texto":"Medir en cada sesión (monitoreo rutinario de resultados) ayuda a detectar a tiempo a quienes no mejoran o empeoran, algo que el juicio clínico por sí solo suele pasar por alto. Se usan cuestionarios breves: el <b>PHQ-9</b> para síntomas depresivos (0 a 27) y el <b>GAD-7</b> para ansiedad (0 a 21), ambos de uso libre, y medidas de <b>alianza</b> como la Escala de Calificación de la Sesión (SRS, 0 a 40; verifica sus condiciones de uso). Ninguno diagnostica por sí solo."},{"tipo":"tabla","titulo":"Criterios de referencia (programa NHS Talking Therapies, Inglaterra)","encabezados":["Medida","Rango clínico («caso»)","Mejoría confiable"],"filas":[["PHQ-9","10 o más","Bajar 6 puntos o más"],["GAD-7","8 o más","Bajar 4 puntos o más"]],"nota":"Son criterios de un servicio público inglés, útiles como referencia. En la SRS, puntuaciones menores de 36 suelen tomarse como señal para conversar sobre la alianza. Verifica los criterios del instrumento y la versión en español que uses."},{"tipo":"excel","rotulo":"Seguimiento de Lucía (ficticio)","datos":[["Sesión","PHQ-9 (0-27)","GAD-7 (0-21)","Alianza SRS (0-40)"],[1,18,13,34],[2,17,13,37],[3,15,11,38],[4,14,10,36],[5,11,8,38],[6,9,7,39],["","","",""],["Cambio PHQ-9 (inicio menos última)",""],["¿Mejoría confiable PHQ-9?",""],["Cambio GAD-7 (inicio menos última)",""],["¿Mejoría confiable GAD-7?",""],["Sesiones con alianza menor de 36",""],["¿PHQ-9 final bajo el rango clínico?",""]],"retos":[{"celda":"B9","formula":"=B2-B7","esperado":9,"texto":"<b>B9</b>: cambio en PHQ-9: primera sesión menos la última."},{"celda":"B10","formula":"=SI(B9>=6,\"Sí\",\"No\")","esperado":"Sí","requiere":"SI(","texto":"<b>B10</b>: con SI, escribe «Sí» si el cambio es de 6 o más; si no, «No»."},{"celda":"B11","formula":"=C2-C7","esperado":6,"texto":"<b>B11</b>: cambio en GAD-7."},{"celda":"B12","formula":"=SI(B11>=4,\"Sí\",\"No\")","esperado":"Sí","requiere":"SI(","texto":"<b>B12</b>: «Sí» si el GAD-7 bajó 4 puntos o más."},{"celda":"B13","formula":"=CONTAR.SI(D2:D7,\"<36\")","esperado":1,"requiere":"CONTAR.SI(","texto":"<b>B13</b>: cuenta las sesiones con alianza menor de 36."},{"celda":"B14","formula":"=SI(B7<10,\"Sí\",\"No\")","esperado":"Sí","requiere":"SI(","texto":"<b>B14</b>: «Sí» si el PHQ-9 de la última sesión es menor de 10.","explica":"Lucía muestra mejoría confiable en depresión y ansiedad y termina por debajo del rango clínico en PHQ-9. La alianza baja de la sesión 1 es común al inicio; lo importante es que se habló y mejoró. Aun así, en cada sesión se revisa la pregunta del PHQ-9 sobre pensamientos de muerte: si se responde con cualquier valor distinto de cero, se evalúa el riesgo en ese momento."}]},{"tipo":"destacado","texto":"<b>La pregunta 9 del PHQ-9</b> explora pensamientos de muerte o de hacerse daño. Revísala en cada aplicación, aunque el total sea bajo. Cualquier respuesta distinta de «nunca» requiere evaluar el riesgo en la misma sesión."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"El PHQ-9 de un consultante pasa de 16 a 12. Según el criterio de referencia, eso…","ops":["Todavía no es mejoría confiable (bajó 4, se requieren 6)","Es mejoría confiable","Indica recuperación completa"],"correcta":0},{"p":"Medir en cada sesión sirve sobre todo para…","ops":["Diagnosticar","Sustituir la entrevista clínica","Detectar a tiempo a quien no mejora o empeora"],"correcta":2},{"p":"Un PHQ-9 total de 6 con la pregunta 9 marcada como «varios días» requiere…","ops":["Esperar a la siguiente sesión","Evaluar el riesgo en la misma sesión","Ignorarla porque el total es bajo"],"correcta":1}]},{"tipo":"clave","items":["Mide con instrumentos breves en cada sesión: PHQ-9, GAD-7 y una medida de alianza.","Cambio confiable de referencia: 6 puntos en PHQ-9 y 4 en GAD-7.","Revisa siempre la pregunta sobre pensamientos de muerte, aunque el total sea bajo."]}]},{"id":"d-terapias-contextuales-m6-l3","titulo":"Lección 3 — Supervisión, límites de competencia y código ético","objetivo":"reconocer tus límites de competencia y aplicar el Código Ético del Psicólogo a dilemas frecuentes de la práctica contextual.","bloques":[{"tipo":"texto","texto":"En México, el <b>Código Ético del Psicólogo</b> de la Sociedad Mexicana de Psicología (publicado por Editorial Trillas) es la referencia más usada; también existen otros, como el de la Federación Nacional de Colegios, Sociedades y Asociaciones de Psicólogos de México (FENAPSIME). Todos coinciden en principios como el respeto a la dignidad y los derechos de las personas, el cuidado responsable, la integridad en las relaciones y la <b>competencia</b>: ofrecer solo los servicios para los que se tiene formación y experiencia, o hacerlo bajo supervisión."},{"tipo":"tabla","titulo":"Dilemas frecuentes con terapias contextuales","encabezados":["Situación","Respuesta ética"],"filas":[["Anunciarte como «terapeuta ACT certificado» tras un diplomado","No existe certificación oficial en ACT; describe con precisión tu formación"],["Ofrecer «DBT» cuando solo das un taller de habilidades","Llámalo por su nombre: grupo de habilidades basado en DBT"],["Atender autolesiones frecuentes sin formación en DBT ni manejo de crisis","Derivar o trabajar bajo supervisión de alguien formado"],["Grabar sesiones para supervisión","Solo con consentimiento informado por escrito y resguardo seguro"],["Compartir un caso en redes o grupos de mensajería","No; en supervisión, con datos que no permitan identificar a la persona"],["Usar una técnica que aprendiste en un video corto","Formarte y practicar con supervisión antes de aplicarla"]]},{"tipo":"lista","items":["<b>Supervisión clínica:</b> revisa casos con alguien con más experiencia en el modelo; en DBT, el equipo de consulta es parte del tratamiento.","<b>Formación continua:</b> talleres con formadores reconocidos, lectura de manuales y práctica deliberada.","<b>Autocuidado:</b> el desgaste del terapeuta afecta la calidad de la atención; atiéndelo.","<b>Consentimiento informado:</b> explica el enfoque, su evidencia, alternativas, confidencialidad y sus límites (por ejemplo, riesgo para la vida)."]},{"tipo":"destacado","texto":"<b>Límites de la confidencialidad.</b> La confidencialidad tiene excepciones cuando hay riesgo serio para la vida de la persona o de terceros, y en los casos que marca la ley. Explícalas desde la primera sesión, por escrito. Verifica las disposiciones vigentes sobre expediente clínico y datos personales que apliquen a tu forma de ejercer."},{"tipo":"relacionar","rotulo":"Relaciona el principio con el ejemplo","pares":[["Competencia","Derivar un caso de autolesiones frecuentes a un programa DBT"],["Integridad","Describir tu formación sin inflarla"],["Respeto a la dignidad","Usar lenguaje no estigmatizante"],["Confidencialidad","Presentar un caso sin datos que identifiquen"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Terminaste este diplomado. ¿Cómo describes tu formación con honestidad?","ops":["«Diplomado libre de 40 horas en terapias contextuales»","«Terapeuta ACT certificado»","«Especialista certificado en DBT»"],"correcta":0},{"p":"Un taller de habilidades DBT sin terapia individual ni equipo de consulta…","ops":["Es DBT estándar","Es mejor que la DBT","No es DBT completa y debe presentarse así"],"correcta":2},{"p":"Para grabar una sesión con fines de supervisión necesitas…","ops":["Nada, si es para aprender","Consentimiento informado por escrito","Solo avisar de palabra"],"correcta":1}]},{"tipo":"reflexion","rotulo":"Tus límites hoy","pregunta":"Con honestidad: ¿qué tipo de casos podrías atender con lo que sabes y cuáles derivarías o trabajarías solo con supervisión?","ayuda":"Me siento competente para… derivaría… buscaría supervisión en…"},{"tipo":"clave","items":["El código ético exige competencia: ofrece solo lo que dominas o trabájalo con supervisión.","Describe tu formación con precisión; no existe certificación oficial en ACT.","Consentimiento informado, confidencialidad y sus límites se explican desde el inicio."]}]},{"id":"d-terapias-contextuales-m6-l4","titulo":"Lección 4 — Caso integrador ficticio","objetivo":"integrar análisis funcional, formulación, intervención, medición y ética en un caso ficticio completo.","bloques":[{"tipo":"texto","texto":"<b>Caso ficticio: Alejandro, 31 años, ingeniero en Querétaro.</b> Llega por «ansiedad y bajón» desde hace ocho meses, tras un cambio de área en su empresa. Evita las juntas con clientes (se reporta enfermo), dejó el equipo de basquetbol, pasa las noches revisando foros sobre «cómo saber si eres un fraude» y bebe cuatro o cinco cervezas los viernes «para desconectarse». Vive con su pareja, Sofía, a quien describe como su mayor apoyo. Niega ideas de muerte; lo confirmas con preguntas directas y con la pregunta 9 del PHQ-9. PHQ-9: 15. GAD-7: 14."},{"tipo":"tabla","titulo":"Formulación contextual (resumen)","encabezados":["Elemento","Contenido"],"filas":[["Análisis funcional","Evitar juntas y beber alivian la ansiedad y la vergüenza de inmediato (reforzamiento negativo); a largo plazo aumentan el miedo, los problemas en el trabajo y el ánimo bajo"],["Fusión","Con la regla «si me ven nervioso, sabrán que soy un fraude»"],["Evitación experiencial","Revisar foros y beber funcionan para no sentir la incertidumbre"],["Pérdida de reforzadores","Dejó el basquetbol y ve menos a sus amigos"],["Valores (matriz ACT)","Ser un ingeniero que aporta, ser buen compañero de equipo, cuidar su relación con Sofía"],["Fortalezas","Apoyo de su pareja, trabajo estable, buena disposición al tratamiento"]]},{"tipo":"pasos","rotulo":"Plan de intervención (12 a 16 sesiones, revisable)","pasos":["Consentimiento informado, línea base (PHQ-9, GAD-7 y registro funcional) y acuerdos de confidencialidad y sus límites.","Pregunta de viabilidad sobre evitar, beber y revisar foros: alivio a corto plazo contra costo a largo plazo.","Clarificación de valores con la matriz ACT y el cuestionario del curso.","Defusión de la regla «soy un fraude» y aceptación de la ansiedad en juntas, con exposición graduada a las juntas.","Activación conductual: volver al basquetbol de forma graduada y planear salidas con Sofía y sus amigos.","Revisión del consumo de alcohol con información objetiva; si aumenta o hay dependencia, derivar a atención especializada.","Medición en cada sesión y ajuste del plan si no hay cambio confiable hacia la sesión 6 u 8.","Prevención de recaídas y cierre, con plan escrito y fecha de seguimiento."]},{"tipo":"ordenar","rotulo":"Ordena el principio que guía el caso","items":[{"frase":"Formular medir intervenir y volver a medir","es":"La formulación se ajusta con los datos"}]},{"tipo":"practica","rotulo":"Decisiones del caso","preguntas":[{"p":"En la sesión 8, el PHQ-9 de Alejandro sigue en 14. Lo adecuado es…","ops":["Revisar la formulación y el plan, y comentarlo en supervisión","Seguir igual porque la terapia tarda","Darlo de alta"],"correcta":0},{"p":"Alejandro dice que desde hace dos semanas bebe también entre semana. Lo adecuado es…","ops":["Ignorarlo porque no es el motivo de consulta","Pedirle que lo acepte con defusión","Evaluar el consumo y valorar derivar a atención especializada"],"correcta":2},{"p":"Sofía te llama para preguntar cómo va Alejandro. Lo correcto es…","ops":["Enviarle los cuestionarios","No compartir información sin el consentimiento de Alejandro","Contarle todo porque es su pareja"],"correcta":1}]},{"tipo":"reflexion","rotulo":"Tu turno","pregunta":"Si fueras el terapeuta de Alejandro, ¿qué harías distinto en el plan y por qué? ¿Qué parte del caso llevarías a supervisión?","ayuda":"Cambiaría… porque en la formulación… Llevaría a supervisión…"},{"tipo":"clave","items":["Un caso integrado une análisis funcional, valores, intervención con evidencia y medición.","Si los datos no muestran cambio, revisa la formulación y consulta en supervisión.","La ética atraviesa todo: consentimiento, confidencialidad, derivación y límites de competencia."]}]}],"quiz":{"titulo":"Evaluación del módulo 6","preguntas":[{"p":"La práctica basada en la evidencia combina…","ops":["Solo la preferencia del terapeuta","Solo lo que diga el consultante","La terapia de moda","Evidencia, formulación y preferencias de la persona"],"correcta":3},{"p":"Para depresión recurrente en remisión, una opción con buena evidencia es…","ops":["DBT estándar","Solo lectura de libros","MBCT","FAP como único tratamiento"],"correcta":2},{"p":"El criterio de referencia de mejoría confiable en PHQ-9 es bajar…","ops":["Cualquier cambio","6 puntos o más","1 punto","15 puntos"],"correcta":1},{"p":"La pregunta 9 del PHQ-9 explora…","ops":["Pensamientos de muerte o de hacerse daño","El apetito","El sueño","La concentración"],"correcta":0},{"p":"Tras un diplomado de 40 horas, anunciarse como «terapeuta ACT certificado» es…","ops":["Correcto","Obligatorio","Un requisito de la SEP","Engañoso, porque no existe certificación oficial en ACT"],"correcta":3},{"p":"Un grupo de habilidades sin terapia individual ni equipo de consulta…","ops":["Es FAP","Es MBCT","No es DBT completa","Es DBT estándar"],"correcta":2},{"p":"Para grabar sesiones con fines de supervisión se requiere…","ops":["Solo avisar al final","Consentimiento informado por escrito","Nada","Permiso del jefe"],"correcta":1},{"p":"Si tras varias sesiones no hay cambio confiable, lo adecuado es…","ops":["Revisar la formulación y consultar en supervisión","Seguir igual sin revisar","Culpar al consultante","Terminar sin explicación"],"correcta":0}]}}]});
window.CURSOS_MARA.push({"id":"d-evaluacion-clinica","nombre":"Diplomado en Evaluación Psicológica y Formulación de Casos Clínicos","color":"#7C3AED","nivel":"Diplomados","familia":"Salud y bienestar","periodoTipo":null,"periodoNum":null,"desc":"Para psicólogos con cédula y estudiantes de los últimos semestres que no saben por dónde empezar cuando llega un paciente. Aprende a conducir la primera consulta, evaluar el estado mental y el riesgo, usar la CIE-11 y el DSM-5-TR con criterio, formular el caso con el modelo de las 5 P, medir resultados sesión a sesión y documentar bien tu expediente. Casos ficticios y práctica constante; no sustituye la supervisión clínica.","horas":30,"precio":1790,"publicado":true,"proximamente":false,"modulos":[{"id":"d-evaluacion-clinica-m1","titulo":"Módulo 1 — La primera consulta","resumen":"Encuadre, consentimiento informado, confidencialidad y sus límites, la primera entrevista semiestructurada, el motivo de consulta, la historia clínica, la alianza terapéutica y las particularidades de entrevistar a adolescentes, parejas y familias. Cuatro lecciones y una evaluación.","lecciones":[{"id":"d-evaluacion-clinica-m1-l1","titulo":"Lección 1 — Para quién es este diplomado y el encuadre","objetivo":"reconocer los alcances de este diplomado y establecer un encuadre claro desde el primer contacto con un paciente.","bloques":[{"tipo":"destacado","texto":"<b>Antes de empezar.</b> Este es un <b>diplomado libre de capacitación</b> con constancia de Instituto Mara: <b>no tiene validez oficial de la SEP</b> ni es una certificación de CONOCER. Está dirigido a <b>psicólogos con cédula profesional</b> y a <b>estudiantes de los últimos semestres de psicología</b>. <b>No habilita a quien no es psicólogo para evaluar ni diagnosticar</b>: en México, la práctica de la psicología clínica y la psicoterapia requiere formación profesional y <b>cédula</b>. Tampoco <b>sustituye la supervisión clínica</b>: si estás en formación, cada caso real que atiendas debe revisarse con tu supervisor o supervisora. Si un paciente está en riesgo, recuerda la <b>Línea de la Vida 800 911 2000</b> (gratuita, 24 horas) y el <b>911</b> en emergencia."},{"tipo":"texto","texto":"Muchos psicólogos recién egresados cuentan lo mismo: «Sabía teoría, pero cuando se sentó el primer paciente no supe por dónde empezar». Este diplomado sigue el recorrido real de un caso: <b>primera consulta → evaluación → diagnóstico → formulación → plan de tratamiento y documentación</b>. Nos basamos en la CIE-11 de la OMS, el DSM-5-TR de la Asociación Americana de Psiquiatría, las guías NICE y las recomendaciones de la APA. Todos los casos son <b>ficticios</b>.<br><br>El primer paso es el <b>encuadre</b>: las reglas del juego que acuerdas con el paciente para que el trabajo sea posible y seguro."},{"tipo":"tabla","titulo":"Elementos del encuadre","encabezados":["Elemento","Qué acuerdas","Ejemplo"],"filas":[["Objetivo inicial","Que las primeras sesiones son de evaluación, no de tratamiento todavía","«Las primeras 2 o 3 sesiones nos sirven para entender qué pasa y decidir juntos el plan»"],["Tiempo y frecuencia","Duración de la sesión y periodicidad","50 minutos, una vez por semana"],["Honorarios y cancelaciones","Costo, forma de pago y política de faltas","Cancelar con 24 horas de anticipación"],["Modalidad","Presencial o en línea, y qué hacer si falla la conexión","«Si se corta la videollamada, te marco al celular»"],["Contacto entre sesiones","Por qué medio y para qué","WhatsApp solo para agenda; en crisis, Línea de la Vida o 911"],["Confidencialidad","Qué se guarda en secreto y cuáles son sus límites","Lo verás en la siguiente lección"]]},{"tipo":"comparar","titulo":"Dos formas de abrir la primera sesión","malTitulo":"Sin encuadre","mal":"«Bueno, cuéntame, ¿qué te trae por aquí?» (y 50 minutos después el paciente no sabe cuánto cuesta, cuántas sesiones serán ni si lo que dijo es confidencial).","bienTitulo":"Con encuadre","bien":"«Antes de empezar quiero platicarte cómo vamos a trabajar: la sesión dura 50 minutos, las primeras sesiones son para conocernos y entender lo que te pasa, lo que hablemos aquí es confidencial con algunas excepciones que te voy a explicar, y al final te propongo un plan. ¿Te parece?»"},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Una persona que tomó este diplomado pero no estudió psicología puede…","ops":["Comprender el proceso, pero no evaluar ni diagnosticar pacientes","Abrir un consultorio de evaluación psicológica","Diagnosticar si usa la CIE-11"],"correcta":0,"explica":"La evaluación y el diagnóstico clínico son actos profesionales que requieren formación en psicología y cédula."},{"p":"El encuadre sirve para…","ops":["Demostrar autoridad ante el paciente","Cobrar por adelantado todas las sesiones","Acordar reglas claras que hacen posible y seguro el trabajo"],"correcta":2},{"p":"Si estás en formación y atiendes un caso real, lo indicado es…","ops":["Consultarlo en un grupo de redes sociales con nombre y datos","Revisarlo con tu supervisor o supervisora","Resolverlo solo para ganar experiencia"],"correcta":1}]},{"tipo":"ordenar","rotulo":"Ordena el recorrido de un caso","items":[{"frase":"primera consulta evaluación diagnóstico formulación plan de tratamiento","es":"Cada etapa se apoya en la anterior; por eso el diplomado sigue este orden."}]},{"tipo":"clave","items":["Este diplomado es para psicólogos y estudiantes avanzados; no habilita para evaluar a quien no lo es ni sustituye la supervisión.","El encuadre (objetivo, tiempo, honorarios, modalidad, contacto y confidencialidad) se acuerda desde la primera sesión.","Recorrido del caso: consulta, evaluación, diagnóstico, formulación y plan."]}]},{"id":"d-evaluacion-clinica-m1-l2","titulo":"Lección 2 — Consentimiento informado y confidencialidad","objetivo":"obtener un consentimiento informado válido y explicar al paciente la confidencialidad y sus límites con palabras sencillas.","bloques":[{"tipo":"texto","texto":"El <b>consentimiento informado</b> no es un papel que se firma de prisa: es un <b>proceso</b> en el que el paciente entiende qué vas a hacer, para qué, con qué riesgos y alternativas, y decide libremente. Se documenta por escrito, pero sobre todo se <b>conversa</b>. Los códigos de ética de la profesión (por ejemplo, el de la Sociedad Mexicana de Psicología o los principios de la APA) coinciden en que es una obligación, no una formalidad."},{"tipo":"lista","items":["<b>Qué incluye:</b> propósito de la evaluación, procedimientos (entrevistas, cuestionarios), duración aproximada, honorarios, confidencialidad y sus límites, uso de los datos y derecho a retirarse.","<b>Quién lo firma:</b> la persona adulta con capacidad para decidir. En menores de edad, madre, padre o tutor, <b>más el asentimiento</b> del niño o adolescente explicado a su nivel.","<b>Cuándo se renueva:</b> si cambias de procedimiento (por ejemplo, grabar una sesión o aplicar una batería extensa) o si inicias tratamiento después de la evaluación."]},{"tipo":"tabla","titulo":"Los límites de la confidencialidad (se explican desde el inicio)","encabezados":["Situación","Qué implica"],"filas":[["Riesgo grave para la vida del paciente","Puedes romper la confidencialidad para protegerlo: avisar a un familiar, activar servicios de emergencia"],["Riesgo grave para terceros","Amenaza creíble de dañar a alguien identificable"],["Maltrato o abuso a niñas, niños, adolescentes u otras personas vulnerables","Existe obligación de dar aviso a las autoridades de protección; verifica el procedimiento de tu entidad"],["Orden de una autoridad judicial","Se entrega solo lo que se solicita formalmente"],["Supervisión clínica","Se comenta el caso con el supervisor, sin datos que identifiquen al paciente cuando sea posible"]],"nota":"Revisa con tu institución, tu colegio de psicólogos o un abogado las obligaciones de aviso que aplican en tu estado: pueden variar."},{"tipo":"plantilla","rotulo":"Guion para explicar la confidencialidad","texto":"Todo lo que platiquemos aquí es confidencial: no lo comparto con tu familia, tu escuela ni tu trabajo sin tu permiso. Hay pocas excepciones, y te las digo desde ahora para que no haya sorpresas: si considero que tu vida o la de otra persona está en peligro grave, si me entero de que un niño o una persona vulnerable está siendo lastimada, o si un juez me lo pide formalmente. Además, reviso mis casos con un supervisor para darte una mejor atención, cuidando tus datos. Si algún día tengo que compartir algo, primero intentaré platicarlo contigo. ¿Tienes alguna duda?"},{"tipo":"relacionar","rotulo":"¿Qué haces en cada situación?","pares":[["La mamá de un paciente adulto llama para preguntar qué dijo su hijo","No compartes nada sin autorización del paciente"],["Un paciente dice que tiene un plan concreto para quitarse la vida hoy","Priorizas su seguridad aunque implique romper la confidencialidad"],["Una adolescente relata que un adulto de su casa la golpea con frecuencia","Das aviso a la autoridad de protección correspondiente"],["Quieres grabar la sesión para tu supervisión","Pides consentimiento específico por escrito"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"El consentimiento informado es, ante todo…","ops":["Un proceso de conversación y decisión libre","Un formato que se firma sin leer","Un requisito solo para investigación"],"correcta":0,"explica":"El documento es la evidencia; lo importante es que el paciente entienda y decida."},{"p":"Con un adolescente de 15 años necesitas…","ops":["Solo la firma del adolescente","Solo la firma del tutor, sin explicarle nada al adolescente","El consentimiento del tutor y el asentimiento del adolescente"],"correcta":2},{"p":"Los límites de la confidencialidad se explican…","ops":["Nunca, para no asustar al paciente","Desde la primera sesión","Solo cuando aparece un riesgo"],"correcta":1}]},{"tipo":"clave","items":["El consentimiento informado es un proceso: se conversa, se documenta y se renueva si cambia el procedimiento.","En menores: consentimiento del tutor más asentimiento del menor.","La confidencialidad tiene límites (riesgo, maltrato, orden judicial) y se explican desde el inicio."]}]},{"id":"d-evaluacion-clinica-m1-l3","titulo":"Lección 3 — La primera entrevista semiestructurada y el motivo de consulta","objetivo":"conducir una primera entrevista semiestructurada, precisar el motivo de consulta y cuidar la alianza terapéutica desde el inicio.","bloques":[{"tipo":"texto","texto":"Una entrevista <b>libre</b> sigue al paciente a donde vaya; una <b>estructurada</b> lee preguntas fijas en orden. La <b>semiestructurada</b> combina lo mejor de ambas: tienes una guía de temas que no pueden faltar, pero el orden y las palabras se adaptan a la persona. Es la forma más útil para una primera consulta."},{"tipo":"plantilla","rotulo":"Guía de primera entrevista semiestructurada","texto":"1. Encuadre y consentimiento (5 min).\n2. Motivo de consulta en palabras del paciente: ¿Qué te trae hoy? ¿Por qué ahora?\n3. Historia del problema: ¿Cuándo empezó? ¿Qué pasaba en tu vida entonces? ¿Ha cambiado con el tiempo?\n4. Impacto: ¿Cómo afecta tu trabajo, estudios, pareja, familia, sueño, alimentación?\n5. Intentos de solución: ¿Qué has probado? ¿Qué te ha servido y qué no? ¿Tratamientos previos?\n6. Tamizaje de riesgo: pensamientos de muerte o de hacerse daño, violencia, consumo de sustancias.\n7. Recursos: ¿Con quién cuentas? ¿Qué te ayuda a sentirte mejor?\n8. Expectativas: ¿Qué te gustaría que cambiara? ¿Cómo sabrías que esto funcionó?\n9. Cierre: resumen, dudas y próximos pasos (5 min).","nota":"Adapta el orden: si el paciente llega en crisis, el tamizaje de riesgo va primero."},{"tipo":"tabla","titulo":"Del motivo expresado al motivo de consulta clínico","encabezados":["Lo que dice el paciente","Preguntas para precisar","Motivo de consulta redactado"],"filas":[["«Ya no puedo con mi vida»","¿Qué es lo que ya no puedes? ¿Desde cuándo? ¿Has pensado en quitarte la vida?","Tristeza persistente, cansancio y aislamiento de 3 meses tras pérdida del empleo; niega ideación suicida"],["«Mi mamá dice que tengo que venir»","¿Tú qué piensas de venir? ¿Qué crees que le preocupa a ella?","Referido por la madre por bajo rendimiento escolar; el adolescente reconoce problemas para dormir"],["«Me dan ataques»","¿Qué sientes exactamente? ¿Cuánto dura? ¿Dónde te pasa?","Episodios súbitos de palpitaciones y miedo intenso, de 10 minutos, 2 a 3 por semana desde hace 2 meses"]],"nota":"Distingue <b>quién</b> pide la consulta (el paciente, un familiar, la escuela, un juzgado): cambia la motivación y el encuadre."},{"tipo":"texto","texto":"La <b>alianza terapéutica</b> es el acuerdo de colaboración entre tú y el paciente: <b>vínculo</b> (confianza), <b>acuerdo en las metas</b> y <b>acuerdo en las tareas</b>. Es uno de los predictores más consistentes del resultado en psicoterapia, sin importar el enfoque. Se construye desde la primera entrevista: escuchar sin juzgar, validar, explicar lo que harás y preguntar cómo se sintió la sesión."},{"tipo":"comparar","titulo":"Preguntar sobre el motivo de consulta","malTitulo":"Pregunta que cierra","mal":"«¿Estás deprimido?» «¿Tomas mucho?» «¿Tu esposo te trata mal?» (preguntas cerradas que suenan a juicio y se responden con sí o no).","bienTitulo":"Pregunta que abre","bien":"«¿Cómo ha sido tu ánimo estas semanas?» «Cuéntame cómo es tu consumo de alcohol en una semana normal.» «¿Cómo se resuelven los desacuerdos en tu casa?»"},{"tipo":"completar","rotulo":"Completa","items":[{"frase":"La entrevista ___ tiene una guía de temas obligatorios, pero adapta el orden y las palabras.","resp":["semiestructurada","semi estructurada","semi-estructurada"]},{"frase":"La alianza terapéutica incluye vínculo, acuerdo en metas y acuerdo en ___.","resp":["tareas","las tareas"]},{"frase":"Además de «qué te trae», conviene preguntar «¿por qué ___?».","resp":["ahora"]}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Un paciente llega llorando y dice que no quiere seguir viviendo. En tu guía…","ops":["Adelantas el tamizaje de riesgo","Sigues el orden y preguntas por su infancia","Terminas la sesión y le das cita la próxima semana"],"correcta":0,"explica":"La guía es flexible: la seguridad va primero."},{"p":"¿Cuál es el mejor predictor transversal de buen resultado en psicoterapia, sin importar el enfoque?","ops":["El número de pruebas aplicadas","La antigüedad del terapeuta","La alianza terapéutica"],"correcta":2}]},{"tipo":"clave","items":["La entrevista semiestructurada combina guía fija y flexibilidad; la seguridad siempre va primero.","Convierte el motivo expresado en un motivo clínico: qué, desde cuándo, cuánto, dónde y con qué impacto.","La alianza (vínculo, metas y tareas) se construye desde la primera sesión."]}]},{"id":"d-evaluacion-clinica-m1-l4","titulo":"Lección 4 — Historia clínica y entrevistas con adolescentes, parejas y familias","objetivo":"integrar una historia clínica psicológica completa y adaptar la entrevista cuando atiendes a un adolescente, una pareja o una familia.","bloques":[{"tipo":"texto","texto":"La <b>historia clínica</b> ordena lo que recogiste en la entrevista para que tú (o cualquier colega) pueda entender el caso. No se llena en una sola sesión: se completa a lo largo de la evaluación. Recuerda que no es un interrogatorio: pregunta lo relevante para el motivo de consulta."},{"tipo":"tabla","titulo":"Apartados de una historia clínica psicológica","encabezados":["Apartado","Qué registras"],"filas":[["Ficha de identificación","Nombre, edad, escolaridad, ocupación, estado civil, con quién vive, contacto de emergencia"],["Motivo de consulta","En palabras del paciente y redactado clínicamente; quién refiere"],["Padecimiento actual","Inicio, curso, factores que lo empeoran o alivian, impacto"],["Antecedentes personales","Desarrollo, escolaridad, trabajo, salud física, medicamentos, sueño, consumo de sustancias"],["Antecedentes psicológicos y psiquiátricos","Tratamientos previos, hospitalizaciones, intentos de suicidio"],["Historia familiar","Familiograma, relaciones, antecedentes de salud mental en la familia"],["Historia social y cultural","Red de apoyo, religión, migración, situación económica, violencia"],["Recursos y fortalezas","Qué le ha ayudado, intereses, habilidades"]]},{"tipo":"tarjetas","rotulo":"Adaptaciones según a quién entrevistas","tarjetas":[{"frente":"Adolescentes","reverso":"Explica la confidencialidad y sus límites frente al adolescente y su tutor juntos. Dedica un tiempo a solas con el adolescente. Usa su lenguaje y evita el tono de regaño."},{"frente":"Parejas","reverso":"Entrevista conjunta y, si lo acuerdan, un espacio individual con cada quien. Acuerda desde el inicio qué pasa con los «secretos». Pregunta siempre por violencia de forma individual y segura."},{"frente":"Familias","reverso":"Observa quién habla, quién interrumpe, quién queda fuera. Dale voz a cada integrante, incluidos los niños. El «paciente identificado» suele expresar un problema del sistema familiar."},{"frente":"Si sospechas violencia","reverso":"No confrontes a la pareja o familia en conjunto: puede aumentar el riesgo. Evalúa por separado y prioriza la seguridad."}]},{"tipo":"comparar","titulo":"Primera sesión con un adolescente y su mamá","malTitulo":"Así no","mal":"La psicóloga habla 40 minutos con la mamá frente al adolescente, que escucha en silencio cómo lo describen como «flojo y grosero». Al final le pregunta: «¿Y tú qué opinas?».","bienTitulo":"Así sí","bien":"La psicóloga explica el encuadre a ambos, escucha brevemente a la mamá, luego pide hablar a solas con el adolescente: «Me interesa conocer tu versión. ¿Qué crees que está pasando?»."},{"tipo":"relacionar","rotulo":"Relaciona cada dato con su apartado","pares":[["Toma sertralina desde hace un año","Antecedentes personales"],["Su abuela materna tuvo depresión","Historia familiar"],["Le encanta tocar la guitarra y lo calma","Recursos y fortalezas"],["El insomnio empezó hace 6 semanas y ha empeorado","Padecimiento actual"]]},{"tipo":"reflexion","rotulo":"Tu primera historia clínica","pregunta":"Piensa en una entrevista que hayas hecho (en prácticas o en clase). ¿Qué apartado de la historia clínica te cuesta más explorar y por qué?","ayuda":"Me cuesta preguntar por… porque… Podría abordarlo diciendo…"},{"tipo":"clave","items":["La historia clínica se completa a lo largo de la evaluación y se centra en lo relevante para el motivo de consulta.","Con adolescentes, tiempo a solas y confidencialidad explicada a ambos.","En parejas y familias, observa el sistema; ante sospecha de violencia, evalúa por separado."]}]}],"quiz":{"titulo":"Evaluación del módulo 1","preguntas":[{"p":"¿Cuál de estos elementos forma parte del encuadre?","ops":["El diagnóstico definitivo","El resultado de las pruebas","La política de cancelaciones"],"correcta":2},{"p":"El consentimiento informado con un menor de edad requiere…","ops":["Ninguna autorización si la escuela lo refiere","Consentimiento del tutor y asentimiento del menor","Solo la firma del menor"],"correcta":1},{"p":"¿Cuál es un límite de la confidencialidad?","ops":["Riesgo grave para la vida del paciente o de terceros","Que la familia quiera saber cómo va","Que el paciente falte a una sesión"],"correcta":0},{"p":"La entrevista semiestructurada se caracteriza por…","ops":["Leer siempre las mismas preguntas en el mismo orden","No tener ningún plan previo","Tener una guía de temas con orden y palabras flexibles"],"correcta":2},{"p":"«Ya no puedo con mi vida» es un motivo…","ops":["Irrelevante para la evaluación","Expresado, que debes precisar con preguntas","Clínico, listo para el expediente"],"correcta":1},{"p":"Los tres componentes de la alianza terapéutica son…","ops":["Vínculo, acuerdo en metas y acuerdo en tareas","Diagnóstico, pronóstico y tratamiento","Puntualidad, pago y asistencia"],"correcta":0},{"p":"En una entrevista de pareja en la que sospechas violencia, lo indicado es…","ops":["Confrontarlos juntos para que lo reconozcan","Ignorarlo hasta tener pruebas","Evaluar a cada integrante por separado y priorizar la seguridad"],"correcta":2},{"p":"Si eres estudiante y atiendes pacientes en prácticas, debes…","ops":["Diagnosticar sin supervisión si ya terminaste el diplomado","Revisar tus casos con tu supervisor","Tomar decisiones clínicas solo"],"correcta":1}]}},{"id":"d-evaluacion-clinica-m2","titulo":"Módulo 2 — Evaluación: estado mental, riesgo e instrumentos","resumen":"La estructura del examen del estado mental y la observación clínica; el tamizaje de riesgo de suicidio, violencia, consumo y maltrato con su protocolo de actuación; instrumentos de tamizaje de uso libre como el PHQ-9 y el GAD-7; qué hace estandarizado a un instrumento, por qué importan la validez y los baremos mexicanos, y cuándo derivar. Cuatro lecciones y una evaluación.","lecciones":[{"id":"d-evaluacion-clinica-m2-l1","titulo":"Lección 1 — El examen del estado mental y la observación clínica","objetivo":"describir el estado mental de un paciente con la estructura estándar y con lenguaje observable, sin interpretaciones.","bloques":[{"tipo":"texto","texto":"El <b>examen del estado mental</b> (EEM) es una «fotografía» de cómo está la persona <b>en el momento de la entrevista</b>. No es una prueba aparte: lo haces mientras conversas y observas. Sirve para detectar datos que el paciente no reporta (por ejemplo, un pensamiento desorganizado) y para comparar su evolución entre sesiones."},{"tipo":"tabla","titulo":"Estructura del examen del estado mental","encabezados":["Área","Qué observas o exploras","Ejemplo de redacción"],"filas":[["Apariencia y conducta","Aliño, vestimenta, contacto visual, actividad motora","Aliño adecuado, contacto visual intermitente, inquietud motora leve"],["Actitud","Cooperación, suspicacia, hostilidad","Cooperadora, con respuestas breves"],["Lenguaje","Velocidad, volumen, fluidez","Lenguaje de velocidad lenta y volumen bajo"],["Estado de ánimo y afecto","Ánimo reportado (en sus palabras) y afecto observado","Refiere sentirse «vacía»; afecto triste, congruente, de rango restringido"],["Pensamiento: curso y contenido","Organización; preocupaciones, ideas de muerte, ideas delirantes","Curso coherente; contenido centrado en culpa; ideas pasivas de muerte sin plan"],["Percepción","Alucinaciones u otras alteraciones","Niega alteraciones sensoperceptivas"],["Cognición","Orientación, atención, memoria","Orientada en tiempo, lugar y persona; atención conservada"],["Juicio e introspección","Conciencia del problema y toma de decisiones","Reconoce que necesita ayuda; juicio conservado"]]},{"tipo":"comparar","titulo":"Redactar el EEM","malTitulo":"Interpretativo","mal":"«La paciente se ve deprimida y manipuladora, seguro exagera para llamar la atención.»","bienTitulo":"Descriptivo","bien":"«Llora en dos momentos al hablar de su hijo; afecto triste congruente con el discurso; solicita en tres ocasiones que se le extienda la sesión.»"},{"tipo":"destacado","texto":"<b>Regla de oro:</b> escribe lo que <b>viste y escuchaste</b>, no lo que supones. «Manipulador», «histérica» o «flojo» son juicios, no observaciones, y pueden perjudicar al paciente si otro profesional lee tu expediente."},{"tipo":"relacionar","rotulo":"¿A qué área del EEM pertenece?","pares":[["Habla muy rápido y es difícil interrumpirlo","Lenguaje"],["No sabe en qué mes estamos","Cognición"],["Dice escuchar voces cuando está solo","Percepción"],["Cree que sus vecinos lo espían a través del televisor","Pensamiento"],["Niega tener cualquier problema aunque lo trajeron por varios incidentes","Juicio e introspección"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"El examen del estado mental describe…","ops":["Su diagnóstico definitivo","Cómo está la persona en el momento de la entrevista","Toda su historia de vida"],"correcta":1,"explica":"Por eso se repite y se compara entre sesiones."},{"p":"¿Cuál es una descripción observable?","ops":["Evita el contacto visual y responde con monosílabos","Es una persona evasiva por naturaleza","Seguro oculta algo"],"correcta":0}]},{"tipo":"clave","items":["El EEM es una fotografía del momento: apariencia, actitud, lenguaje, ánimo y afecto, pensamiento, percepción, cognición, juicio.","Se hace mientras entrevistas y observas.","Redacta observaciones, no juicios ni etiquetas."]}]},{"id":"d-evaluacion-clinica-m2-l2","titulo":"Lección 2 — Tamizaje de riesgo: suicidio, violencia, consumo y maltrato","objetivo":"preguntar directamente por el riesgo y aplicar un protocolo de actuación cuando hay peligro para el paciente o para otros.","bloques":[{"tipo":"destacado","texto":"<b>En toda primera consulta se explora el riesgo</b>, aunque el motivo parezca «leve». Preguntar directamente por el suicidio <b>no aumenta el riesgo</b>: la evidencia indica que suele aliviar al paciente y abre la puerta a la ayuda. Si hay peligro inmediato: <b>911</b>. Para orientación y acompañamiento, <b>Línea de la Vida 800 911 2000</b> (gratuita, 24 horas)."},{"tipo":"tabla","titulo":"Qué explorar en cada área de riesgo","encabezados":["Área","Preguntas guía","Señales de alarma"],"filas":[["Suicidio","«¿Has pensado en la muerte o en quitarte la vida?» «¿Has pensado cómo?» «¿Lo has intentado antes?»","Plan concreto, acceso a medios, intento previo, desesperanza, despedidas"],["Violencia hacia otros","«¿Has pensado en lastimar a alguien?» «¿Has tenido peleas físicas?»","Amenazas a una persona identificable, acceso a armas, antecedentes de violencia"],["Consumo de sustancias","«En una semana normal, ¿cuánto alcohol tomas?» «¿Usas alguna otra sustancia?»","Consumo diario, pérdida de control, intoxicación en sesión, mezcla con medicamentos"],["Maltrato y violencia recibida","«¿Alguien en tu casa te ha lastimado o te da miedo?»","Lesiones, miedo a regresar a casa, menor de edad o adulto mayor en riesgo"]],"nota":"Existen instrumentos de uso libre que ayudan a estructurar estas preguntas, como la Escala Columbia para Evaluar la Seriedad de la Ideación Suicida (C-SSRS) o el AUDIT de la OMS para alcohol. Ninguno sustituye el juicio clínico."},{"tipo":"pasos","rotulo":"Protocolo de actuación ante riesgo suicida","pasos":["<b>Pregunta directamente</b> y con calma; escucha sin juzgar ni minimizar.","<b>Estima el nivel de riesgo:</b> ideas pasivas, ideas activas, plan, intención, acceso a medios, intentos previos.","<b>Riesgo inminente</b> (plan e intención para hoy, o acceso a medios): no dejes sola a la persona, llama al <b>911</b> o acompáñala a urgencias, avisa a un familiar o contacto de emergencia.","<b>Riesgo presente no inminente:</b> elabora con el paciente un <b>plan de seguridad</b> (señales de alerta, estrategias propias, personas y lugares, profesionales, Línea de la Vida 800 911 2000, restringir el acceso a medios).","<b>Deriva</b> a valoración psiquiátrica cuando corresponda y aumenta la frecuencia de contacto.","<b>Documenta</b> lo preguntado, lo respondido, tu estimación y las acciones tomadas.","<b>Consulta con tu supervisor</b> o un colega el mismo día."]},{"tipo":"comparar","titulo":"Preguntar por el suicidio","malTitulo":"Así no","mal":"«No estarás pensando en hacer una tontería, ¿verdad?» (la pregunta invita a decir que no y juzga).","bienTitulo":"Así sí","bien":"«A veces, cuando alguien se siente tan mal como me cuentas, piensa en quitarse la vida. ¿Te ha pasado a ti?»"},{"tipo":"ordenar","rotulo":"Ordena el primer paso ante riesgo inminente","items":[{"frase":"no dejes sola a la persona y llama al 911","es":"La seguridad inmediata va antes que cualquier otra tarea clínica."}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Preguntar directamente a un paciente si piensa en suicidarse…","ops":["Le mete la idea en la cabeza","Solo debe hacerlo un psiquiatra","No aumenta el riesgo y permite ofrecer ayuda"],"correcta":2,"explica":"Es un mito que preguntar induzca la conducta."},{"p":"Un paciente dice que tiene pastillas guardadas y piensa tomarlas hoy. Lo indicado es…","ops":["Pedirle que prometa que no lo hará y terminar la sesión","No dejarlo solo y activar emergencias (911 o urgencias)","Darle cita para la próxima semana"],"correcta":1},{"p":"Un plan de seguridad incluye…","ops":["Señales de alerta, contactos, profesionales y restricción de medios","Solo la promesa firmada de no suicidarse","Un diagnóstico definitivo"],"correcta":0}]},{"tipo":"clave","items":["Explora riesgo en toda primera consulta: suicidio, violencia, consumo y maltrato.","Riesgo inminente: no dejes sola a la persona y activa el 911 o urgencias; Línea de la Vida 800 911 2000 para orientación.","Plan de seguridad, derivación, documentación y supervisión el mismo día."]}]},{"id":"d-evaluacion-clinica-m2-l3","titulo":"Lección 3 — Instrumentos de tamizaje de uso libre: PHQ-9 y GAD-7","objetivo":"calificar e interpretar el PHQ-9 y el GAD-7 como herramientas de tamizaje, sin confundirlos con un diagnóstico.","bloques":[{"tipo":"texto","texto":"El <b>PHQ-9</b> (síntomas depresivos, 9 reactivos) y el <b>GAD-7</b> (síntomas de ansiedad generalizada, 7 reactivos) son cuestionarios breves y de <b>uso libre</b>: sus autores y Pfizer los pusieron a disposición del público sin costo. Cada reactivo pregunta con qué frecuencia se presentó un síntoma en las <b>últimas dos semanas</b> y se califica de <b>0 (nunca) a 3 (casi todos los días)</b>. Consigue siempre la versión oficial en español desde una fuente confiable; aquí no reproducimos los reactivos."},{"tipo":"tabla","titulo":"Rangos de interpretación habituales","encabezados":["Instrumento","Rango total","Cortes de severidad"],"filas":[["PHQ-9","0 a 27","0–4 mínima · 5–9 leve · 10–14 moderada · 15–19 moderadamente grave · 20–27 grave"],["GAD-7","0 a 21","0–4 mínima · 5–9 leve · 10–14 moderada · 15–21 grave"]],"nota":"El reactivo 9 del PHQ-9 explora pensamientos de muerte o de hacerse daño: <b>cualquier respuesta distinta de 0</b> obliga a evaluar el riesgo en esa misma sesión, sin importar el total."},{"tipo":"excel","rotulo":"Tamizaje de Laura (caso ficticio)","datos":[["Reactivo","PHQ-9","GAD-7","","Resultado","Valor"],[1,2,2,"","Total PHQ-9",""],[2,2,3,"","Severidad PHQ-9",""],[3,3,2,"","Total GAD-7",""],[4,1,1,"","Severidad GAD-7",""],[5,2,1,"","Alerta reactivo 9",""],[6,2,2],[7,1,1],[8,1],[9,1]],"retos":[{"celda":"F2","formula":"=SUMA(B2:B10)","esperado":15,"requiere":"SUMA(","texto":"<b>F2</b>: suma los 9 reactivos del PHQ-9."},{"celda":"F3","formula":"=SI(F2>=20,\"Grave\",SI(F2>=15,\"Moderadamente grave\",SI(F2>=10,\"Moderada\",SI(F2>=5,\"Leve\",\"Mínima\"))))","esperado":"Moderadamente grave","requiere":"SI(","texto":"<b>F3</b>: asigna la severidad con SI anidados usando los cortes 20, 15, 10 y 5.","pista":"=SI(F2>=20,\"Grave\",SI(F2>=15,\"Moderadamente grave\",SI(F2>=10,\"Moderada\",SI(F2>=5,\"Leve\",\"Mínima\"))))"},{"celda":"F4","formula":"=SUMA(C2:C8)","esperado":12,"requiere":"SUMA(","texto":"<b>F4</b>: suma los 7 reactivos del GAD-7."},{"celda":"F5","formula":"=SI(F4>=15,\"Grave\",SI(F4>=10,\"Moderada\",SI(F4>=5,\"Leve\",\"Mínima\")))","esperado":"Moderada","requiere":"SI(","texto":"<b>F5</b>: asigna la severidad del GAD-7 con los cortes 15, 10 y 5."},{"celda":"F6","formula":"=SI(B10>0,\"Evaluar riesgo hoy\",\"Sin alerta\")","esperado":"Evaluar riesgo hoy","requiere":"SI(","texto":"<b>F6</b>: si el reactivo 9 del PHQ-9 (B10) es mayor que 0, escribe «Evaluar riesgo hoy»; si no, «Sin alerta».","explica":"Aunque el total de Laura no es «grave», su reactivo 9 vale 1: la psicóloga debe explorar el riesgo suicida en esta misma sesión con el protocolo de la lección anterior."}]},{"tipo":"destacado","texto":"<b>Tamizar no es diagnosticar.</b> Un PHQ-9 de 15 indica que conviene una evaluación clínica cuidadosa, no que la persona «tiene depresión». El diagnóstico requiere entrevista, criterios clínicos, duración, deterioro funcional y descartar otras causas (por ejemplo, hipotiroidismo o efectos de medicamentos)."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Un PHQ-9 de 12 significa…","ops":["Diagnóstico confirmado de depresión mayor","Que no hay nada de qué preocuparse","Síntomas en rango moderado que requieren evaluación clínica"],"correcta":2,"explica":"Es un resultado de tamizaje; el diagnóstico se establece con la evaluación completa."},{"p":"El PHQ-9 total es 6, pero el reactivo 9 vale 2. Debes…","ops":["Esperar a la siguiente aplicación","Evaluar el riesgo suicida en esa misma sesión","Ignorarlo porque el total es leve"],"correcta":1},{"p":"El periodo que evalúan el PHQ-9 y el GAD-7 es…","ops":["Las últimas dos semanas","El último año","Toda la vida"],"correcta":0}]},{"tipo":"clave","items":["PHQ-9 (0–27) y GAD-7 (0–21): tamizaje breve y de uso libre; cortes 5, 10, 15 (y 20 en PHQ-9).","Cualquier puntaje mayor que 0 en el reactivo 9 del PHQ-9 obliga a evaluar riesgo ese día.","Un puntaje alto orienta la evaluación; no sustituye el diagnóstico clínico."]}]},{"id":"d-evaluacion-clinica-m2-l4","titulo":"Lección 4 — Instrumentos estandarizados, baremos mexicanos y cuándo derivar","objetivo":"explicar qué hace confiable a un instrumento, por qué importan los baremos en población mexicana y cuándo derivar a evaluación neuropsicológica o psiquiátrica.","bloques":[{"tipo":"texto","texto":"Un <b>instrumento estandarizado</b> se aplica y califica siempre de la misma manera y se interpreta comparando el resultado con un grupo de referencia (la <b>muestra normativa</b>). Para que sirva necesita:<br>• <b>Confiabilidad:</b> mide de forma consistente (si lo aplicas dos veces sin cambios reales, da resultados parecidos).<br>• <b>Validez:</b> mide lo que dice medir y sus conclusiones son útiles para el fin que buscas.<br>• <b>Baremos</b> (normas): tablas que convierten el puntaje bruto en percentiles o puntajes estándar según la población de referencia."},{"tipo":"destacado","texto":"<b>¿Por qué importa la población mexicana?</b> Un instrumento creado y normado en otro país puede funcionar distinto aquí por idioma, escolaridad, cultura o nivel socioeconómico. Si usas baremos ajenos, puedes <b>sobrediagnosticar o subdiagnosticar</b>. Antes de usar una prueba, busca si tiene <b>adaptación y validación en México</b>, con qué muestra (edad, región, escolaridad) y en qué año. Usa solo pruebas adquiridas legalmente: muchas están protegidas por derechos de autor y su venta está restringida a profesionales."},{"tipo":"excel","rotulo":"Mismo puntaje, dos baremos (datos ficticios con fines didácticos)","datos":[["Puntaje bruto desde","Percentil baremo extranjero","Percentil baremo mexicano","","Dato","Valor"],[0,10,5,"","Puntaje bruto de Mariana",24],[10,40,25,"","Percentil con baremo extranjero",""],[15,70,50,"","Percentil con baremo mexicano",""],[20,92,75,"","Diferencia de percentiles",""],[25,97,90,"","Interpretación con baremo mexicano",""],[30,99,97]],"retos":[{"celda":"F3","formula":"=BUSCARV(F2,$A$2:$C$7,2,VERDADERO)","esperado":92,"requiere":"BUSCARV(","texto":"<b>F3</b>: busca el percentil de Mariana en la columna del baremo extranjero con BUSCARV aproximado.","pista":"=BUSCARV(F2,$A$2:$C$7,2,VERDADERO). Con VERDADERO toma el renglón más grande que no pasa de 24."},{"celda":"F4","formula":"=BUSCARV(F2,$A$2:$C$7,3,VERDADERO)","esperado":75,"requiere":"BUSCARV(","texto":"<b>F4</b>: ahora búscalo en el baremo mexicano (tercera columna)."},{"celda":"F5","formula":"=F3-F4","esperado":17,"texto":"<b>F5</b>: calcula la diferencia entre ambos percentiles."},{"celda":"F6","formula":"=SI(F4>=90,\"Elevado\",\"No elevado\")","esperado":"No elevado","requiere":"SI(","texto":"<b>F6</b>: si el percentil mexicano es de 90 o más, escribe «Elevado»; si no, «No elevado».","explica":"Con el baremo extranjero, Mariana quedaría en el percentil 92 y parecería «elevada»; con el mexicano está en el 75. El mismo puntaje bruto cambia de significado según con quién la comparas."}]},{"tipo":"tabla","titulo":"Cuándo derivar","encabezados":["Derivar a…","Señales"],"filas":[["Evaluación neuropsicológica","Quejas de memoria o atención que interfieren con la vida diaria, cambios cognitivos después de un golpe en la cabeza, sospecha de deterioro cognitivo en adultos mayores, dificultades de aprendizaje persistentes que requieren perfil detallado"],["Valoración psiquiátrica","Riesgo suicida, síntomas psicóticos, sospecha de episodio maníaco, depresión grave que no mejora, consumo con abstinencia, necesidad de evaluar medicación"],["Valoración médica","Síntomas que pueden tener causa física: cambios bruscos de peso, palpitaciones, fatiga extrema, síntomas nuevos después de los 50 años"]],"nota":"Derivar no es «deshacerte» del paciente: muchas veces sigues trabajando con él en coordinación con el otro profesional."},{"tipo":"relacionar","rotulo":"Relaciona el concepto","pares":[["Da resultados consistentes en aplicaciones repetidas","Confiabilidad"],["Mide lo que dice medir","Validez"],["Tabla que convierte puntajes brutos en percentiles","Baremo"],["Grupo con el que se compara al evaluado","Muestra normativa"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Una prueba con baremos de otro país aplicada en México puede…","ops":["Dar siempre el mismo resultado","Volverse más confiable","Sobrediagnosticar o subdiagnosticar"],"correcta":2},{"p":"Un paciente de 68 años refiere que olvida citas y se pierde en su colonia. Conviene…","ops":["Decirle que es normal por la edad","Derivar a evaluación neuropsicológica y médica","Aplicar solo el GAD-7"],"correcta":1}]},{"tipo":"clave","items":["Un instrumento estandarizado necesita confiabilidad, validez y baremos adecuados.","Prefiere pruebas validadas y normadas en población mexicana; el mismo puntaje cambia de sentido según el baremo.","Deriva a neuropsicología, psiquiatría o medicina cuando las señales lo indiquen, y coordina."]}]}],"quiz":{"titulo":"Evaluación del módulo 2","preguntas":[{"p":"El examen del estado mental describe…","ops":["Su historia familiar completa","Su pronóstico a cinco años","El estado de la persona durante la entrevista"],"correcta":2},{"p":"¿Cuál es una redacción adecuada para el expediente?","ops":["Exagera para llamar la atención","Llora al hablar de su hijo; afecto triste congruente","Paciente histérica y manipuladora"],"correcta":1},{"p":"Preguntar directamente por ideas suicidas…","ops":["No aumenta el riesgo","Induce la conducta suicida","Está prohibido en la primera sesión"],"correcta":0},{"p":"Ante riesgo suicida inminente, lo primero es…","ops":["Asignar tarea para la próxima sesión","Aplicar una batería completa de pruebas","No dejar sola a la persona y activar el 911 o urgencias"],"correcta":2},{"p":"En el PHQ-9, un total de 17 corresponde a…","ops":["Mínima","Moderadamente grave","Leve"],"correcta":1},{"p":"El PHQ-9 y el GAD-7 son…","ops":["Instrumentos de tamizaje de uso libre","Pruebas diagnósticas definitivas","Escalas de inteligencia"],"correcta":0},{"p":"Los baremos sirven para…","ops":["Calificar la alianza terapéutica","Sustituir la entrevista clínica","Comparar el puntaje del evaluado con una población de referencia"],"correcta":2},{"p":"Quejas de memoria que interfieren con la vida diaria sugieren derivar a…","ops":["Ninguna parte, es normal","Evaluación neuropsicológica","Coaching de productividad"],"correcta":1}]}},{"id":"d-evaluacion-clinica-m3","titulo":"Módulo 3 — Diagnóstico con criterio","resumen":"Para qué sirven la CIE-11 y el DSM-5-TR y cuáles son sus límites; un método de diagnóstico diferencial básico; cómo pensar la comorbilidad; y cómo usar y comunicar un diagnóstico sin etiquetar a la persona, con ejercicios sobre casos ficticios. Cuatro lecciones y una evaluación.","lecciones":[{"id":"d-evaluacion-clinica-m3-l1","titulo":"Lección 1 — CIE-11 y DSM-5-TR: para qué sirven y cuáles son sus límites","objetivo":"comparar la CIE-11 y el DSM-5-TR y explicar para qué sirve un diagnóstico y qué no puede decirte.","bloques":[{"tipo":"texto","texto":"Un diagnóstico es un <b>lenguaje común</b>: permite que profesionales distintos se entiendan, elegir tratamientos con evidencia, hacer estadística de salud pública y, en algunos casos, acceder a servicios o incapacidades. Las dos clasificaciones principales son la <b>CIE-11</b> de la Organización Mundial de la Salud y el <b>DSM-5-TR</b> de la Asociación Americana de Psiquiatría."},{"tipo":"tabla","titulo":"CIE-11 y DSM-5-TR de un vistazo","encabezados":["Aspecto","CIE-11 (OMS)","DSM-5-TR (APA)"],"filas":[["Quién la publica","Organización Mundial de la Salud","Asociación Americana de Psiquiatría"],["Vigencia","Entró en vigor el 1 de enero de 2022","Publicado en marzo de 2022 (revisión de texto del DSM-5 de 2013)"],["Alcance","Todas las enfermedades; los trastornos mentales están en el capítulo 06","Solo trastornos mentales"],["Estilo","Requisitos diagnósticos esenciales, con más espacio para el juicio clínico","Criterios con umbrales precisos (número de síntomas, duración)"],["Acceso","Consulta gratuita en línea (icd.who.int)","Libro con derechos de autor"],["Uso habitual","Estadística oficial y sistemas de salud en muchos países","Investigación y práctica clínica, sobre todo en Estados Unidos"]],"nota":"Verifica qué clasificación y qué versión pide tu institución: en muchos sistemas de salud la transición de la CIE-10 a la CIE-11 sigue en curso al momento de escribir."},{"tipo":"comparar","titulo":"Lo que un diagnóstico dice y lo que no","malTitulo":"Lo que NO te dice","mal":"Por qué esta persona en particular sufre, qué la mantiene así, qué recursos tiene, qué le importa, ni qué tratamiento exacto elegir para ella.","bienTitulo":"Lo que SÍ te dice","bien":"Qué patrón de síntomas presenta, qué tan frecuente es, qué curso suele tener y qué tratamientos tienen evidencia para ese patrón en general."},{"tipo":"lista","items":["<b>Límite 1:</b> las categorías son acuerdos de expertos, no «cosas» que existan dentro de la persona; los límites entre normal y trastorno son graduales.","<b>Límite 2:</b> dos personas con el mismo diagnóstico pueden parecerse muy poco (el DSM permite muchas combinaciones de síntomas).","<b>Límite 3:</b> la cultura influye en cómo se expresa el malestar; ambos manuales incluyen apartados culturales que conviene revisar.","<b>Por eso</b> el diagnóstico se complementa con la <b>formulación del caso</b> (Módulo 4)."]},{"tipo":"relacionar","rotulo":"Relaciona cada clasificación","pares":[["CIE-11","Clasifica todas las enfermedades y se consulta gratis"],["DSM-5-TR","Solo trastornos mentales, con umbrales precisos"],["Capítulo 06 de la CIE-11","Trastornos mentales, del comportamiento o del neurodesarrollo"],["CIE-10","Versión anterior que aún usan algunos sistemas de salud"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"El principal valor de un diagnóstico es…","ops":["Ofrecer un lenguaje común y orientar hacia tratamientos con evidencia","Explicar por completo a la persona","Sustituir la formulación del caso"],"correcta":0,"explica":"Por eso se complementa con la formulación."},{"p":"Los trastornos mentales en la CIE-11 están en el capítulo…","ops":["01","21","06"],"correcta":2},{"p":"Dos pacientes con el mismo diagnóstico…","ops":["Tienen exactamente los mismos síntomas","Pueden tener síntomas e historias muy distintas","Siempre necesitan el mismo tratamiento"],"correcta":1}]},{"tipo":"clave","items":["CIE-11 (OMS, vigente desde 2022, gratuita) y DSM-5-TR (APA, 2022) son lenguajes comunes, no explicaciones de la persona.","La CIE-11 da más espacio al juicio clínico; el DSM-5-TR usa umbrales precisos.","El diagnóstico orienta; la formulación explica este caso en particular."]}]},{"id":"d-evaluacion-clinica-m3-l2","titulo":"Lección 2 — Diagnóstico diferencial básico","objetivo":"aplicar una secuencia de diagnóstico diferencial que descarte causas médicas, sustancias y otras explicaciones antes de concluir.","bloques":[{"tipo":"texto","texto":"El <b>diagnóstico diferencial</b> es preguntarte: «¿Qué otra cosa podría explicar esto?». Un error frecuente de principiante es quedarse con la primera hipótesis que «cuadra». Un síntoma como la tristeza, el insomnio o la dificultad para concentrarse aparece en muchos cuadros distintos."},{"tipo":"pasos","rotulo":"Secuencia básica de diagnóstico diferencial","pasos":["<b>¿Hay una causa médica?</b> Hipotiroidismo, anemia, dolor crónico, efectos de medicamentos: deriva a valoración médica si hay sospecha.","<b>¿Hay consumo de sustancias?</b> Alcohol, estimulantes, cannabis, abstinencia: pueden producir ansiedad, ánimo bajo o psicosis.","<b>¿Es una reacción esperable?</b> Duelo, estrés por una pérdida de empleo: no todo malestar es un trastorno.","<b>¿Qué cuadros comparten estos síntomas?</b> Enlista al menos dos o tres hipótesis.","<b>¿Qué dato las distingue?</b> Duración, curso, edad de inicio, episodios de euforia, contenido de las preocupaciones.","<b>Busca ese dato</b> con preguntas, observación, instrumentos o información de terceros (con consentimiento).","<b>Concluye con prudencia:</b> diagnóstico provisional si falta información."]},{"tipo":"tabla","titulo":"Síntomas compartidos, datos que distinguen","encabezados":["Presentación","Hipótesis","Dato clave para distinguir"],"filas":[["Ánimo bajo y cansancio","Episodio depresivo · hipotiroidismo · duelo","Valoración médica; relación temporal con una pérdida; síntomas de inutilidad o culpa"],["Ánimo bajo recurrente","Trastorno depresivo · trastorno bipolar","Preguntar siempre por episodios previos de euforia, poco sueño sin cansancio o gasto excesivo"],["Dificultad para concentrarse","TDAH · ansiedad · depresión · falta de sueño","Inicio en la infancia y presencia en varios contextos (TDAH) contra inicio reciente"],["Palpitaciones y miedo intenso","Trastorno de pánico · problema cardíaco · consumo de estimulantes","Valoración médica; consumo de cafeína, bebidas energéticas u otras sustancias"]]},{"tipo":"destacado","texto":"<b>Caso ficticio.</b> Rodrigo, 34 años, consulta por «depresión»: duerme mal, está irritable y no rinde en el trabajo desde hace dos meses. En la entrevista refiere que hace un año pasó una semana durmiendo 3 horas sin cansarse, gastó sus ahorros en un negocio impulsivo y sus amigos le decían que «hablaba sin parar». Este dato cambia la hipótesis: hay que explorar un posible trastorno bipolar y derivar a valoración psiquiátrica, porque el tratamiento difiere."},{"tipo":"practica","rotulo":"Practica con casos ficticios","preguntas":[{"p":"Ana, 52 años, refiere ánimo bajo, aumento de peso y mucho frío desde hace meses. Antes de concluir un diagnóstico psicológico conviene…","ops":["Derivar a valoración médica para descartar causas físicas","Diagnosticar depresión de inmediato","Aplicar una prueba de personalidad"],"correcta":0,"explica":"Algunos síntomas sugieren una causa médica, como un problema de tiroides; se descarta primero."},{"p":"Beto, 19 años, tiene crisis de ansiedad desde que toma cuatro bebidas energéticas al día para estudiar. Lo primero es…","ops":["Diagnosticar trastorno de pánico","Recomendar más café para rendir","Explorar y reducir el consumo de estimulantes antes de concluir"],"correcta":2},{"p":"Carmen perdió a su esposo hace tres semanas y llora todos los días. Lo más prudente es…","ops":["Decirle que ya debería superarlo","Considerar un duelo esperable y dar seguimiento","Diagnosticar un trastorno depresivo"],"correcta":1}]},{"tipo":"completar","rotulo":"Completa","items":[{"frase":"Ante ánimo bajo recurrente, pregunta siempre por episodios previos de ___.","resp":["euforia","manía","hipomanía"]},{"frase":"Si falta información, el diagnóstico se registra como ___.","resp":["provisional","presuntivo"]}]},{"tipo":"clave","items":["Pregúntate siempre «¿qué otra cosa podría explicar esto?».","Descarta primero causas médicas, sustancias y reacciones esperables como el duelo.","Busca el dato que distingue las hipótesis y, si falta, deja el diagnóstico como provisional."]}]},{"id":"d-evaluacion-clinica-m3-l3","titulo":"Lección 3 — Comorbilidad","objetivo":"identificar la comorbilidad frecuente y decidir qué problema atender primero.","bloques":[{"tipo":"texto","texto":"<b>Comorbilidad</b> es la presencia de dos o más condiciones al mismo tiempo en la misma persona. En salud mental es la regla más que la excepción: la ansiedad y la depresión suelen ir juntas; el consumo de alcohol acompaña con frecuencia a la ansiedad social o al trauma; el TDAH en adultos se acompaña a menudo de problemas de ánimo o consumo."},{"tipo":"tabla","titulo":"Combinaciones frecuentes y qué vigilar","encabezados":["Combinación","Qué vigilar"],"filas":[["Depresión y ansiedad","Mayor gravedad y riesgo; los tratamientos basados en evidencia a menudo abordan ambas"],["Ansiedad y consumo de alcohol","El alcohol puede funcionar como «automedicación» y empeorar la ansiedad a mediano plazo"],["Trauma y depresión","Explora experiencias traumáticas con cuidado antes de planear el tratamiento"],["Problemas de salud física y ánimo","El dolor crónico o la diabetes pueden mantener el ánimo bajo; coordina con el médico"]]},{"tipo":"excel","rotulo":"Comorbilidad en un consultorio (casos ficticios)","datos":[["Paciente","Problema principal","Segundo problema","¿Comorbilidad?","","Indicador","Valor"],["P01","Depresión","Ansiedad","","","Pacientes con comorbilidad",""],["P02","Ansiedad","Ninguno","","","Total de pacientes",""],["P03","Depresión","Consumo de alcohol","","","Porcentaje con comorbilidad",""],["P04","Trauma","Depresión","","","Principal: depresión",""],["P05","Ansiedad","Consumo de alcohol"],["P06","Depresión","Ninguno"],["P07","Ansiedad","Depresión"],["P08","Duelo","Ninguno"]],"retos":[{"celda":"D2","formula":"=SI(C2=\"Ninguno\",\"No\",\"Sí\")","esperado":"Sí","requiere":"SI(","texto":"<b>D2</b>: si el segundo problema es «Ninguno», escribe «No»; si no, «Sí». (Las filas D3 a D9 se llenarían igual; aquí solo haces la primera.)"},{"celda":"G2","formula":"=CONTAR.SI(C2:C9,\"<>Ninguno\")","esperado":5,"requiere":"CONTAR.SI(","texto":"<b>G2</b>: cuenta cuántos pacientes tienen un segundo problema distinto de «Ninguno».","pista":"=CONTAR.SI(C2:C9,\"<>Ninguno\"). El signo <> significa «distinto de»."},{"celda":"G3","formula":"=CONTARA(A2:A9)","esperado":8,"requiere":"CONTARA(","texto":"<b>G3</b>: cuenta el total de pacientes con CONTARA."},{"celda":"G4","formula":"=REDONDEAR(G2/G3*100,1)","esperado":62.5,"requiere":"REDONDEAR(","texto":"<b>G4</b>: calcula el porcentaje con comorbilidad, redondeado a un decimal."},{"celda":"G5","formula":"=CONTAR.SI(B2:B9,\"Depresión\")","esperado":3,"requiere":"CONTAR.SI(","texto":"<b>G5</b>: cuenta cuántos pacientes tienen depresión como problema principal.","explica":"En este consultorio ficticio, más de la mitad de los pacientes presenta un segundo problema. Por eso la evaluación no termina al encontrar el primer diagnóstico."}]},{"tipo":"lista","items":["<b>Atiende primero el riesgo:</b> suicidio, violencia o consumo grave van antes que todo.","<b>Después, lo que bloquea el resto:</b> si el consumo de alcohol impide asistir a sesiones, es prioritario.","<b>Luego, lo que más afecta al paciente</b> según él mismo.","<b>Revisa si un tratamiento sirve para ambos</b> (por ejemplo, intervenciones transdiagnósticas)."]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Comorbilidad significa…","ops":["Dos o más condiciones presentes al mismo tiempo","Un diagnóstico equivocado","Que el paciente exagera sus síntomas"],"correcta":0},{"p":"Un paciente tiene depresión moderada y un consumo de alcohol que le impide llegar a sus sesiones. ¿Qué atiendes primero?","ops":["Solo la depresión","Ninguno hasta tener más pruebas","El consumo, porque bloquea el tratamiento"],"correcta":2,"explica":"Lo que impide el tratamiento y lo que implica riesgo va primero."}]},{"tipo":"clave","items":["En salud mental, la comorbilidad es frecuente; no te detengas en el primer diagnóstico.","Prioriza: riesgo, lo que bloquea el tratamiento, lo que más afecta al paciente.","Busca intervenciones que atiendan varios problemas a la vez cuando haya evidencia."]}]},{"id":"d-evaluacion-clinica-m3-l4","titulo":"Lección 4 — Diagnosticar sin etiquetar","objetivo":"usar lenguaje centrado en la persona y comunicar un diagnóstico de forma clara, respetuosa y útil para el paciente.","bloques":[{"tipo":"texto","texto":"Un diagnóstico mal usado se vuelve <b>etiqueta</b>: define a la persona, la reduce a un problema y puede generar estigma, discriminación o una profecía autocumplida («si soy ansioso, nunca podré hablar en público»). Bien usado, <b>alivia</b>: «lo que me pasa tiene nombre, le pasa a más gente y hay tratamiento»."},{"tipo":"comparar","titulo":"Lenguaje centrado en la persona","malTitulo":"Etiqueta","mal":"«Es un TDAH.» «Tengo tres depresivos esta semana.» «Es una limítrofe.» «Está loco.» Usar «bipolar» o «esquizo» como adjetivo para describir a alguien cambiante.","bienTitulo":"Persona primero","bien":"«Es un niño con diagnóstico de TDAH.» «Tengo tres pacientes con depresión.» «Una paciente con rasgos de personalidad que estamos evaluando.» «Una persona que vive con un trastorno bipolar.»"},{"tipo":"pasos","rotulo":"Cómo comunicar un diagnóstico","pasos":["Pregunta primero qué sabe o qué cree que le pasa.","Nombra el diagnóstico con palabras sencillas y explica qué significa (y qué no).","Normaliza sin minimizar: es frecuente y tiene tratamiento con evidencia.","Conecta con su historia: por qué crees que apareció y qué lo mantiene (formulación).","Explica las opciones de tratamiento y decide con el paciente.","Pregunta cómo se siente con lo que escuchó y resuelve dudas."]},{"tipo":"plantilla","rotulo":"Ejemplo de devolución (caso ficticio)","texto":"Lupita, con lo que platicamos y los cuestionarios, lo que describes coincide con lo que en salud mental llamamos un trastorno de ansiedad generalizada. Esto no quiere decir que estés «mal de la cabeza» ni que vayas a estar así siempre: es un patrón de preocupación difícil de controlar que le pasa a mucha gente y que responde bien al tratamiento. En tu caso creo que empezó a crecer cuando entraste al nuevo trabajo y se mantiene porque revisas todo muchas veces para sentirte segura. Te propongo trabajar juntas con terapia cognitivo-conductual unas 12 sesiones. ¿Qué te parece lo que te acabo de decir?"},{"tipo":"ordenar","rotulo":"Ordena la frase centrada en la persona","items":[{"frase":"es una adolescente con diagnóstico de depresión","es":"La persona va primero y el diagnóstico la describe, no la define."}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"¿Cuál es la forma respetuosa?","ops":["Un loco peligroso","Una persona que vive con esquizofrenia","Un esquizofrénico"],"correcta":1},{"p":"Al comunicar un diagnóstico conviene empezar por…","ops":["Preguntar qué sabe o qué cree que le pasa","Leerle los criterios del manual","Darle el código de la CIE-11 y terminar la sesión"],"correcta":0}]},{"tipo":"reflexion","rotulo":"Tu lenguaje clínico","pregunta":"¿Qué expresiones etiquetadoras has escuchado (o usado) en clase, en prácticas o en pasillos de hospital? ¿Cómo las dirías de otra manera?","ayuda":"He escuchado… Podría decir en su lugar…"},{"tipo":"clave","items":["Un diagnóstico bien usado alivia y orienta; mal usado, etiqueta y estigmatiza.","Usa lenguaje centrado en la persona y evita diagnósticos como adjetivos.","Comunica el diagnóstico con palabras sencillas, conectado con su historia y con las opciones de tratamiento."]}]}],"quiz":{"titulo":"Evaluación del módulo 3","preguntas":[{"p":"La CIE-11 la publica…","ops":["La Asociación Americana de Psiquiatría","La Secretaría de Salud de México","La Organización Mundial de la Salud"],"correcta":2},{"p":"Un límite del diagnóstico categorial es que…","ops":["Nunca se relaciona con tratamientos","No explica por qué esta persona en particular sufre","No sirve para comunicarse entre profesionales"],"correcta":1},{"p":"El primer paso del diagnóstico diferencial es descartar…","ops":["Causas médicas y efectos de sustancias","La opinión de la familia","La alianza terapéutica"],"correcta":0},{"p":"Ante ánimo bajo recurrente, un dato clave que debes preguntar es…","ops":["Su signo zodiacal","Si le gusta su trabajo actual","Si ha tenido episodios de euforia o poco sueño sin cansancio"],"correcta":2},{"p":"Si falta información para concluir, el diagnóstico se registra como…","ops":["Descartado","Provisional","Definitivo"],"correcta":1},{"p":"Comorbilidad es…","ops":["La presencia simultánea de dos o más condiciones","Un error de diagnóstico","La cooperación entre profesionales"],"correcta":0},{"p":"En comorbilidad, lo que se atiende primero es…","ops":["Siempre el diagnóstico más antiguo","Lo que sea más fácil para el terapeuta","El riesgo y lo que bloquea el tratamiento"],"correcta":2},{"p":"¿Cuál es lenguaje centrado en la persona?","ops":["Un niño hiperactivo problemático","Un niño con diagnóstico de TDAH","Un TDAH"],"correcta":1}]}},{"id":"d-evaluacion-clinica-m4","titulo":"Módulo 4 — Formulación de casos","resumen":"El modelo de las 5 P (problema presentado, predisponentes, precipitantes, perpetuantes y protectores); una formulación integrativa con aportes cognitivo-conductuales, contextuales, sistémicos y psicodinámicos; cómo plantear hipótesis y contrastarlas con datos; y cómo armar el mapa del caso. Cuatro lecciones y una evaluación.","lecciones":[{"id":"d-evaluacion-clinica-m4-l1","titulo":"Lección 1 — El modelo de las 5 P","objetivo":"organizar la información de un caso con el modelo de las 5 P para explicar por qué esta persona tiene este problema ahora.","bloques":[{"tipo":"texto","texto":"Si el diagnóstico responde «¿qué tiene?», la <b>formulación</b> responde «¿por qué a esta persona, por qué ahora y qué lo mantiene?». Es una <b>hipótesis explicativa</b> que conecta la historia del paciente con su problema actual y guía el tratamiento. El modelo de las <b>5 P</b> es una forma sencilla y muy usada de organizarla."},{"tipo":"tabla","titulo":"Las 5 P","encabezados":["P","Pregunta que responde","Ejemplo (caso ficticio de Sofía, 27 años)"],"filas":[["<b>Problema presentado</b>","¿Qué le pasa hoy y cómo afecta su vida?","Ataques de pánico 3 veces por semana; dejó de usar el Metro y llega tarde al trabajo"],["<b>Predisponentes</b>","¿Qué la hizo más vulnerable desde antes?","Madre muy ansiosa que evitaba salir; tendencia a notar sus sensaciones corporales"],["<b>Precipitantes</b>","¿Qué lo detonó ahora?","Primera crisis en un vagón detenido, en una semana de mucho estrés laboral"],["<b>Perpetuantes</b>","¿Qué lo mantiene?","Evita el Metro, lleva siempre agua y un ansiolítico «por si acaso», interpreta las palpitaciones como infarto"],["<b>Protectores</b>","¿Qué recursos tiene?","Buena red de amigas, le gusta correr, está motivada, trabajo estable"]],"nota":"Los <b>perpetuantes</b> son los más importantes para el tratamiento: son lo que sí se puede cambiar hoy."},{"tipo":"relacionar","rotulo":"Clasifica cada dato de Sofía","pares":[["Su mamá evitaba salir sola por miedo","Predisponente"],["La primera crisis ocurrió en un vagón detenido","Precipitante"],["Ya no usa el Metro para no sentir la crisis","Perpetuante"],["Corre tres veces por semana y lo disfruta","Protector"],["Llega tarde al trabajo porque hace rodeos","Problema presentado"]]},{"tipo":"comparar","titulo":"Formulación o resumen","malTitulo":"Resumen de datos","mal":"«Sofía tiene 27 años, trabaja en una oficina, tiene ataques de pánico, su mamá es ansiosa, le gusta correr.» (Datos sueltos sin conexión.)","bienTitulo":"Formulación","bien":"«Sofía, con una sensibilidad previa a las sensaciones corporales aprendida en casa, tuvo una primera crisis en un momento de estrés; desde entonces interpreta las palpitaciones como peligro y evita el Metro, lo que le impide comprobar que no le pasa nada y mantiene el miedo. Su motivación y su red de amigas son recursos para el tratamiento.»"},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Los factores perpetuantes son importantes porque…","ops":["Explican el origen remoto del problema","Son los que más le gustan al paciente","Son lo que mantiene el problema y se puede cambiar hoy"],"correcta":2,"explica":"Muchas intervenciones con evidencia actúan justamente sobre lo que mantiene el problema."},{"p":"La diferencia entre formulación y resumen es que la formulación…","ops":["Incluye el código diagnóstico","Conecta los datos en una explicación","Tiene más páginas"],"correcta":1}]},{"tipo":"clave","items":["La formulación explica por qué esta persona, por qué ahora y qué lo mantiene.","5 P: problema presentado, predisponentes, precipitantes, perpetuantes y protectores.","Los perpetuantes guían el tratamiento; los protectores son recursos para lograrlo."]}]},{"id":"d-evaluacion-clinica-m4-l2","titulo":"Lección 2 — Formulación integrativa: cuatro miradas","objetivo":"enriquecer una formulación con aportes cognitivo-conductuales, contextuales, sistémicos y psicodinámicos sin perder coherencia.","bloques":[{"tipo":"texto","texto":"Cada enfoque ilumina una parte distinta del caso. Una <b>formulación integrativa</b> no mezcla todo sin orden: usa la <b>5 P</b> como esqueleto y toma de cada enfoque las preguntas que ayudan a entender a este paciente. El tratamiento, en cambio, debe elegirse según la <b>evidencia</b> disponible para el problema."},{"tipo":"tabla","titulo":"Qué aporta cada enfoque (en términos generales)","encabezados":["Enfoque","Preguntas que ayuda a hacer","En el caso de Sofía"],"filas":[["Cognitivo-conductual","¿Qué piensa en el momento? ¿Qué hace y qué consecuencias tiene?","«Me va a dar un infarto» → evita → alivio inmediato → el miedo se mantiene"],["Contextual (por ejemplo, ACT y análisis funcional)","¿Para qué le sirve la conducta? ¿Qué valores deja de lado por evitar?","La evitación le quita malestar, pero la aleja de su trabajo y de ver a sus amigas"],["Sistémico","¿Qué papel juega el problema en la familia o la pareja? ¿Quién refuerza la evitación?","Su novio la lleva en auto a todas partes; sin querer, mantiene la evitación"],["Psicodinámico","¿Qué patrones de relación se repiten? ¿Qué experiencias tempranas se reactivan?","Aprendió que el mundo es peligroso y que necesita a alguien que la proteja"]],"nota":"No necesitas dominar los cuatro enfoques. Lo importante es reconocer que cada uno aporta una pregunta útil y ser claro sobre en qué te basas."},{"tipo":"tarjetas","rotulo":"Preguntas clave por enfoque","tarjetas":[{"frente":"Cognitivo-conductual","reverso":"¿Qué pasa antes, qué piensa, qué siente, qué hace y qué pasa después?"},{"frente":"Contextual","reverso":"¿Qué evita, qué función cumple y qué le importa de verdad?"},{"frente":"Sistémico","reverso":"¿Quién más participa en el problema y cómo responde cada quien?"},{"frente":"Psicodinámico","reverso":"¿Qué patrón relacional se repite con otras personas, incluido el terapeuta?"}]},{"tipo":"destacado","texto":"<b>Cuidado con el eclecticismo sin rumbo.</b> Integrar no es aplicar «un poco de todo». La formulación puede nutrirse de varios enfoques, pero el plan de tratamiento debe ser coherente, basado en evidencia y discutido con tu supervisor."},{"tipo":"relacionar","rotulo":"¿Qué enfoque hace esta pregunta?","pares":[["¿Qué pensamiento aparece justo antes de la crisis?","Cognitivo-conductual"],["¿Qué deja de hacer que es valioso para ella?","Contextual"],["¿Cómo responde la familia cuando ella evita salir?","Sistémico"],["¿Se repite con la terapeuta el patrón de buscar protección?","Psicodinámico"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Una formulación integrativa bien hecha…","ops":["Usa un esqueleto claro y toma preguntas útiles de varios enfoques","Aplica técnicas de todos los enfoques al mismo tiempo","Evita cualquier referencia a la evidencia"],"correcta":0},{"p":"El novio de Sofía la lleva en auto para que no use el Metro. Desde lo sistémico, esto…","ops":["No tiene relación con el problema","Es la causa única del pánico","Puede mantener la evitación sin intención"],"correcta":2}]},{"tipo":"clave","items":["La formulación integrativa usa las 5 P como esqueleto y suma preguntas de varios enfoques.","Cada enfoque ilumina algo: pensamientos y conductas, función y valores, sistema, patrones relacionales.","Integrar en la formulación no justifica un tratamiento sin rumbo: elige según la evidencia."]}]},{"id":"d-evaluacion-clinica-m4-l3","titulo":"Lección 3 — Hipótesis y cómo contrastarlas","objetivo":"formular hipótesis clínicas que se puedan poner a prueba y contrastarlas con registros y datos del propio paciente.","bloques":[{"tipo":"texto","texto":"Una formulación es una <b>hipótesis</b>, no una verdad. Una buena hipótesis clínica es <b>específica</b> y se puede <b>poner a prueba</b>: «la ansiedad de Diego sube en los días en que duerme menos de 6 horas» se puede comprobar; «Diego tiene un conflicto interno» no. Los datos que la contradicen son tan valiosos como los que la confirman."},{"tipo":"comparar","titulo":"Hipótesis clínicas","malTitulo":"Difícil de contrastar","mal":"«El problema de Diego es su baja autoestima.» «Tiene mucha energía negativa.»","bienTitulo":"Contrastable","bien":"«Diego se siente más ansioso los días que duerme poco.» «Las discusiones con su jefe preceden a sus episodios de atracón.»"},{"tipo":"pasos","rotulo":"Cómo contrastar una hipótesis","pasos":["Escríbela de forma específica: qué, cuándo, en qué situación.","Define qué dato la apoyaría y qué dato la contradiría.","Recoge información: autorregistro, cuestionarios, observación, informe de terceros con consentimiento.","Compara los datos con la hipótesis y con al menos una hipótesis alternativa.","Ajusta la formulación y compártela con el paciente para que la valide o la corrija."]},{"tipo":"excel","rotulo":"Autorregistro de Diego: ¿trabajo o sueño? (caso ficticio)","datos":[["Día","Contexto","Horas de sueño","Ansiedad (0-10)","","Indicador","Valor"],["Lunes","Trabajo",5,8,"","Ansiedad promedio en trabajo",""],["Martes","Trabajo",7,4,"","Ansiedad promedio en casa",""],["Miércoles","Trabajo",5,7,"","Ansiedad con menos de 6 h de sueño",""],["Jueves","Trabajo",6,5,"","Ansiedad con 6 h o más de sueño",""],["Viernes","Trabajo",4,9,"","Conclusión preliminar",""],["Sábado","Casa",7,3],["Domingo","Casa",5,6]],"retos":[{"celda":"G2","formula":"=PROMEDIO.SI(B2:B8,\"Trabajo\",D2:D8)","esperado":6.6,"requiere":"PROMEDIO.SI(","texto":"<b>G2</b>: calcula la ansiedad promedio de los días de trabajo con PROMEDIO.SI.","pista":"=PROMEDIO.SI(rango del criterio, \"Trabajo\", rango a promediar)"},{"celda":"G3","formula":"=PROMEDIO.SI(B2:B8,\"Casa\",D2:D8)","esperado":4.5,"requiere":"PROMEDIO.SI(","texto":"<b>G3</b>: ahora la ansiedad promedio de los días en casa."},{"celda":"G4","formula":"=PROMEDIO.SI(C2:C8,\"<6\",D2:D8)","esperado":7.5,"requiere":"PROMEDIO.SI(","texto":"<b>G4</b>: promedio de ansiedad los días con menos de 6 horas de sueño.","pista":"El criterio va entre comillas: \"<6\"."},{"celda":"G5","formula":"=PROMEDIO.SI(C2:C8,\">=6\",D2:D8)","esperado":4,"requiere":"PROMEDIO.SI(","texto":"<b>G5</b>: promedio de ansiedad los días con 6 horas o más."},{"celda":"G6","formula":"=SI(G4-G5>G2-G3,\"Pesa más el sueño\",\"Pesa más el contexto\")","esperado":"Pesa más el sueño","requiere":"SI(","texto":"<b>G6</b>: si la diferencia por sueño (G4−G5) es mayor que la diferencia por contexto (G2−G3), escribe «Pesa más el sueño»; si no, «Pesa más el contexto».","explica":"La diferencia por sueño (3.5 puntos) es mayor que la del contexto (2.1). Es un dato preliminar: una semana es poco, y el domingo en casa con poco sueño también tuvo ansiedad alta. Se sigue registrando y se revisa la hipótesis con Diego."}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"¿Cuál hipótesis se puede contrastar?","ops":["Su energía está desequilibrada","Sus atracones ocurren después de discutir con su jefe","Tiene un bloqueo emocional"],"correcta":1},{"p":"Un dato que contradice tu hipótesis…","ops":["Es valioso porque te obliga a revisarla","Debe ignorarse","Demuestra que el paciente miente"],"correcta":0,"explica":"La formulación mejora cuando la pones a prueba."}]},{"tipo":"clave","items":["Una hipótesis clínica útil es específica y contrastable.","Define antes qué datos la apoyarían y cuáles la contradirían, y compárala con una alternativa.","El autorregistro del paciente es una fuente de datos poderosa; revisa las conclusiones con él."]}]},{"id":"d-evaluacion-clinica-m4-l4","titulo":"Lección 4 — El mapa del caso","objetivo":"redactar el mapa del caso en una página que conecte las 5 P, las hipótesis y las implicaciones para el tratamiento.","bloques":[{"tipo":"texto","texto":"El <b>mapa del caso</b> reúne en una página todo lo que sabes y lo que supones. Te sirve para presentar el caso en supervisión, para explicárselo al paciente con palabras sencillas y para decidir el plan. Se actualiza conforme avanzas."},{"tipo":"plantilla","rotulo":"Plantilla del mapa del caso","texto":"Datos básicos (sin nombre real): edad, ocupación, con quién vive, quién refiere.\nProblema presentado: qué le pasa, desde cuándo, con qué frecuencia e impacto.\nDiagnóstico (provisional o definitivo) y comorbilidad.\nPredisponentes: biológicos, psicológicos y sociales.\nPrecipitantes: qué lo detonó ahora.\nPerpetuantes: pensamientos, conductas, relaciones y contexto que lo mantienen.\nProtectores: recursos personales, familiares y sociales.\nRiesgo: nivel estimado y plan de seguridad si aplica.\nHipótesis principal y alternativa, y cómo se van a contrastar.\nImplicaciones para el tratamiento: qué perpetuantes atender primero y con qué intervención basada en evidencia.\nPreguntas pendientes para la siguiente sesión o para supervisión."},{"tipo":"destacado","texto":"<b>Caso ficticio para practicar.</b> Julián, 41 años, chofer de reparto en Guadalajara. Lo refiere su médico porque tiene insomnio y «nervios» desde hace 5 meses, cuando lo asaltaron a mano armada en su ruta. Desde entonces tiene pesadillas con el asalto, se sobresalta con el ruido de motos, evita la colonia donde ocurrió y toma cerveza por las noches «para poder dormir». Su padre tomaba mucho. Su esposa lo apoya y sus hijos lo motivan a seguir trabajando. PHQ-9 de 11; reactivo 9 en 0."},{"tipo":"ordenar","rotulo":"Ordena la secuencia del mapa del caso","items":[{"frase":"problema presentado predisponentes precipitantes perpetuantes protectores implicaciones","es":"Del qué pasa al por qué pasa y, al final, qué hacer."}]},{"tipo":"relacionar","rotulo":"Ubica los datos de Julián","pares":[["El asalto a mano armada hace 5 meses","Precipitante"],["Evita la colonia y toma cerveza para dormir","Perpetuante"],["Su esposa lo apoya y sus hijos lo motivan","Protector"],["Su padre tenía un consumo alto de alcohol","Predisponente"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"En el caso de Julián, una implicación para el tratamiento es…","ops":["Recomendarle cambiar de trabajo de inmediato","Asumir que solo es insomnio y enviarlo a dormir más","Evaluar un posible trastorno de estrés postraumático y vigilar el consumo de alcohol"],"correcta":2,"explica":"Los síntomas tras un evento traumático y el consumo como estrategia para dormir son perpetuantes clave."},{"p":"El mapa del caso debe incluir…","ops":["Solo la historia de la infancia","Hipótesis, riesgo e implicaciones para el tratamiento","Solo el diagnóstico"],"correcta":1}]},{"tipo":"reflexion","rotulo":"Tu mapa de práctica","pregunta":"Con los datos de Julián, escribe en tres renglones su formulación: por qué a él, por qué ahora y qué lo mantiene. ¿Qué dato te falta y cómo lo obtendrías?","ayuda":"Julián, con… vivió… y desde entonces… lo que mantiene… Me falta saber… y lo preguntaría así…"},{"tipo":"clave","items":["El mapa del caso cabe en una página y conecta 5 P, riesgo, hipótesis e implicaciones.","Sirve para supervisión, para devolverle al paciente su formulación y para planear.","Se actualiza con los datos nuevos: es un documento vivo."]}]}],"quiz":{"titulo":"Evaluación del módulo 4","preguntas":[{"p":"La formulación de caso responde principalmente…","ops":["Qué código diagnóstico le corresponde","Cuánto debe cobrarse por sesión","Por qué esta persona tiene este problema ahora y qué lo mantiene"],"correcta":2},{"p":"Un evento que detona el problema actual es un factor…","ops":["Predisponente","Precipitante","Protector"],"correcta":1},{"p":"Evitar los lugares donde apareció la crisis suele ser un factor…","ops":["Perpetuante","Protector","Precipitante"],"correcta":0},{"p":"Una red de apoyo sólida es un factor…","ops":["Perpetuante","Precipitante","Protector"],"correcta":2},{"p":"Una formulación integrativa bien hecha…","ops":["Descarta la evidencia","Toma preguntas útiles de varios enfoques con un esqueleto claro","Aplica técnicas de todos los enfoques sin orden"],"correcta":1},{"p":"¿Cuál es una hipótesis clínica contrastable?","ops":["Su ansiedad aumenta los días en que duerme menos de 6 horas","Tiene un conflicto interno profundo","Su energía está bloqueada"],"correcta":0},{"p":"Si los datos contradicen tu hipótesis, lo indicado es…","ops":["Ignorar esos datos","Cambiar de paciente","Revisar y ajustar la formulación"],"correcta":2},{"p":"El mapa del caso sirve para…","ops":["Publicar el caso en redes con fines educativos","Supervisión, devolución al paciente y planeación del tratamiento","Sustituir el consentimiento informado"],"correcta":1}]}},{"id":"d-evaluacion-clinica-m5","titulo":"Módulo 5 — Plan de tratamiento y documentación","resumen":"Objetivos SMART e intervenciones basadas en evidencia según el problema; medición de resultados sesión a sesión en hoja de cálculo; notas clínicas SOAP y DAP, expediente clínico y protección de datos personales sensibles; informe psicológico y un caso integrador ficticio de principio a fin. Cuatro lecciones y una evaluación.","lecciones":[{"id":"d-evaluacion-clinica-m5-l1","titulo":"Lección 1 — Objetivos SMART e intervenciones basadas en evidencia","objetivo":"redactar objetivos terapéuticos SMART a partir de la formulación y elegir intervenciones con respaldo científico según el problema.","bloques":[{"tipo":"texto","texto":"El plan de tratamiento traduce la formulación en acción: <b>qué</b> queremos cambiar, <b>cómo</b> y <b>cómo sabremos</b> que funcionó. Los objetivos se acuerdan con el paciente (así se fortalece la alianza) y se redactan en formato <b>SMART</b>: específicos, medibles, alcanzables, relevantes y con tiempo definido."},{"tipo":"comparar","titulo":"Redactar objetivos","malTitulo":"Vago","mal":"«Que Sofía esté mejor.» «Reducir la ansiedad.» «Que mejore su autoestima.»","bienTitulo":"SMART","bien":"«En 12 semanas, Sofía viajará en Metro sola de su casa al trabajo al menos 3 días por semana, con ansiedad de 4/10 o menos.» «En 10 semanas, el PHQ-9 de Julián bajará de 11 a menos de 5.»"},{"tipo":"tabla","titulo":"Intervenciones con evidencia según el problema (panorama general)","encabezados":["Problema","Intervenciones psicológicas recomendadas por guías como NICE y APA"],"filas":[["Depresión leve a moderada","Activación conductual, terapia cognitivo-conductual (TCC), autoayuda guiada, terapia interpersonal"],["Depresión moderada a grave","TCC o activación conductual, a menudo combinadas con medicación indicada por psiquiatría"],["Trastorno de pánico","TCC con psicoeducación y exposición a sensaciones y situaciones"],["Ansiedad generalizada","TCC, autoayuda guiada basada en TCC, relajación aplicada"],["Estrés postraumático","TCC centrada en el trauma, terapia de procesamiento cognitivo, EMDR"],["Trastorno obsesivo-compulsivo","TCC con exposición y prevención de respuesta"],["Insomnio","TCC para el insomnio (TCC-I)"]],"nota":"Consulta la guía vigente para cada problema y aplica solo las intervenciones para las que tienes formación y supervisión."},{"tipo":"completar","rotulo":"Completa el objetivo SMART","items":[{"frase":"«En 8 ___, Luis asistirá a sus clases al menos 4 días por semana.» (tiempo definido)","resp":["semanas"]},{"frase":"Un objetivo SMART debe ser ___: que se pueda verificar con un número o una conducta observable.","resp":["medible"]}]},{"tipo":"relacionar","rotulo":"Relaciona el problema con una intervención de primera línea","pares":[["Trastorno obsesivo-compulsivo","Exposición y prevención de respuesta"],["Insomnio crónico","TCC para el insomnio"],["Estrés postraumático","TCC centrada en el trauma"],["Depresión leve","Activación conductual"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"¿Cuál objetivo es SMART?","ops":["En 10 semanas, dormir al menos 6 horas 5 noches por semana según su registro","Dormir mejor","Tener más energía y ser feliz"],"correcta":0},{"p":"Los objetivos del tratamiento se definen…","ops":["Solo por el terapeuta","Copiando los criterios del DSM","En acuerdo con el paciente, a partir de la formulación"],"correcta":2}]},{"tipo":"clave","items":["Objetivos SMART: específicos, medibles, alcanzables, relevantes y con tiempo.","Elige intervenciones con evidencia para el problema (NICE, APA) y dentro de tu formación.","El plan sale de la formulación: ataca primero los perpetuantes clave."]}]},{"id":"d-evaluacion-clinica-m5-l2","titulo":"Lección 2 — Medir resultados sesión a sesión","objetivo":"registrar y analizar puntajes sesión a sesión para saber si el tratamiento funciona y cuándo ajustarlo.","bloques":[{"tipo":"texto","texto":"La percepción del terapeuta sobre el progreso de un paciente no siempre es precisa: hay pacientes que empeoran sin que el terapeuta lo note. <b>Medir sesión a sesión</b> con un instrumento breve (como el PHQ-9, el GAD-7 o una escala de objetivo personal) permite detectar a tiempo si el tratamiento no avanza y ajustar. A esto se le llama <b>monitoreo rutinario de resultados</b>."},{"tipo":"lista","items":["<b>Respuesta:</b> reducción de 50% o más respecto al puntaje inicial.","<b>Remisión</b> (en el PHQ-9): puntaje menor que 5.","<b>Estancamiento:</b> sin cambio importante durante varias sesiones: revisa formulación, alianza y plan, y llévalo a supervisión.","<b>Empeoramiento:</b> reevalúa riesgo de inmediato."]},{"tipo":"excel","rotulo":"Seguimiento de Julián con PHQ-9 (caso ficticio)","datos":[["Sesión","PHQ-9","","Indicador","Valor"],[1,18,"","Puntaje inicial",""],[2,17,"","Puntaje actual",""],[3,15,"","Reducción (%)",""],[4,14,"","¿Respuesta?",""],[5,12,"","¿Remisión?",""],[6,10,"","Puntaje más bajo",""],[7,9],[8,8]],"retos":[{"celda":"E2","formula":"=B2","esperado":18,"texto":"<b>E2</b>: trae el puntaje de la primera sesión."},{"celda":"E3","formula":"=B9","esperado":8,"texto":"<b>E3</b>: trae el puntaje de la sesión más reciente (sesión 8)."},{"celda":"E4","formula":"=REDONDEAR((E2-E3)/E2*100,1)","esperado":55.6,"requiere":"REDONDEAR(","texto":"<b>E4</b>: calcula el porcentaje de reducción: (inicial − actual) / inicial × 100, redondeado a un decimal."},{"celda":"E5","formula":"=SI(E4>=50,\"Sí\",\"No\")","esperado":"Sí","requiere":"SI(","texto":"<b>E5</b>: si la reducción es de 50% o más, escribe «Sí»; si no, «No»."},{"celda":"E6","formula":"=SI(E3<5,\"Sí\",\"No\")","esperado":"No","requiere":"SI(","texto":"<b>E6</b>: si el puntaje actual es menor que 5, hay remisión: «Sí»; si no, «No»."},{"celda":"E7","formula":"=MIN(B2:B9)","esperado":8,"requiere":"MIN(","texto":"<b>E7</b>: encuentra el puntaje más bajo del tratamiento.","explica":"Julián respondió al tratamiento (bajó 55.6%), pero aún no está en remisión. Es buen momento para revisar con él los objetivos pendientes antes de hablar de cierre."}]},{"tipo":"destacado","texto":"<b>Muestra la gráfica al paciente.</b> Revisar juntos los puntajes refuerza la alianza, hace visible el avance y abre la conversación cuando algo no funciona. El instrumento complementa la entrevista: si el puntaje baja pero el paciente dice sentirse peor, pregunta."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Un paciente pasa de un PHQ-9 de 20 a 9. ¿Hay respuesta?","ops":["No se puede saber","Sí, bajó más de 50%","No, porque no llegó a 0"],"correcta":1,"explica":"(20 − 9) / 20 = 55%."},{"p":"Si el puntaje no mejora durante varias sesiones, conviene…","ops":["Revisar formulación, alianza y plan, y llevarlo a supervisión","Seguir igual sin cambios","Dejar de medir para no desanimarse"],"correcta":0}]},{"tipo":"clave","items":["Medir sesión a sesión detecta a tiempo el estancamiento o el empeoramiento.","Respuesta: reducción de 50% o más; remisión en el PHQ-9: menos de 5.","Comparte los resultados con el paciente y úsalos para ajustar el plan."]}]},{"id":"d-evaluacion-clinica-m5-l3","titulo":"Lección 3 — Notas clínicas, expediente y datos personales","objetivo":"redactar notas de sesión en formato SOAP o DAP e integrar un expediente que cumpla las normas de expediente clínico y de protección de datos.","bloques":[{"tipo":"texto","texto":"Cada sesión se documenta con una <b>nota de evolución</b>. Dos formatos muy usados son <b>SOAP</b> (Subjetivo, Objetivo, Análisis, Plan) y <b>DAP</b> (Datos, Análisis, Plan). Lo importante es que la nota sea breve, objetiva, útil para otro profesional y respetuosa, porque el paciente puede solicitar información de su expediente."},{"tipo":"plantilla","rotulo":"Nota SOAP (caso ficticio)","texto":"Fecha y hora: 14/10, 17:00. Sesión 5.\nS (Subjetivo): Julián refiere que durmió mejor esta semana; tuvo 2 pesadillas (antes 5). Tomó cerveza una noche. «Me sentí más tranquilo manejando».\nO (Objetivo): puntual, aliño adecuado, afecto menos ansioso que en sesiones previas. PHQ-9: 12 (sesión 1: 18). Niega ideas de muerte.\nA (Análisis): progreso en sueño y consumo; la evitación de la colonia del asalto se mantiene como perpetuante principal.\nP (Plan): continuar TCC centrada en el trauma; tarea: registro de pesadillas y consumo; siguiente sesión, iniciar jerarquía de exposición.\nNombre completo, cédula profesional y firma de quien elabora."},{"tipo":"tabla","titulo":"El expediente clínico en México","encabezados":["Punto","Qué considerar"],"filas":[["NOM-004-SSA3-2012, del expediente clínico","Es obligatoria para el personal del área de la salud y los establecimientos de atención médica públicos, sociales y privados, incluidos los consultorios. No menciona la psicología por separado, pero instituciones y colegios la usan como referencia para el expediente psicológico: verifica con tu institución o asesoría legal cómo aplica en tu caso"],["Conservación","Mínimo 5 años contados a partir de la fecha del último acto registrado"],["Contenido","Historia clínica, notas de evolución, consentimientos, resultados de instrumentos, referencias e informes"],["Cada nota","Fecha, hora, nombre completo de quien la elabora y firma (autógrafa, electrónica o digital)"],["Expediente electrónico","Si usas un sistema electrónico, revisa también la NOM-024-SSA3-2012 sobre sistemas de información de registro electrónico para la salud"],["Confidencialidad","Acceso restringido; se entrega información solo al paciente, a quien él autorice o por requerimiento de autoridad competente"]]},{"tipo":"destacado","texto":"<b>Datos personales sensibles.</b> La información de salud, incluida la psicológica, es un <b>dato personal sensible</b>. En el sector privado aplica la <b>Ley Federal de Protección de Datos Personales en Posesión de los Particulares</b> (nueva ley publicada en el DOF el 20 de marzo de 2025); la autoridad que la vigila ya no es el INAI sino la Secretaría Anticorrupción y Buen Gobierno. Necesitas <b>aviso de privacidad</b>, <b>consentimiento expreso</b> para tratar datos sensibles (lo más seguro es por escrito) y atender los <b>derechos ARCO</b> (acceso, rectificación, cancelación y oposición). En instituciones públicas aplica la ley general para sujetos obligados. Verifica los detalles en el texto vigente."},{"tipo":"lista","items":["No envíes expedientes ni notas por WhatsApp o correo personal sin protección.","Usa contraseñas, cifrado y respaldos; guarda el papel bajo llave.","En supervisión o en clase, quita los datos que identifican al paciente.","Evita en las notas detalles íntimos que no aportan al tratamiento."]},{"tipo":"completar","rotulo":"Completa","items":[{"frase":"En el formato SOAP, la «A» corresponde al ___.","resp":["análisis","Análisis"]},{"frase":"La NOM-004-SSA3-2012 pide conservar el expediente al menos ___ años desde el último acto registrado.","resp":["5","cinco"]},{"frase":"La información de salud mental es un dato personal ___.","resp":["sensible"]}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"¿Qué va en la «O» de una nota SOAP?","ops":["Lo que el paciente dice que siente","El plan para la siguiente sesión","Lo observado y los resultados de instrumentos"],"correcta":2},{"p":"Un colega te pide por WhatsApp la nota completa de un paciente para «darle una opinión». Lo correcto es…","ops":["Reenviarle los audios de la sesión","Consultar el caso sin datos identificables y por un medio seguro","Mandarle la foto del expediente"],"correcta":1}]},{"tipo":"clave","items":["SOAP (Subjetivo, Objetivo, Análisis, Plan) y DAP son formatos breves y objetivos para las notas.","NOM-004-SSA3-2012: referencia para el expediente; conservación mínima de 5 años; cada nota con fecha, hora, nombre y firma.","La salud mental es dato sensible: aviso de privacidad, consentimiento expreso, derechos ARCO y resguardo seguro."]}]},{"id":"d-evaluacion-clinica-m5-l4","titulo":"Lección 4 — Informe psicológico y caso integrador","objetivo":"redactar un informe psicológico claro y responsable, e integrar todo el proceso de evaluación en un caso ficticio completo.","bloques":[{"tipo":"texto","texto":"El <b>informe psicológico</b> comunica los resultados de una evaluación a alguien más: el paciente, un médico, una escuela o una autoridad. Antes de escribirlo pregunta: <b>¿para quién es y para qué lo necesita?</b> Incluye solo lo necesario para ese propósito, en lenguaje comprensible y con conclusiones que se sostengan en los datos."},{"tipo":"tabla","titulo":"Estructura del informe psicológico","encabezados":["Apartado","Contenido"],"filas":[["Datos de identificación","Del evaluado, del evaluador (nombre y cédula), fechas y destinatario"],["Motivo de la evaluación","Quién la solicita y qué pregunta debe responder"],["Procedimientos","Entrevistas, observación e instrumentos utilizados (nombre y versión)"],["Resultados","Datos relevantes de cada fuente, sin copiar puntajes sin interpretación"],["Integración y conclusiones","Respuesta a la pregunta de evaluación; diagnóstico si aplica; formulación breve"],["Recomendaciones","Concretas y realistas: tratamiento, derivaciones, ajustes escolares o laborales"],["Alcances y límites","Fecha de validez de las conclusiones y advertencia de que no debe usarse con otro fin"]]},{"tipo":"destacado","texto":"<b>Caso integrador (ficticio).</b> Mariela, 23 años, estudiante de enfermería en Puebla, llega por «estrés» antes de su servicio social.<br>• <b>Primera consulta:</b> encuadre, consentimiento y límites de la confidencialidad. Motivo clínico: preocupación difícil de controlar, tensión muscular e insomnio de 7 meses; bajó su promedio.<br>• <b>Evaluación:</b> EEM con afecto ansioso, pensamiento coherente centrado en «voy a fallar». Tamizaje: GAD-7 de 14, PHQ-9 de 9 con reactivo 9 en 0; niega consumo y violencia. Se descarta con su médica un problema de tiroides.<br>• <b>Diagnóstico provisional:</b> trastorno de ansiedad generalizada, con síntomas depresivos leves.<br>• <b>Formulación (5 P):</b> predisponente, madre muy exigente; precipitante, reprobar una materia; perpetuantes, revisar apuntes hasta la madrugada y pedir confirmación constante a sus compañeras; protectores, vocación clara y una amiga cercana.<br>• <b>Plan:</b> TCC para ansiedad generalizada, 12 sesiones. Objetivo SMART: en 12 semanas, GAD-7 menor que 5 y dormir 7 horas al menos 5 noches por semana. GAD-7 en cada sesión.<br>• <b>Documentación:</b> nota SOAP de cada sesión, expediente resguardado y aviso de privacidad firmado."},{"tipo":"plantilla","rotulo":"Fragmento de conclusiones del informe (caso ficticio)","texto":"Conclusiones: Con base en tres entrevistas clínicas, la observación y los cuestionarios GAD-7 y PHQ-9, Mariela presenta un patrón de preocupación excesiva y difícil de controlar, acompañado de tensión muscular e insomnio, de siete meses de evolución, que afecta su desempeño académico. Estos datos son compatibles con un trastorno de ansiedad generalizada (diagnóstico provisional). No se identifica riesgo suicida al momento de la evaluación.\nRecomendaciones: 1) Terapia cognitivo-conductual de 12 sesiones con medición semanal. 2) Mantener seguimiento médico. 3) Revaluar al término del tratamiento.\nEste informe se elaboró a solicitud de la interesada, para uso personal. Las conclusiones corresponden a la fecha de la evaluación.\nNombre, cédula profesional y firma."},{"tipo":"ordenar","rotulo":"Ordena el proceso completo","items":[{"frase":"encuadre entrevista tamizaje diagnóstico formulación plan medición documentación","es":"Este es el recorrido que viviste a lo largo del diplomado."}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Antes de redactar un informe, la primera pregunta es…","ops":["¿Para quién es y para qué lo necesita?","¿Cuántas pruebas puedo incluir?","¿Qué diagnóstico suena más completo?"],"correcta":0,"explica":"El destinatario y el propósito definen qué incluir y qué dejar fuera."},{"p":"En el caso de Mariela, un factor perpetuante es…","ops":["Tener una amiga cercana","Haber reprobado una materia","Revisar apuntes hasta la madrugada y pedir confirmación constante"],"correcta":2},{"p":"¿Qué NO debe hacer un informe?","ops":["Señalar sus límites y fecha","Incluir detalles íntimos que no responden a la pregunta de evaluación","Indicar los instrumentos utilizados"],"correcta":1}]},{"tipo":"reflexion","rotulo":"Tu siguiente paso","pregunta":"Piensa en el próximo paciente que atenderás (o en tus prácticas). ¿Qué parte del proceso aplicarás desde la primera sesión y qué llevarás a supervisión?","ayuda":"Desde la primera sesión voy a… Llevaré a supervisión…"},{"tipo":"clave","items":["El informe responde a una pregunta concreta para un destinatario concreto, con lenguaje claro y límites explícitos.","El proceso completo: encuadre, entrevista, tamizaje, diagnóstico, formulación, plan, medición y documentación.","Todo el camino se recorre con ética, evidencia y supervisión."]}]}],"quiz":{"titulo":"Evaluación del módulo 5","preguntas":[{"p":"¿Cuál es un objetivo SMART?","ops":["Superar la ansiedad","Ser más positiva","En 12 semanas, viajar sola en Metro 3 días por semana con ansiedad de 4/10 o menos"],"correcta":2},{"p":"Una intervención de primera línea para el trastorno obsesivo-compulsivo es…","ops":["Hipnosis regresiva","TCC con exposición y prevención de respuesta","Reiki"],"correcta":1},{"p":"Un paciente pasa de un PHQ-9 de 16 a 7. Esto indica…","ops":["Respuesta, pero todavía no remisión","Remisión completa","Que el tratamiento no funciona"],"correcta":0},{"p":"En una nota SOAP, la «S» corresponde a…","ops":["Los resultados de los instrumentos","Las tareas de la siguiente sesión","Lo que el paciente refiere"],"correcta":2},{"p":"Según la NOM-004-SSA3-2012, el expediente se conserva al menos…","ops":["Hasta que el paciente lo pida","5 años desde el último acto registrado","1 año desde la primera consulta"],"correcta":1},{"p":"La información de salud mental se considera…","ops":["Un dato personal sensible","Información pública","Un dato sin protección especial"],"correcta":0},{"p":"Un informe psicológico debe incluir…","ops":["Todos los detalles íntimos de la vida del paciente","Solo los puntajes brutos sin interpretación","Procedimientos, resultados, conclusiones, recomendaciones y límites"],"correcta":2},{"p":"Si el puntaje de un paciente empeora de forma notable, lo primero es…","ops":["Dejar de aplicar el instrumento","Revaluar el riesgo","Esperar a la siguiente sesión"],"correcta":1}]}}]});
window.CURSOS_MARA.push({"id":"c-ia-psicologos","nombre":"IA para Psicólogos y Consultorios de Salud Mental","color":"#8B5CF6","nivel":"Cursos libres de capacitación","familia":"IA por profesión","periodoTipo":null,"periodoNum":null,"desc":"Para psicólogos, psicoterapeutas, tanatólogos, orientadores y consultorios pequeños: usa asistentes de IA para notas, informes, agenda, materiales de psicoeducación y actualización profesional, quitándole horas al papeleo sin poner en riesgo la confidencialidad ni la calidad clínica. La IA no diagnostica ni sustituye tu juicio clínico.","horas":10,"precio":790,"publicado":true,"proximamente":false,"modulos":[{"id":"c-ia-psicologos-m1","titulo":"Módulo 1 — IA con ética clínica","resumen":"Qué hace bien y qué hace mal un asistente de IA, por qué los datos de tus pacientes nunca deben llegar a él, cómo anonimizar un caso paso a paso y qué dicen la ley y la ética profesional. Tres lecciones y una evaluación.","lecciones":[{"id":"c-ia-psicologos-m1-l1","titulo":"Lección 1 — Qué hace bien (y mal) un asistente de IA","objetivo":"distinguir las tareas de consultorio en las que un asistente de IA ahorra tiempo de aquellas en las que puede dañar a un paciente.","bloques":[{"tipo":"destacado","texto":"<b>Antes de empezar.</b> Este es un curso libre de capacitación con constancia de Instituto Mara; no tiene validez oficial ante la SEP ni es una certificación de CONOCER. Es para profesionales que <b>ya</b> ejercen o estudian psicología, psicoterapia, tanatología u orientación. No te habilita para diagnosticar ni para dar psicoterapia: en México, ejercer como psicólogo o psicoterapeuta requiere formación profesional y cédula. Tampoco sustituye la asesoría legal sobre protección de datos."},{"tipo":"texto","texto":"Un asistente de IA (ChatGPT, Claude, Gemini, Copilot…) es un modelo de lenguaje: predice qué texto es probable que siga a tus instrucciones. Por eso escribe con fluidez, resume, ordena y cambia de tono muy bien. Pero <b>no sabe</b> si lo que dice es verdad, <b>no conoce</b> a tu paciente y <b>no tiene</b> responsabilidad profesional. Tú sí."},{"tipo":"tabla","titulo":"Dónde ayuda y dónde no","encabezados":["Sí le puedes pedir (con revisión)","No le pidas"],"filas":[["Convertir tus apuntes ya anonimizados en una nota ordenada","Que decida un diagnóstico o una hipótesis clínica por ti"],["Redactar recordatorios, políticas de cancelación y mensajes","Que evalúe riesgo suicida o de violencia de un paciente real"],["Explicar un concepto en lenguaje sencillo para una hoja de psicoeducación","Que recomiende medicamentos o dosis"],["Resumir un artículo largo para tu estudio","Que te dé referencias bibliográficas sin que las verifiques"],["Proponer un borrador de informe con tu estructura","Que firme, envíe o decida algo en tu nombre"]]},{"tipo":"tarjetas","rotulo":"Tres fallas que debes conocer","tarjetas":[{"frente":"Alucinación","reverso":"La IA inventa datos con total seguridad: un estudio que no existe, una cifra, una cita textual o un criterio diagnóstico mal copiado."},{"frente":"Sesgo","reverso":"Repite estereotipos de sus datos de entrenamiento: por género, edad, clase social, orientación sexual o cultura. Puede patologizar lo que en un contexto mexicano es normal."},{"frente":"Complacencia","reverso":"Tiende a darte la razón. Si le preguntas «¿verdad que esto es ansiedad?», es fácil que te diga que sí aunque falten datos."}]},{"tipo":"practica","rotulo":"¿Tarea segura o de riesgo?","preguntas":[{"p":"Pedirle que redacte tu política de cancelaciones con un tono cálido y firme.","ops":["Segura, con tu revisión","De riesgo","Prohibida siempre"],"correcta":0,"explica":"Es texto administrativo sin datos de pacientes."},{"p":"Pegar la transcripción de una sesión con el nombre de tu paciente para que te sugiera un diagnóstico.","ops":["Segura, si la herramienta es de pago","Segura, si la borras al terminar","De riesgo: expone datos sensibles y delega el juicio clínico"],"correcta":2,"explica":"Hay dos faltas a la vez: confidencialidad y delegación del diagnóstico."},{"p":"Pedirle una explicación sencilla de la respiración diafragmática para adolescentes, que tú revisas antes de entregar.","ops":["Innecesaria","Segura, con tu revisión","De riesgo"],"correcta":1,"explica":"La revisas contra una fuente confiable y la adaptas a tu paciente."}]},{"tipo":"reflexion","rotulo":"Tu papeleo semanal","pregunta":"¿Qué tres tareas de papeleo te quitan más horas a la semana? ¿Alguna de ellas implica datos que identifiquen a tus pacientes?","ayuda":"Por ejemplo: notas de sesión (sí, datos sensibles), recordatorios de citas (datos personales mínimos), publicaciones en redes (sin datos)."},{"tipo":"clave","items":["La IA predice texto: escribe muy bien, pero no sabe si lo que dice es cierto ni conoce a tu paciente.","Alucinación, sesgo y complacencia son sus fallas típicas: revisa todo lo que produce.","Úsala para el papeleo y la redacción; el juicio clínico y la responsabilidad son tuyos."]}]},{"id":"c-ia-psicologos-m1-l2","titulo":"Lección 2 — Confidencialidad: anonimiza antes de escribir","objetivo":"anonimizar un caso clínico paso a paso para poder trabajar con un asistente de IA sin exponer a tu paciente.","bloques":[{"tipo":"texto","texto":"La regla de oro de este curso: <b>nunca pegues en un asistente de IA datos que permitan identificar a un paciente</b>. Aunque la herramienta prometa no usar tus conversaciones para entrenar, esos datos salen de tu control, pasan por servidores de terceros y quedan en un historial. En salud mental, una filtración puede costarle a tu paciente su trabajo, su familia o su tranquilidad."},{"tipo":"destacado","texto":"<b>Lo que dice la ley.</b> En México, la Ley Federal de Protección de Datos Personales en Posesión de los Particulares vigente se publicó en el DOF el 20 de marzo de 2025 y sustituyó a la de 2010. Considera <b>datos personales sensibles</b> los que pueden dar origen a discriminación o implicar un riesgo grave, entre ellos el <b>estado de salud presente o futuro</b>, la vida sexual, las creencias y el origen étnico. Con la reforma desapareció el INAI y, al momento de escribir, la autoridad en la materia es la <b>Secretaría Anticorrupción y Buen Gobierno</b>. Verifica el texto vigente en diputados.gob.mx."},{"tipo":"tabla","titulo":"Qué quitar o cambiar","encabezados":["Tipo de dato","Ejemplo","Cómo queda"],"filas":[["Identificadores directos","Nombre, CURP, teléfono, correo, dirección, foto","Se eliminan; usas una clave como «Paciente A»"],["Fechas exactas","Nació el 3 de mayo de 1991; sesión del 12 de agosto","Rango de edad («30 a 35 años») o «hace dos semanas»"],["Lugares y organizaciones","Trabaja en la farmacia de la esquina en Tlaquepaque","«Trabaja en comercio en una ciudad mediana»"],["Terceros identificables","Su esposa Lupita, su jefe el licenciado Ruiz","«Su pareja», «su jefe»"],["Detalles únicos","Fue la reina del carnaval de su pueblo en 2010","Se omiten si no son clínicamente necesarios"]]},{"tipo":"pasos","rotulo":"Anonimiza un caso en 6 pasos","pasos":["<b>Decide para qué lo necesitas.</b> Si solo quieres ordenar la nota, quizá baste con los síntomas y las intervenciones.","<b>Borra identificadores directos:</b> nombres, apellidos, apodos, teléfonos, correos, CURP, número de expediente.","<b>Generaliza</b> edad, fechas, ciudad, escuela, empresa y profesión muy específica.","<b>Cambia a los terceros</b> por su rol: «su madre», «su pareja», «su maestra».","<b>Quita detalles únicos</b> que alguien cercano podría reconocer (un accidente famoso, un cargo público, un hecho que salió en noticias).","<b>Relee como si fueras su vecino:</b> si con ese texto alguien de su entorno podría reconocerlo, sigue generalizando."]},{"tipo":"comparar","titulo":"Nota para trabajar con IA","malTitulo":"Mal anonimizada","mal":"Mariana G., 34 años, maestra de primaria en la escuela Benito Juárez de Zacatecas. Llegó el 12 de agosto porque su esposo Iván la dejó después de 10 años. Desde entonces duerme 4 horas y dice que «ya no quiere seguir así». Su hermana es enfermera en el IMSS local.","bienTitulo":"Bien anonimizada","bien":"Paciente A, mujer de 30 a 35 años, docente. Consulta hace unas semanas tras una separación de pareja reciente, después de una relación larga. Refiere dormir alrededor de 4 horas y expresa desesperanza («ya no quiere seguir así»); se exploró riesgo en sesión. Cuenta con una hermana como red de apoyo."},{"tipo":"practica","rotulo":"¿Ya es seguro?","preguntas":[{"p":"«Paciente A, 34 años, el único dentista del municipio, con crisis de pánico.»","ops":["No: «el único dentista del municipio» lo identifica","Sí: ya no tiene nombre","Sí, si la edad es exacta"],"correcta":0,"explica":"Un detalle único basta para reconocer a alguien."},{"p":"«Adolescente de 14 a 16 años, estudiante, con dificultades para dormir y conflictos con su madre.»","ops":["No: menciona a la madre","No: nunca se puede hablar de adolescentes","Sí, parece suficientemente general"],"correcta":2,"explica":"Los roles («su madre») no identifican por sí solos."},{"p":"Tu herramienta dice que no entrena con tus datos. ¿Puedes pegar el expediente completo?","ops":["Sí, si es de noche","No: los datos igual salen de tu control; anonimiza primero","Sí, con esa promesa basta"],"correcta":1,"explica":"Minimizar datos es la mejor protección."}]},{"tipo":"clave","items":["Nunca pegues datos que identifiquen a un paciente en un asistente de IA.","La información de salud es dato personal sensible según la ley mexicana de protección de datos de 2025.","Anonimizar es borrar, generalizar, cambiar terceros por roles, quitar detalles únicos y releer como vecino."]}]},{"id":"c-ia-psicologos-m1-l3","titulo":"Lección 3 — Consentimiento, juicio clínico y código ético","objetivo":"explicar a tus pacientes cómo usas la tecnología en tu consultorio y reconocer los límites éticos que la IA no puede cruzar.","bloques":[{"tipo":"texto","texto":"Si usas herramientas digitales en tu práctica (agenda en línea, videollamada, un asistente de IA para redactar), tus pacientes tienen derecho a saberlo. No se trata de asustar, sino de ser transparente: qué usas, para qué, qué datos <b>no</b> compartes y qué derechos tienen. Esto se integra al <b>consentimiento informado</b> y a tu <b>aviso de privacidad</b>."},{"tipo":"plantilla","rotulo":"Párrafo para tu consentimiento informado (adáptalo con asesoría legal)","texto":"Uso de tecnología en este consultorio\nPara organizar la agenda y redactar documentos administrativos utilizo herramientas digitales, algunas con funciones de inteligencia artificial. Nunca comparto en esas herramientas tu nombre ni datos que te identifiquen, y ninguna decisión sobre tu proceso terapéutico la toma una herramienta: la toma tu terapeuta. Tus datos se tratan conforme a mi aviso de privacidad. Si tienes dudas o no estás de acuerdo con algún uso, puedes decírmelo y lo platicamos.\nNombre y firma del paciente (o de su madre, padre o tutor): ____\nFecha: ____","nota":"No es un texto legal definitivo: revísalo con un abogado y ajústalo a tu aviso de privacidad."},{"tipo":"destacado","texto":"<b>La IA no diagnostica.</b> Diagnosticar exige entrevista, observación, historia, a veces pruebas estandarizadas y, sobre todo, tu formación y tu responsabilidad profesional. Un asistente de IA no ve a la persona, no conoce su contexto y puede sonar convincente estando equivocado. Úsalo para ordenar tu pensamiento, nunca para sustituirlo. Ante riesgo suicida o de violencia, sigue tu protocolo, canaliza a urgencias o al <b>911</b>, y recuerda que la <b>Línea de la Vida 800 911 2000</b> atiende las 24 horas, gratis."},{"tipo":"tabla","titulo":"El código ético en términos generales","encabezados":["Principio","Qué implica con la IA"],"filas":[["Competencia","Solo usas herramientas que entiendes, conoces sus límites y te capacitas para usarlas bien."],["Confidencialidad","Lo que el paciente dice en consulta no sale a terceros sin su consentimiento, salvo las excepciones legales; una IA en la nube es un tercero."],["Responsabilidad","Todo documento que firmas es tuyo, aunque un borrador lo haya escrito una herramienta."],["Beneficio y no daño","El tiempo que ahorras debe traducirse en mejor atención, no en menos revisión."]],"nota":"En México, la referencia más citada es el Código Ético del Psicólogo de la Sociedad Mexicana de Psicología (hay varias ediciones); algunos colegios y federaciones tienen el suyo. Consulta el de tu colegio."},{"tipo":"relacionar","rotulo":"Relaciona la situación con el principio","pares":[["Firmas un informe que redactó la IA sin leerlo completo","Responsabilidad"],["Pegas el nombre de tu paciente en un chat de IA","Confidencialidad"],["Usas una herramienta nueva sin saber qué hace con los datos","Competencia"],["Ahorras una hora de notas y la usas para preparar mejor la sesión","Beneficio y no daño"]]},{"tipo":"completar","rotulo":"Completa","items":[{"frase":"El diagnóstico lo hace el profesional; la IA solo ayuda a ___ lo que tú ya pensaste.","resp":["ordenar","redactar","organizar"]},{"frase":"Tus pacientes deben saber qué tecnología usas: eso forma parte del consentimiento ___.","resp":["informado"]},{"frase":"Un asistente de IA en la nube es, para efectos de confidencialidad, un ___.","resp":["tercero"]}]},{"tipo":"clave","items":["Informa a tus pacientes qué tecnología usas y qué datos nunca compartes.","La IA no diagnostica ni evalúa riesgo: ante una crisis, protocolo, 911 o Línea de la Vida 800 911 2000.","Competencia, confidencialidad y responsabilidad aplican igual cuando usas IA."]}]}],"quiz":{"titulo":"Evaluación del módulo 1","preguntas":[{"p":"¿Qué es una «alucinación» de un asistente de IA?","ops":["Un error de ortografía","Una respuesta demasiado corta","Un fallo de conexión","Un dato inventado que presenta con seguridad"],"correcta":3},{"p":"Según la ley mexicana de protección de datos, la información sobre el estado de salud es…","ops":["Un dato sin protección especial","Un dato personal sensible","Un dato público"],"correcta":1},{"p":"Al momento de escribir, tras la desaparición del INAI, la autoridad en protección de datos personales en posesión de particulares es…","ops":["La PROFECO","La Secretaría Anticorrupción y Buen Gobierno","La Secretaría de Salud","El IMSS"],"correcta":1},{"p":"¿Cuál de estas notas está mejor anonimizada?","ops":["«Rosa, 42 años, dueña de la única papelería de su colonia»","«R. M., nacida el 2 de abril de 1983, con insomnio»","«Mujer de 40 a 45 años, trabaja en comercio, consulta por insomnio»"],"correcta":2},{"p":"Tu herramienta de IA promete no entrenar con tus datos. Lo correcto es…","ops":["Usarla solo con pacientes adultos","Anonimizar de todos modos antes de escribir","Pegar el expediente completo"],"correcta":1},{"p":"Le preguntas a la IA «¿verdad que esto es un trastorno de ansiedad?» y te dice que sí. Eso ilustra…","ops":["Complacencia: tiende a darte la razón","Que el diagnóstico es correcto","Que la IA hizo una evaluación completa"],"correcta":0},{"p":"Un paciente expresa ideas de muerte en un mensaje. ¿Qué haces?","ops":["Le pides a la IA que evalúe el riesgo","Esperas a la siguiente sesión","Sigues tu protocolo de riesgo y, si hay peligro inminente, activas el 911 o canalizas a urgencias"],"correcta":2},{"p":"Firmas un informe que redactó la IA con errores. ¿De quién es la responsabilidad?","ops":["Compartida con el paciente","Tuya, porque lo firmaste","De la empresa de la IA"],"correcta":1}]}},{"id":"c-ia-psicologos-m2","titulo":"Módulo 2 — Notas y documentación sin perder la tarde","resumen":"Convierte tus apuntes sueltos (ya anonimizados) en notas SOAP o DAP, arma tu biblioteca de instrucciones reutilizables y aprende a revisar informes y cartas de referencia antes de firmarlos. Tres lecciones y una evaluación.","lecciones":[{"id":"c-ia-psicologos-m2-l1","titulo":"Lección 1 — De apuntes sueltos a nota SOAP o DAP","objetivo":"transformar apuntes de sesión ya anonimizados en una nota estructurada SOAP o DAP en minutos.","bloques":[{"tipo":"texto","texto":"Al terminar un día de consulta muchos colegas tienen el cuaderno lleno de frases sueltas: «duerme mejor», «tarea de registro: la hizo 3 días», «conflicto con jefe otra vez». Pasarlas a una nota ordenada cuesta tiempo. Aquí la IA ayuda mucho, <b>siempre que le des apuntes ya anonimizados</b> (módulo 1) y revises lo que devuelve."},{"tipo":"tabla","titulo":"Dos formatos de nota muy usados","encabezados":["Formato","Secciones","Cuándo conviene"],"filas":[["<b>SOAP</b>","<b>S</b>ubjetivo (lo que refiere el paciente) · <b>O</b>bjetivo (lo que observas o mides) · <b>A</b>nálisis o evaluación (tu interpretación clínica) · <b>P</b>lan (siguientes pasos)","Contextos de salud con equipos multidisciplinarios"],["<b>DAP</b>","<b>D</b>atos (subjetivos y objetivos juntos) · <b>A</b>nálisis · <b>P</b>lan","Consulta privada, cuando buscas una nota más breve"]],"nota":"Si trabajas en una institución de salud, sigue su formato y la normativa del expediente clínico que aplique (en México, la NOM-004-SSA3-2012 para el expediente clínico). La IA solo acomoda; la nota oficial es tuya."},{"tipo":"comparar","titulo":"La misma petición, dos resultados","malTitulo":"Instrucción débil","mal":"Hazme una nota de mi sesión de hoy: está más tranquila, hizo la tarea, habló de su mamá.","bienTitulo":"Instrucción buena","bien":"Actúa como asistente de redacción clínica. Con los apuntes anonimizados de abajo, redacta una nota en formato DAP. Usa solo la información que te doy; si falta algo, escribe [FALTA DATO]. No agregues diagnósticos, hipótesis ni interpretaciones que yo no haya escrito. Lenguaje profesional, neutro, en tercera persona, máximo 150 palabras."},{"tipo":"plantilla","rotulo":"Instrucción: nota DAP desde apuntes anonimizados","texto":"Actúa como asistente de redacción clínica para un psicólogo.\nTarea: convierte mis apuntes de sesión en una nota en formato DAP (Datos, Análisis, Plan).\nReglas:\n1. Usa solo la información de mis apuntes. No inventes datos, citas ni resultados.\n2. Si falta información para una sección, escribe [FALTA DATO].\n3. En Análisis, redacta únicamente las impresiones que yo anoté; no propongas diagnósticos.\n4. Lenguaje profesional, neutro y no estigmatizante, en tercera persona.\n5. Máximo 150 palabras.\nApuntes (ya anonimizados):\n[pega aquí tus apuntes]","nota":"Cambia «DAP» por «SOAP» y el conteo de palabras según tu estilo. Nunca pegues nombres ni datos identificables."},{"tipo":"ordenar","rotulo":"Ordena las secciones de una nota SOAP","items":[{"frase":"Subjetivo Objetivo Análisis Plan","es":"Primero lo que refiere el paciente, al final lo que harás."}]},{"tipo":"practica","rotulo":"¿En qué sección va?","preguntas":[{"p":"«Refiere que esta semana durmió mejor y tuvo menos discusiones en casa.»","ops":["Subjetivo","Objetivo","Plan"],"correcta":0,"explica":"Es lo que el paciente cuenta."},{"p":"«Puntaje de la escala aplicada en sesión: 14.»","ops":["Subjetivo","Análisis","Objetivo"],"correcta":2,"explica":"Es un dato observado o medido."},{"p":"«Continuar con registro de pensamientos; revisar en la próxima sesión.»","ops":["Subjetivo","Plan","Análisis"],"correcta":1}]},{"tipo":"clave","items":["SOAP separa lo que refiere el paciente de lo que observas; DAP es más breve.","Una buena instrucción dice formato, reglas, límites y qué hacer si falta información.","La IA acomoda tus apuntes; no debe agregar diagnósticos ni interpretaciones."]}]},{"id":"c-ia-psicologos-m2-l2","titulo":"Lección 2 — Tu biblioteca de instrucciones reutilizables","objetivo":"construir plantillas de instrucciones (prompts) para las tareas de documentación que repites cada semana.","bloques":[{"tipo":"texto","texto":"Si cada vez escribes la instrucción desde cero, pierdes el ahorro. La solución es una <b>biblioteca de instrucciones</b>: un documento en tu computadora (no en el chat) con plantillas probadas, cada una con huecos entre corchetes que llenas en segundos."},{"tipo":"pasos","rotulo":"Las 5 partes de una buena instrucción","pasos":["<b>Rol:</b> «Actúa como asistente de redacción clínica».","<b>Tarea:</b> qué quieres exactamente («resume en 5 viñetas…»).","<b>Material:</b> el texto anonimizado con el que va a trabajar.","<b>Formato:</b> extensión, estructura, tono, persona gramatical.","<b>Límites:</b> «no inventes», «no diagnostiques», «marca [FALTA DATO]»."]},{"tipo":"plantilla","rotulo":"Plantilla: resumen de proceso para tu supervisión o cierre","texto":"Actúa como asistente de redacción clínica.\nCon las notas anonimizadas de abajo (sesiones 1 a [número]), elabora un resumen del proceso con estas secciones: motivo de consulta, objetivos acordados, intervenciones realizadas, cambios observados, pendientes.\nUsa solo lo que está en las notas. Si algo no aparece, escribe [FALTA DATO]. No propongas diagnósticos. Máximo [número] palabras, en viñetas.\nNotas:\n[pega aquí]"},{"tipo":"plantilla","rotulo":"Plantilla: revisar tu propia nota","texto":"Revisa la nota clínica de abajo, que yo escribí. No la reescribas. Señálame en una lista:\n1. Frases ambiguas o que mezclan lo que refiere el paciente con mi interpretación.\n2. Lenguaje que pueda sonar estigmatizante o juicioso.\n3. Datos que quedaron identificables y debería generalizar.\n4. Secciones incompletas.\nNota:\n[pega aquí tu nota anonimizada]","nota":"Esta plantilla es muy útil: la IA revisa, tú decides qué cambias."},{"tipo":"comparar","titulo":"Límites en la instrucción","malTitulo":"Sin límites","mal":"Resume estas notas y dime qué tiene la paciente.","bienTitulo":"Con límites","bien":"Resume estas notas en 5 viñetas. Usa solo lo escrito. No propongas diagnósticos ni etiquetas; si algo no está claro, pregúntame en lugar de suponer."},{"tipo":"completar","rotulo":"Completa","items":[{"frase":"Guarda tu biblioteca de instrucciones en un documento ___, no solo en el historial del chat.","resp":["propio","tuyo","personal","local"]},{"frase":"Los huecos que llenas cada vez se marcan entre ___.","resp":["corchetes"]},{"frase":"Si falta información, pide que la IA escriba [FALTA ___] en lugar de inventar.","resp":["DATO","dato"]}]},{"tipo":"reflexion","rotulo":"Tu primera plantilla","pregunta":"¿Qué documento redactas más seguido (nota, resumen, carta, informe)? Escribe su plantilla con las 5 partes: rol, tarea, material, formato y límites.","ayuda":"Pruébala con un caso ficticio antes de usarla con apuntes reales anonimizados."},{"tipo":"clave","items":["Una biblioteca de instrucciones multiplica el ahorro de tiempo.","Rol, tarea, material, formato y límites: las 5 partes de una buena instrucción.","Pídele a la IA que revise tu nota, no que la reescriba: tú decides."]}]},{"id":"c-ia-psicologos-m2-l3","titulo":"Lección 3 — Revisar, corregir y redactar informes y cartas","objetivo":"revisar con método lo que produce la IA y preparar informes y cartas de referencia que puedas firmar con tranquilidad.","bloques":[{"tipo":"texto","texto":"Todo lo que genera la IA es un <b>borrador</b>. En documentos que salen del consultorio (informes para una escuela, cartas de referencia a psiquiatría, constancias de asistencia) la revisión es todavía más importante, porque llevan tu nombre y tu cédula."},{"tipo":"lista","items":["<b>Exactitud:</b> ¿cada dato viene de tus notas? ¿Hay algo que no dijiste?","<b>Juicio clínico:</b> ¿la IA agregó una hipótesis, un diagnóstico o una recomendación que no es tuya?","<b>Lenguaje:</b> ¿habla de la persona y no de la etiqueta («persona con esquizofrenia», no «el esquizofrénico»)?","<b>Mínimo necesario:</b> ¿el destinatario necesita todo lo que dice? Una escuela no necesita detalles de la historia familiar.","<b>Consentimiento:</b> ¿el paciente (o su tutor) autorizó compartir esa información con ese destinatario?"]},{"tipo":"plantilla","rotulo":"Instrucción: carta de referencia a otro profesional","texto":"Actúa como asistente de redacción clínica. Redacta una carta de referencia breve y formal de un psicólogo a [especialidad, por ejemplo: psiquiatría].\nIncluye: motivo de la referencia, resumen del proceso en 3 a 5 líneas, lo que se solicita al colega y disposición para comunicarse.\nUsa solo estos datos anonimizados: [pega aquí].\nNo incluyas diagnósticos que yo no haya escrito. Deja [NOMBRE DEL PACIENTE], [FECHA] y [DATOS DE CONTACTO] como marcadores para llenarlos yo después, fuera del asistente de IA.","nota":"Los datos reales los escribes tú en tu procesador de textos, nunca en el chat."},{"tipo":"comparar","titulo":"Un párrafo de informe escolar","malTitulo":"Tal como lo dejó la IA","mal":"El alumno presenta un claro TDAH con rasgos oposicionistas y probable dislexia, por lo que se recomienda medicación y cambio de escuela.","bienTitulo":"Revisado por la psicóloga","bien":"Durante las sesiones se observaron dificultades para sostener la atención en tareas largas. Se sugiere a la escuela dividir las instrucciones en pasos cortos y dar retroalimentación frecuente. Se ha recomendado a la familia una valoración con especialista para complementar la evaluación."},{"tipo":"practica","rotulo":"¿Qué harías?","preguntas":[{"p":"La IA agregó al informe «probable trastorno de personalidad», que tú nunca anotaste.","ops":["Lo borras: es un juicio clínico que no hiciste","Lo dejas porque suena profesional","Lo cambias por «posible»"],"correcta":0,"explica":"Nada entra al informe si no es tu conclusión fundamentada."},{"p":"La escuela pide un informe y el padre autorizó compartir solo recomendaciones pedagógicas.","ops":["Mandas la nota clínica completa","Mandas el resumen con historia familiar","Incluyes solo las recomendaciones pedagógicas"],"correcta":2,"explica":"Comparte el mínimo necesario y solo lo autorizado."},{"p":"El borrador dice «el paciente bipolar». ¿Cómo lo corriges?","ops":["«El paciente loco»","«La persona con diagnóstico de trastorno bipolar», si ese diagnóstico es tuyo y es necesario mencionarlo","Lo dejas igual"],"correcta":1,"explica":"Lenguaje centrado en la persona y solo si es pertinente."}]},{"tipo":"relacionar","rotulo":"Relaciona el error con la corrección","pares":[["El borrador incluye un dato que no está en tus notas","Borrarlo o verificarlo"],["El informe menciona la historia de pareja de la madre","Recortar al mínimo necesario"],["Dice «el anoréxico»","Usar lenguaje centrado en la persona"],["La carta sugiere un medicamento","Quitar lo que está fuera de tu competencia"]]},{"tipo":"clave","items":["Todo lo que produce la IA es borrador; lo que firmas es tuyo.","Revisa exactitud, juicio clínico, lenguaje, mínimo necesario y consentimiento.","Los datos reales del paciente se agregan fuera del asistente de IA."]}]}],"quiz":{"titulo":"Evaluación del módulo 2","preguntas":[{"p":"En una nota SOAP, «Refiere que se siente más tranquila» va en…","ops":["Objetivo","Plan","Análisis","Subjetivo"],"correcta":3},{"p":"¿Qué diferencia principal hay entre DAP y SOAP?","ops":["SOAP no incluye análisis","DAP junta lo subjetivo y lo objetivo en «Datos»","DAP no tiene plan"],"correcta":1},{"p":"¿Qué instrucción reduce más el riesgo de que la IA invente?","ops":["«Usa solo mis apuntes y escribe [FALTA DATO] si algo no aparece»","«Hazlo lo más completo posible»","«Agrega lo que consideres importante»"],"correcta":0},{"p":"Las cinco partes de una buena instrucción son rol, tarea, material, formato y…","ops":["Límites","Emojis","Precio","Firma"],"correcta":0},{"p":"La IA agregó un diagnóstico que tú no escribiste. ¿Qué haces?","ops":["Lo pasas a la sección de plan","Lo quitas antes de firmar","Lo dejas si suena bien"],"correcta":1},{"p":"Una escuela pide un informe. ¿Qué incluyes?","ops":["Solo lo necesario y autorizado por la familia","Toda la nota clínica","Las transcripciones de las sesiones"],"correcta":0},{"p":"¿Dónde escribes el nombre real del paciente en una carta de referencia?","ops":["En el chat, para que la IA lo acomode","En ningún lado","En tu procesador de textos, después de salir del asistente de IA"],"correcta":2},{"p":"¿Cuál es un ejemplo de lenguaje centrado en la persona?","ops":["«Un caso de depresión»","«Persona que vive con depresión»","«El depresivo»"],"correcta":1}]}},{"id":"c-ia-psicologos-m3","titulo":"Módulo 3 — Un consultorio organizado","resumen":"Formatos de admisión, recordatorios y políticas de cancelación, respuestas de WhatsApp profesionales con límites claros, seguimiento de asistencia en hoja de cálculo y publicaciones para redes que no prometen curas ni exponen a nadie. Tres lecciones y una evaluación.","lecciones":[{"id":"c-ia-psicologos-m3-l1","titulo":"Lección 1 — Admisión, recordatorios y políticas de cancelación","objetivo":"diseñar con IA tu formato de admisión, tus recordatorios de cita y una política de cancelación clara y amable.","bloques":[{"tipo":"texto","texto":"La parte administrativa es donde la IA ahorra más tiempo con menos riesgo, porque trabajas con <b>plantillas</b>, no con datos de pacientes. Le pides el formato vacío; los datos los llena el paciente en tu sistema o en papel."},{"tipo":"plantilla","rotulo":"Instrucción: formato de admisión","texto":"Actúa como asistente administrativo de un consultorio de psicología en México.\nDiseña un formato de primera consulta para adultos con estas secciones: datos de contacto, contacto de emergencia, motivo de consulta en palabras del paciente, tratamientos psicológicos o psiquiátricos previos, medicamentos actuales, expectativas del proceso, y aceptación del aviso de privacidad y del consentimiento informado.\nPreguntas claras, lenguaje sencillo e incluyente, sin preguntas innecesarias. Entrégalo como lista de campos.","nota":"Revisa que no pidas datos que no vas a usar: recabar de más también es un riesgo."},{"tipo":"comparar","titulo":"Recordatorio de cita","malTitulo":"Expone al paciente","mal":"Hola Jorge, te recuerdo tu sesión de terapia por tu problema de alcohol mañana a las 5 pm. Saludos, Psic. Laura.","bienTitulo":"Discreto y claro","bien":"Hola, te recuerdo tu cita de mañana martes a las 17:00 h. Si necesitas cambiarla, avísame con al menos 24 horas de anticipación. Consultorio Psic. Laura Méndez."},{"tipo":"plantilla","rotulo":"Instrucción: política de cancelación","texto":"Redacta la política de cancelación de un consultorio de psicología privado.\nDatos: las sesiones duran 50 minutos; se pide aviso con 24 horas de anticipación; si no hay aviso, se cobra [porcentaje] de la sesión; hay tolerancia de 15 minutos; en casos de emergencia se valora cada situación.\nTono: cálido, firme y respetuoso. Máximo 120 palabras. Sin tecnicismos legales."},{"tipo":"practica","rotulo":"¿Qué recordatorio usarías?","preguntas":[{"p":"Tu paciente comparte el celular con su familia.","ops":["«Te recuerdo tu cita de mañana a las 10:00 h»","«Te recuerdo tu sesión sobre el duelo por tu hermano»","«Te espero para hablar de lo que pasó con tu pareja»"],"correcta":0,"explica":"El mensaje no debe revelar el motivo ni el tipo de servicio más allá de lo necesario."},{"p":"¿Qué incluyes en una política de cancelación?","ops":["El diagnóstico del paciente","Frases de culpa para que no falte","Anticipación del aviso, cobro si no hay aviso y tolerancia"],"correcta":2}]},{"tipo":"tarjetas","rotulo":"Tres plantillas que conviene tener listas","tarjetas":[{"frente":"Confirmación de primera cita","reverso":"Fecha, hora, dirección o enlace, duración, costo, forma de pago y política de cancelación."},{"frente":"Recordatorio 24 horas antes","reverso":"Solo fecha, hora y cómo reprogramar. Nada sobre el motivo de consulta."},{"frente":"Seguimiento tras una falta","reverso":"Mensaje breve, sin reproches, que ofrece reagendar."}]},{"tipo":"clave","items":["Pídele a la IA formatos vacíos; los datos del paciente no pasan por ella.","Los recordatorios no deben revelar el motivo de consulta.","Una política de cancelación clara protege tu agenda y la relación terapéutica."]}]},{"id":"c-ia-psicologos-m3-l2","titulo":"Lección 2 — WhatsApp con límites y agenda en hoja de cálculo","objetivo":"responder por WhatsApp de forma profesional y con límites, y dar seguimiento a la asistencia de tus pacientes en una hoja de cálculo.","bloques":[{"tipo":"texto","texto":"WhatsApp es cómodo, pero puede convertirse en un consultorio abierto las 24 horas. Define por escrito <b>para qué sí</b> se usa (agendar, cambiar citas, enviar materiales) y <b>para qué no</b> (sesiones por mensaje, crisis). La IA te ayuda a redactar respuestas que suenan cálidas y a la vez ponen límites."},{"tipo":"plantilla","rotulo":"Respuestas rápidas para WhatsApp (revísalas y guárdalas)","texto":"Fuera de horario:\nGracias por tu mensaje. Mi horario de atención por este medio es de lunes a viernes de 9:00 a 19:00 h. Te respondo en cuanto esté disponible. Si estás en una crisis o en peligro, llama al 911 o a la Línea de la Vida 800 911 2000 (24 horas, gratuita).\n\nCuando quieren platicar el tema por mensaje:\nGracias por la confianza de contarme esto. Es importante y merece el espacio de la sesión, donde puedo escucharte con calma. ¿Te parece si lo vemos el [día]? Si necesitas adelantar la cita, dime y buscamos un espacio.\n\nCambio de cita:\nCon gusto. Tengo disponible [opciones]. ¿Cuál te acomoda mejor?","nota":"No uses la IA para responder mensajes de pacientes en tiempo real: prepara las plantillas antes y personalízalas tú."},{"tipo":"destacado","texto":"<b>Crisis por mensaje.</b> Si un paciente escribe algo que sugiere riesgo inminente, no lo pongas en un chat de IA ni esperes: sigue tu protocolo (llamarle, contactar a su red de apoyo si lo acordaron, orientar al 911 o a urgencias). Deja por escrito, en tu consentimiento, cómo actúas en esos casos."},{"tipo":"excel","rotulo":"Seguimiento de asistencia (solo claves, sin nombres)","datos":[["Clave","Programadas","Asistidas","Canceló con aviso","Faltó sin aviso","% asistencia","Seguimiento"],["P-014",8,7,1,0,"",""],["P-022",6,3,1,2,"",""],["P-031",4,4,0,0,100,"Al corriente"],["P-047",5,2,1,2,40,"Contactar"],["","","","","","",""],["Total de faltas sin aviso","","","","","",""],["Pacientes con 2 o más faltas","","","","","",""]],"retos":[{"celda":"F2","formula":"=REDONDEAR(C2/B2*100,0)","esperado":88,"requiere":"REDONDEAR(","texto":"<b>F2</b>: calcula el porcentaje de asistencia de P-014: asistidas entre programadas por 100, redondeado a entero.","pista":"=REDONDEAR(C2/B2*100,0)"},{"celda":"F3","formula":"=REDONDEAR(C3/B3*100,0)","esperado":50,"requiere":"REDONDEAR(","texto":"<b>F3</b>: haz lo mismo para P-022."},{"celda":"G2","formula":"=SI(E2>=2,\"Contactar\",\"Al corriente\")","esperado":"Al corriente","requiere":"SI(","texto":"<b>G2</b>: si las faltas sin aviso son 2 o más, escribe «Contactar»; si no, «Al corriente».","pista":"=SI(E2>=2,\"Contactar\",\"Al corriente\")"},{"celda":"G3","formula":"=SI(E3>=2,\"Contactar\",\"Al corriente\")","esperado":"Contactar","requiere":"SI(","texto":"<b>G3</b>: aplica la misma regla a P-022."},{"celda":"B7","formula":"=SUMA(E2:E5)","esperado":4,"requiere":"SUMA(","texto":"<b>B7</b>: suma todas las faltas sin aviso."},{"celda":"B8","formula":"=CONTAR.SI(G2:G5,\"Contactar\")","esperado":2,"requiere":"CONTAR.SI(","texto":"<b>B8</b>: cuenta cuántos pacientes tienen «Contactar» en la columna de seguimiento.","explica":"Con esta hoja sabes a quién escribirle un mensaje de seguimiento sin reproches. Usa claves: la lista de claves y nombres se guarda aparte, protegida."}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"¿Por qué la hoja usa claves y no nombres?","ops":["Porque así lo exige el WhatsApp","Para minimizar datos identificables si el archivo se comparte o se pierde","Porque las fórmulas no aceptan nombres"],"correcta":1},{"p":"Un paciente escribe a las 23:00 «ya no puedo más, esta noche termino con todo». ¿Qué haces?","ops":["Activas tu protocolo de crisis: contacto directo, red de apoyo y 911 si hay riesgo inminente","Pegas el mensaje en la IA para ver qué responder","Le contestas con tu plantilla de fuera de horario y esperas al lunes"],"correcta":0,"explica":"Una plantilla automática nunca sustituye tu protocolo de crisis."}]},{"tipo":"clave","items":["Define para qué sí y para qué no se usa WhatsApp, y ten plantillas revisadas.","Ante riesgo inminente: protocolo, red de apoyo, 911 o Línea de la Vida 800 911 2000.","Una hoja con claves te dice quién necesita seguimiento sin exponer nombres."]}]},{"id":"c-ia-psicologos-m3-l3","titulo":"Lección 3 — Redes sociales sin prometer curas ni exponer a nadie","objetivo":"crear publicaciones de divulgación para redes que sean útiles, éticas y fieles a la evidencia.","bloques":[{"tipo":"texto","texto":"Publicar en redes te da visibilidad, pero en salud mental hay reglas claras: <b>no prometer resultados</b>, <b>no diagnosticar a distancia</b>, <b>no usar casos reales</b> (ni «con permiso» si el paciente podría reconocerse o arrepentirse) y <b>no difundir mitos</b>. La IA puede proponerte ideas y borradores; tú verificas que sean correctos."},{"tipo":"comparar","titulo":"La misma publicación","malTitulo":"Publicación riesgosa","mal":"¡Supera tu ansiedad en 3 sesiones garantizado! Mi paciente Ana (con su permiso) llegó destrozada y hoy es otra persona. Si te sientes triste seguro tienes depresión: agenda ya.","bienTitulo":"Publicación ética","bien":"¿Sabías que la ansiedad es una reacción normal que a veces se vuelve muy intensa o constante? Si te está impidiendo dormir, trabajar o convivir, vale la pena consultarlo con un profesional. En terapia trabajamos estrategias con evidencia científica. Si estás en crisis, llama a la Línea de la Vida 800 911 2000."},{"tipo":"plantilla","rotulo":"Instrucción: calendario de divulgación","texto":"Actúa como asistente de comunicación para una psicóloga clínica en México.\nPropón 8 ideas de publicaciones de divulgación para Instagram y Facebook sobre [tema, por ejemplo: sueño y estrés], para adultos.\nReglas: información basada en evidencia (OMS, APA, guías clínicas reconocidas), sin prometer resultados, sin casos de pacientes, sin frases que diagnostiquen a quien lee, sin neuromitos. Cada idea con título, 3 mensajes clave y una invitación a consultar.\nAl final, marca qué datos debo verificar en una fuente."},{"tipo":"relacionar","rotulo":"Relaciona el error con la regla","pares":[["«Te curo el insomnio en un mes»","No prometer resultados"],["Contar la historia de un paciente con su permiso","No usar casos reales"],["«Si te distraes fácil, tienes TDAH»","No diagnosticar a distancia"],["«Solo usamos el 10% del cerebro»","No difundir mitos"]]},{"tipo":"practica","rotulo":"¿Publicas o corriges?","preguntas":[{"p":"«Cinco señales de que conviene buscar apoyo psicológico», con fuente de la OMS.","ops":["Corriges: nunca se habla de señales","Corriges: debe prometer un resultado","Publicas, tras verificar la fuente"],"correcta":2},{"p":"«Las personas con trastorno bipolar son impredecibles y peligrosas.»","ops":["Publicas con un emoji para suavizar","Corriges: es un estereotipo estigmatizante y falso","Publicas si genera muchas interacciones"],"correcta":1,"explica":"Divulgar también es combatir el estigma."}]},{"tipo":"reflexion","rotulo":"Tu línea editorial","pregunta":"Escribe tres temas sobre los que te gustaría divulgar y una frase que nunca publicarías por ética.","ayuda":"Ejemplo: «Duelo en familia», «Sueño y estrés», «Cuándo ir a terapia». Nunca publicaría: «garantizado»."},{"tipo":"clave","items":["En redes: sin promesas de curación, sin casos reales y sin diagnósticos a distancia.","La IA propone ideas; tú verificas cada dato contra fuentes con evidencia.","Divulgar bien ayuda a reducir el estigma y a que la gente pida ayuda a tiempo."]}]}],"quiz":{"titulo":"Evaluación del módulo 3","preguntas":[{"p":"¿Qué es lo más seguro pedirle a la IA para tu admisión?","ops":["Que capture los datos de tus pacientes","Que califique las respuestas del paciente","El formato vacío de primera consulta"],"correcta":2},{"p":"¿Cuál recordatorio es adecuado?","ops":["«Te espero para seguir con lo de tu divorcio»","«Te recuerdo tu cita de mañana a las 18:00 h»","«Te recuerdo tu sesión por tus ataques de pánico»"],"correcta":1},{"p":"Una política de cancelación debe incluir…","ops":["La anticipación del aviso y qué pasa si no se avisa","El motivo de consulta de cada paciente","Solo el costo de la sesión"],"correcta":0},{"p":"¿Para qué NO conviene usar WhatsApp en el consultorio?","ops":["Para agendar citas","Para enviar materiales de psicoeducación","Para dar sesiones por mensaje o atender crisis"],"correcta":2},{"p":"En la hoja de asistencia, ¿qué fórmula devuelve «Contactar» si hay 2 o más faltas en E2?","ops":["=CONTAR(E2,\"Contactar\")","=SI(E2>=2,\"Contactar\",\"Al corriente\")","=SUMA(E2>=2)"],"correcta":1},{"p":"¿Qué número das ante una crisis de salud mental, además del 911?","ops":["Línea de la Vida 800 911 2000","El número de tu consultorio únicamente","Ninguno: esperas a la sesión"],"correcta":0},{"p":"¿Cuál publicación es ética?","ops":["«Si estás triste, tienes depresión»","Una explicación sobre cuándo buscar ayuda, con fuente confiable","Un testimonio de paciente «con permiso»","«Resultados garantizados en 5 sesiones»"],"correcta":1},{"p":"¿Qué haces con los datos que la IA incluye en un borrador para redes?","ops":["Solo corriges la ortografía","Los verificas en fuentes con evidencia antes de publicar","Los publicas tal cual"],"correcta":1}]}},{"id":"c-ia-psicologos-m4","titulo":"Módulo 4 — Materiales para pacientes","resumen":"Hojas de psicoeducación adaptadas a la edad y al nivel de lectura, hojas de ejercicios y registros de pensamientos o de actividades, y un método para verificar exactitud, evidencia y accesibilidad antes de entregar cualquier material. Tres lecciones y una evaluación.","lecciones":[{"id":"c-ia-psicologos-m4-l1","titulo":"Lección 1 — Psicoeducación clara para cada edad","objetivo":"adaptar una explicación de psicoeducación a la edad y al nivel de lectura de tu paciente.","bloques":[{"tipo":"texto","texto":"La psicoeducación funciona cuando el paciente la <b>entiende y la recuerda</b>. Un mismo tema, como la ansiedad, se explica distinto a un niño de 8 años, a un adolescente, a un adulto con estudios universitarios o a una persona adulta mayor que lee poco. La IA es muy buena para reescribir un texto en distintos niveles; tú te aseguras de que el contenido siga siendo correcto."},{"tipo":"plantilla","rotulo":"Instrucción: adaptar una hoja de psicoeducación","texto":"Actúa como asistente de redacción para materiales de psicoeducación.\nTema: [por ejemplo: qué es la ansiedad y para qué sirve].\nPúblico: [edad, escolaridad y contexto, por ejemplo: niñas y niños de 8 a 10 años en México].\nEscribe una hoja de máximo [número] palabras con: explicación sencilla, un ejemplo cotidiano, qué se puede hacer y cuándo pedir ayuda a un adulto de confianza.\nReglas: frases cortas, palabras comunes, tono cálido, sin miedo ni culpa, sin diagnósticos ni promesas de curación. Basado en información de la OMS o de guías clínicas reconocidas.\nAl final, lista las afirmaciones que debo verificar."},{"tipo":"comparar","titulo":"Explicar la ansiedad a un niño de 9 años","malTitulo":"Muy técnico","mal":"La ansiedad es una respuesta psicofisiológica mediada por el sistema nervioso autónomo ante estímulos percibidos como amenazantes, que puede cronificarse y generar deterioro funcional.","bienTitulo":"Adaptado","bien":"La ansiedad es como una alarma que tiene tu cuerpo para cuidarte. A veces suena cuando hay un peligro de verdad, y a veces suena aunque no pase nada malo. Cuando suena, tu corazón late rápido y sientes la panza rara. Hay trucos para bajarle el volumen, como respirar despacio. Si la alarma suena mucho, cuéntaselo a un adulto de confianza."},{"tipo":"excel","rotulo":"¿Está fácil de leer? (regla práctica del curso)","datos":[["Material","Público","Palabras","Oraciones","Palabras por oración","Máximo sugerido","Veredicto"],["Qué es la ansiedad","Adultos",240,12,"",20,""],["El enojo y yo","Niños 8 a 10",180,6,"",12,""],["Guía de sueño","Adolescentes",150,10,15,15,"OK"],["Duelo en familia","Adultos",300,10,30,20,"Acortar frases"],["","","","","","",""],["Materiales por corregir","","","","","",""]],"retos":[{"celda":"E2","formula":"=REDONDEAR(C2/D2,0)","esperado":20,"requiere":"REDONDEAR(","texto":"<b>E2</b>: calcula las palabras por oración: palabras entre oraciones, redondeado a entero.","pista":"=REDONDEAR(C2/D2,0)"},{"celda":"E3","formula":"=REDONDEAR(C3/D3,0)","esperado":30,"requiere":"REDONDEAR(","texto":"<b>E3</b>: haz lo mismo para la hoja de niños."},{"celda":"G2","formula":"=SI(E2>F2,\"Acortar frases\",\"OK\")","esperado":"OK","requiere":"SI(","texto":"<b>G2</b>: si las palabras por oración superan el máximo sugerido, escribe «Acortar frases»; si no, «OK».","pista":"=SI(E2>F2,\"Acortar frases\",\"OK\")"},{"celda":"G3","formula":"=SI(E3>F3,\"Acortar frases\",\"OK\")","esperado":"Acortar frases","requiere":"SI(","texto":"<b>G3</b>: aplica la regla a la hoja de niños."},{"celda":"B7","formula":"=CONTAR.SI(G2:G5,\"Acortar frases\")","esperado":2,"requiere":"CONTAR.SI(","texto":"<b>B7</b>: cuenta cuántos materiales necesitan acortar frases.","explica":"Las frases largas son una de las principales barreras de lectura. Esta regla práctica no sustituye probar el material con personas del público al que va dirigido."}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Tu paciente adulto mayor lee con dificultad. ¿Qué pides a la IA?","ops":["Frases cortas, palabras comunes, letra grande y un ejemplo cotidiano","Más tecnicismos para que se vea profesional","Un texto más largo para que no le falte nada"],"correcta":0,"explica":"Adapta forma y extensión, no el rigor del contenido."},{"p":"La IA simplificó tanto que ahora dice «la ansiedad se quita respirando». ¿Qué haces?","ops":["Lo dejas porque es fácil de entender","Lo publicas para todos tus pacientes","Corriges: la respiración ayuda a regularse, pero no «quita» la ansiedad"],"correcta":2,"explica":"Simplificar no es distorsionar."}]},{"tipo":"clave","items":["La misma idea se explica distinto según edad, escolaridad y contexto.","Pide frases cortas, ejemplos cotidianos y cuándo pedir ayuda.","Simplificar no debe distorsionar: revisa que el contenido siga siendo correcto."]}]},{"id":"c-ia-psicologos-m4-l2","titulo":"Lección 2 — Hojas de ejercicios y registros adaptados","objetivo":"crear hojas de ejercicios, registros de pensamientos y registros de actividades adaptados a cada paciente.","bloques":[{"tipo":"texto","texto":"Los registros son herramientas clásicas de la terapia cognitivo-conductual (por ejemplo, los difundidos por el Beck Institute): el <b>registro de pensamientos</b> ayuda a notar la relación entre situación, pensamiento, emoción y conducta; el <b>registro de actividades</b> apoya la activación conductual. La IA puede adaptar su formato y su lenguaje; <b>tú decides</b> si ese ejercicio es adecuado para ese paciente y en qué momento del proceso."},{"tipo":"tabla","titulo":"Columnas de un registro de pensamientos sencillo","encabezados":["Columna","Pregunta guía"],"filas":[["Situación","¿Qué pasó, dónde y con quién?"],["Pensamiento","¿Qué pasó por tu mente en ese momento?"],["Emoción","¿Qué sentiste y con qué intensidad, del 0 al 10?"],["Qué hice","¿Cómo reaccionaste?"],["Otra forma de verlo","¿Qué le dirías a un amigo en la misma situación?"]]},{"tipo":"plantilla","rotulo":"Instrucción: adaptar un registro","texto":"Actúa como asistente de diseño de materiales terapéuticos.\nAdapta un registro de pensamientos de 5 columnas (situación, pensamiento, emoción de 0 a 10, qué hice, otra forma de verlo) para [público, por ejemplo: adolescentes de secundaria].\nIncluye: instrucciones de máximo 4 líneas, un ejemplo resuelto con una situación cotidiana ficticia (no clínica grave) y preguntas guía en lenguaje sencillo.\nNo agregues técnicas nuevas ni interpretes. Formato listo para imprimir en media carta."},{"tipo":"plantilla","rotulo":"Instrucción: registro de actividades semanal","texto":"Diseña un registro de actividades de lunes a domingo para un adulto, con tres columnas por día: actividad realizada, agrado (0 a 10) y sensación de logro (0 a 10).\nAgrega al final tres preguntas de reflexión breves para revisar en sesión.\nLenguaje sencillo, sin tecnicismos, sin frases motivacionales exageradas.","nota":"Pruébalo tú primero una semana: descubrirás instrucciones confusas antes que tu paciente."},{"tipo":"ordenar","rotulo":"Ordena las columnas del registro","items":[{"frase":"Situación pensamiento emoción qué hice otra forma de verlo","es":"Del hecho a la respuesta alternativa."}]},{"tipo":"practica","rotulo":"¿Quién decide?","preguntas":[{"p":"¿Es buen momento para darle un registro de pensamientos a tu paciente?","ops":["El paciente, eligiendo entre muchas hojas","Tú, según tu evaluación y el plan de tratamiento","La IA"],"correcta":1},{"p":"La IA propone agregar «técnicas de reprogramación mental» al ejercicio. ¿Qué haces?","ops":["Lo quitas: no tiene respaldo de evidencia","Lo agregas para enriquecerlo","Lo dejas como opcional"],"correcta":0,"explica":"Solo entregas técnicas con evidencia y que sabes aplicar."}]},{"tipo":"reflexion","rotulo":"Tu material más usado","pregunta":"¿Qué hoja de ejercicios entregas más seguido? ¿Cómo la adaptarías para un paciente con baja escolaridad y para un adolescente?","ayuda":"Piensa en extensión, palabras, ejemplos y formato (impreso, foto en el celular, audio)."},{"tipo":"clave","items":["La IA adapta formato y lenguaje; tú decides el ejercicio y el momento.","Un ejemplo resuelto con una situación cotidiana ficticia ayuda mucho.","Nada de técnicas sin evidencia, aunque la IA las sugiera."]}]},{"id":"c-ia-psicologos-m4-l3","titulo":"Lección 3 — Verifica y haz accesible antes de entregar","objetivo":"verificar exactitud y evidencia de un material generado con IA y hacerlo accesible para personas con distintas necesidades.","bloques":[{"tipo":"texto","texto":"Un material de psicoeducación con un error puede hacer daño: una cifra falsa, una recomendación sin respaldo o una frase que culpa al paciente. Antes de imprimirlo o enviarlo, aplica una revisión sistemática."},{"tipo":"pasos","rotulo":"Revisión en 5 pasos","pasos":["<b>Subraya cada afirmación de hecho</b> (cifras, «está comprobado que…», recomendaciones).","<b>Verifica cada una</b> en una fuente confiable: OMS, APA, NICE, CDC, guías clínicas o artículos revisados por pares.","<b>Borra o corrige</b> lo que no puedas confirmar.","<b>Revisa el tono:</b> sin culpa, sin miedo, sin promesas, sin lenguaje estigmatizante.","<b>Agrega cuándo buscar ayuda:</b> tu contacto, el 911 en emergencias y la Línea de la Vida 800 911 2000."]},{"tipo":"lista","items":["<b>Lectura fácil:</b> frases cortas, una idea por párrafo, palabras comunes.","<b>Tamaño y contraste:</b> letra de al menos 12 puntos impresa, buen contraste, sin texto sobre fotografías.","<b>Formatos alternativos:</b> audio o video corto para quien lee poco o tiene discapacidad visual.","<b>Imágenes con descripción</b> si lo envías en digital.","<b>Lenguaje incluyente</b> y ejemplos que reflejen distintas familias y contextos de México."]},{"tipo":"plantilla","rotulo":"Instrucción: revisar accesibilidad","texto":"Revisa el siguiente material de psicoeducación y dime, sin reescribirlo:\n1. Frases de más de 20 palabras.\n2. Palabras técnicas que podría cambiar por otras comunes.\n3. Frases que puedan sonar a culpa, miedo o promesa de curación.\n4. Afirmaciones de hecho que debo verificar en una fuente.\n5. Sugerencias para una versión en audio.\nMaterial:\n[pega aquí]"},{"tipo":"completar","rotulo":"Completa","items":[{"frase":"Toda afirmación de hecho se verifica en una fuente ___ antes de entregar el material.","resp":["confiable","oficial","reconocida"]},{"frase":"Un material accesible tiene frases cortas y una idea por ___.","resp":["párrafo"]},{"frase":"Todo material debe decir cuándo buscar ___ profesional.","resp":["ayuda","apoyo","atención"]}]},{"tipo":"tarjetas","rotulo":"Mitos que la IA a veces repite","tarjetas":[{"frente":"«Usamos solo el 10% del cerebro»","reverso":"Falso. Es un neuromito: usamos todo el cerebro, aunque no todas las áreas al mismo tiempo."},{"frente":"«Cada persona aprende según su estilo visual, auditivo o kinestésico»","reverso":"La evidencia no respalda adaptar la enseñanza a esos estilos como si fueran una verdad."},{"frente":"«Las personas son de cerebro izquierdo o de cerebro derecho»","reverso":"Neuromito: ambos hemisferios trabajan juntos en casi todas las tareas."}]},{"tipo":"clave","items":["Subraya, verifica, corrige, revisa el tono y agrega cuándo buscar ayuda.","La accesibilidad incluye lectura fácil, buen contraste y formatos alternativos.","Detecta y elimina los neuromitos que la IA puede repetir."]}]}],"quiz":{"titulo":"Evaluación del módulo 4","preguntas":[{"p":"Al adaptar psicoeducación para un niño, ¿qué debe mantenerse?","ops":["Los tecnicismos","La misma extensión que para adultos","La exactitud del contenido"],"correcta":2},{"p":"En la hoja de cálculo, ¿cómo obtienes las palabras por oración?","ops":["Palabras multiplicadas por oraciones","Palabras menos oraciones","Palabras entre oraciones","Oraciones entre palabras"],"correcta":2},{"p":"¿Quién decide si un registro de pensamientos es adecuado para un paciente?","ops":["El profesional, según su evaluación y plan","La IA","La escuela"],"correcta":0},{"p":"¿Qué columnas forman un registro de pensamientos sencillo?","ops":["Nombre, CURP, diagnóstico y dosis","Día, hora y costo de la sesión","Situación, pensamiento, emoción, qué hice y otra forma de verlo"],"correcta":2},{"p":"La IA sugiere una técnica sin evidencia. Tú…","ops":["La presentas como novedad","La quitas del material","La agregas como opcional"],"correcta":1},{"p":"¿Cuál de estas es un neuromito?","ops":["«Usamos solo el 10% del cerebro»","«El sueño influye en el estado de ánimo»","«La actividad física puede ayudar a regular el estrés»"],"correcta":0},{"p":"¿Qué mejora la accesibilidad de una hoja?","ops":["Texto sobre fotografías","Letra de 8 puntos para que quepa todo","Frases cortas, buen contraste y versión en audio"],"correcta":2},{"p":"¿Qué no debe faltar al final de un material de psicoeducación?","ops":["Una promesa de mejora","Cuándo buscar ayuda y a dónde llamar","Un diagnóstico para el lector"],"correcta":1}]}},{"id":"c-ia-psicologos-m5","titulo":"Módulo 5 — Estudio y actualización profesional","resumen":"Resume artículos y libros largos sin perder matices, verifica que las referencias existan de verdad, prepara supervisión y presentaciones de casos anonimizados y arma tu plan personal de 30 días de uso responsable. Tres lecciones y una evaluación.","lecciones":[{"id":"c-ia-psicologos-m5-l1","titulo":"Lección 1 — Resumir artículos y libros sin perder matices","objetivo":"resumir artículos científicos y libros largos con IA conservando limitaciones, población estudiada y tamaño del efecto.","bloques":[{"tipo":"texto","texto":"Mantenerte actualizado es parte de tu competencia profesional, pero leer todo lo que se publica es imposible. La IA puede ayudarte a hacer un primer resumen de un artículo o de un capítulo que <b>ya tienes</b>. El riesgo: que simplifique de más y convierta «en una muestra pequeña de universitarios se observó una mejora moderada» en «está comprobado que funciona»."},{"tipo":"plantilla","rotulo":"Instrucción: resumen fiel de un artículo","texto":"Te comparto el texto de un artículo científico. Resúmelo con estas secciones:\n1. Pregunta de investigación.\n2. Diseño del estudio (por ejemplo: ensayo aleatorizado, metaanálisis, estudio de caso).\n3. Participantes: cuántos, edad, país, criterios de inclusión.\n4. Intervención y comparación.\n5. Resultados principales con sus cifras tal como aparecen.\n6. Limitaciones que reconocen los autores.\n7. Qué NO se puede concluir de este estudio.\nUsa solo el texto que te doy. Si algo no aparece, escribe [NO SE MENCIONA]. No agregues estudios externos.\nTexto:\n[pega aquí]","nota":"Revisa los derechos de autor y las condiciones de tu herramienta antes de subir documentos completos. Después, lee al menos el resumen original y la sección de resultados."},{"tipo":"comparar","titulo":"Resumen del mismo estudio","malTitulo":"Pierde matices","mal":"El estudio demostró que la terapia en línea cura la depresión.","bienTitulo":"Conserva matices","bien":"En un ensayo con 120 adultos universitarios de un solo país, la intervención en línea redujo los síntomas depresivos de forma moderada frente a lista de espera a las 8 semanas. No hubo seguimiento a largo plazo y la muestra no incluyó casos graves."},{"tipo":"tarjetas","rotulo":"Preguntas para no perder matices","tarjetas":[{"frente":"¿Quiénes participaron?","reverso":"Una intervención probada en universitarios puede no aplicar igual a adultos mayores o a comunidades rurales."},{"frente":"¿Contra qué se comparó?","reverso":"Mejorar frente a «lista de espera» no es lo mismo que mejorar frente a otro tratamiento."},{"frente":"¿Qué tan grande fue el efecto?","reverso":"«Estadísticamente significativo» no siempre significa «clínicamente importante»."},{"frente":"¿Qué dicen las limitaciones?","reverso":"Los autores suelen decir qué no se puede concluir; la IA tiende a omitirlo."}]},{"tipo":"practica","rotulo":"¿Qué harías?","preguntas":[{"p":"La IA resume: «este libro demuestra que el apego se define en el primer año y no cambia».","ops":["Citarlo en tu próxima conferencia","Compartirlo con tus pacientes","Revisar el texto original: suena a sobresimplificación"],"correcta":2,"explica":"Afirmaciones absolutas son una señal de alerta."},{"p":"El resumen no menciona limitaciones.","ops":["Descartas el artículo","Pides la sección de limitaciones y la lees en el original","Asumes que no tiene"],"correcta":1}]},{"tipo":"clave","items":["Pide resúmenes con diseño, participantes, comparación, resultados y limitaciones.","Desconfía de las afirmaciones absolutas: «cura», «demuestra», «siempre».","El resumen de la IA es una puerta de entrada; la lectura del original es tu responsabilidad."]}]},{"id":"c-ia-psicologos-m5-l2","titulo":"Lección 2 — Verifica que las referencias existan","objetivo":"comprobar en PubMed o Google Académico que una referencia sugerida por la IA existe y dice lo que se afirma.","bloques":[{"tipo":"destacado","texto":"<b>La IA inventa referencias.</b> Es una de sus fallas más documentadas: genera citas con autores reales, títulos plausibles, revistas existentes y años creíbles… de artículos que nunca se publicaron. Otras veces el artículo existe, pero no dice lo que la IA afirma. Nunca pongas en un informe, una tesis o una presentación una referencia que no hayas encontrado y leído tú."},{"tipo":"pasos","rotulo":"Verifica una referencia en 5 pasos","pasos":["Copia el <b>título exacto</b> y búscalo entre comillas en <b>PubMed</b> (pubmed.ncbi.nlm.nih.gov) o en <b>Google Académico</b> (scholar.google.com).","Si trae <b>DOI</b>, pégalo en doi.org: debe llevarte al artículo correcto.","Compara <b>autores, año, revista, volumen y páginas</b>.","Lee al menos el <b>resumen</b> y confirma que dice lo que la IA afirmó.","Si no aparece o no coincide, <b>descártala</b> y busca tú la evidencia."]},{"tipo":"excel","rotulo":"Bitácora de verificación de referencias","datos":[["Referencia","¿Existe?","¿Autores y año coinciden?","¿Dice lo que afirmó la IA?","Decisión"],["R1","Sí","Sí","Sí",""],["R2","No","No","No",""],["R3","Sí","No","Sí","No usar"],["R4","Sí","Sí","No","No usar"],["R5","Sí","Sí","Sí","Usar"],["R6","No","No","No","No usar"],["","","","",""],["Referencias inexistentes","","","",""],["% utilizable","","","",""]],"retos":[{"celda":"E2","formula":"=SI(Y(B2=\"Sí\",C2=\"Sí\",D2=\"Sí\"),\"Usar\",\"No usar\")","esperado":"Usar","requiere":"Y(","texto":"<b>E2</b>: escribe «Usar» solo si las tres columnas dicen «Sí»; si no, «No usar». Combina SI con Y.","pista":"=SI(Y(B2=\"Sí\",C2=\"Sí\",D2=\"Sí\"),\"Usar\",\"No usar\")"},{"celda":"E3","formula":"=SI(Y(B3=\"Sí\",C3=\"Sí\",D3=\"Sí\"),\"Usar\",\"No usar\")","esperado":"No usar","requiere":"Y(","texto":"<b>E3</b>: aplica la misma regla a R2."},{"celda":"B9","formula":"=CONTAR.SI(B2:B7,\"No\")","esperado":2,"requiere":"CONTAR.SI(","texto":"<b>B9</b>: cuenta cuántas referencias no existen."},{"celda":"B10","formula":"=REDONDEAR(CONTAR.SI(E2:E7,\"Usar\")/CONTARA(A2:A7)*100,0)","esperado":33,"requiere":"CONTARA(","texto":"<b>B10</b>: calcula el porcentaje de referencias utilizables: las que dicen «Usar» entre el total de referencias, por 100, redondeado.","pista":"=REDONDEAR(CONTAR.SI(E2:E7,\"Usar\")/CONTARA(A2:A7)*100,0)","explica":"Solo 2 de 6 sirvieron. Es un ejemplo ficticio, pero ilustra por qué nunca se copia una bibliografía de la IA sin verificar."}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"La IA te da una referencia con DOI, pero al pegarlo en doi.org abre un artículo de cardiología. ¿Qué haces?","ops":["La descartas y buscas tú la evidencia","La usas: el DOI existe","Cambias el DOI por otro parecido"],"correcta":0},{"p":"Encontraste el artículo, pero su resumen no menciona lo que la IA afirmó.","ops":["Lo citas de todos modos","Le pides a la IA que confirme","No lo usas para respaldar esa afirmación"],"correcta":2,"explica":"Preguntarle a la misma IA no es verificar."}]},{"tipo":"clave","items":["La IA inventa referencias que parecen reales.","Verifica título, DOI, autores, año y contenido en PubMed o Google Académico.","Si no la encontraste y leíste tú, no la cites."]}]},{"id":"c-ia-psicologos-m5-l3","titulo":"Lección 3 — Supervisión, congresos y tu plan de 30 días","objetivo":"preparar la presentación de un caso anonimizado para supervisión o congreso y diseñar tu plan personal de uso responsable de IA.","bloques":[{"tipo":"texto","texto":"Llevar un caso a supervisión o presentarlo en un congreso exige el mismo cuidado que el módulo 1, con un extra: en una presentación pública el riesgo de que alguien reconozca al paciente es mayor, sobre todo en ciudades pequeñas. Para presentaciones públicas, además de anonimizar, pide el consentimiento del paciente y sigue las reglas del congreso o de la revista."},{"tipo":"plantilla","rotulo":"Instrucción: preparar un caso para supervisión","texto":"Actúa como asistente de un psicólogo que prepara una supervisión clínica.\nCon el resumen anonimizado de abajo, organiza una presentación de 10 minutos con: datos generales (sin identificadores), motivo de consulta, historia relevante, formulación del caso tal como yo la escribí, intervenciones realizadas, evolución y 3 preguntas concretas para mi supervisor.\nNo agregues hipótesis ni diagnósticos. Señala cualquier detalle que todavía pueda identificar a la persona.\nResumen anonimizado:\n[pega aquí]"},{"tipo":"comparar","titulo":"Pregunta para tu supervisor","malTitulo":"Vaga","mal":"¿Qué hago con este paciente?","bienTitulo":"Concreta","bien":"En las últimas 4 sesiones el paciente llega tarde y cambia de tema cuando hablamos de su padre. ¿Cómo puedo abordar esta evitación sin romper la alianza terapéutica?"},{"tipo":"pasos","rotulo":"Tu plan de 30 días","pasos":["<b>Semana 1:</b> elige una sola tarea (por ejemplo, recordatorios y política de cancelación) y crea sus plantillas.","<b>Semana 2:</b> practica anonimizar con 3 casos ficticios y crea tu plantilla de nota DAP o SOAP.","<b>Semana 3:</b> usa la plantilla con apuntes reales anonimizados; revisa cada nota y anota los errores que encuentres.","<b>Semana 4:</b> actualiza tu consentimiento informado y tu aviso de privacidad con asesoría; mide cuánto tiempo ahorraste y decide qué sigue."]},{"tipo":"lista","items":["Nunca datos identificables en el chat.","Todo es borrador hasta que lo revisas.","La IA no diagnostica ni evalúa riesgo.","Toda referencia se verifica en la fuente.","Los pacientes saben qué tecnología usas."]},{"tipo":"reflexion","rotulo":"Tu compromiso","pregunta":"¿Cuál será la primera tarea que delegarás a la IA mañana y qué regla de este curso no vas a romper nunca?","ayuda":"Ejemplo: «Mañana preparo mis recordatorios de cita. Nunca pegaré un nombre en un chat de IA»."},{"tipo":"clave","items":["Para supervisión y congresos: anonimiza más y pide consentimiento para presentaciones públicas.","Lleva preguntas concretas a supervisión; la IA puede ayudarte a ordenarlas.","Empieza con una tarea, mide el ahorro y amplía poco a poco, sin romper tus reglas."]}]}],"quiz":{"titulo":"Evaluación del módulo 5","preguntas":[{"p":"¿Qué resumen de un estudio conserva mejor los matices?","ops":["«El estudio demostró que funciona»","Uno de una sola línea","Uno que menciona participantes, comparación, tamaño del efecto y limitaciones"],"correcta":2},{"p":"¿Cuál es una falla frecuente de la IA con la bibliografía?","ops":["Dar solo referencias de hace 50 años","Inventar referencias que parecen reales","Negarse a dar referencias"],"correcta":1},{"p":"¿Dónde verificas si un artículo de psicología existe?","ops":["En PubMed o Google Académico","Preguntándole a la misma IA","En redes sociales"],"correcta":0},{"p":"El DOI de una referencia lleva a otro artículo. La referencia es…","ops":["Válida si el título suena bien","Válida si la revista existe","No confiable: la descartas"],"correcta":2},{"p":"En la bitácora, ¿qué fórmula escribe «Usar» solo si B2, C2 y D2 dicen «Sí»?","ops":["=SI(O(B2=\"Sí\",C2=\"Sí\",D2=\"Sí\"),\"Usar\",\"No usar\")","=SUMA(B2:D2)","=CONTAR.SI(B2:D2,\"Usar\")","=SI(Y(B2=\"Sí\",C2=\"Sí\",D2=\"Sí\"),\"Usar\",\"No usar\")"],"correcta":3},{"p":"Para presentar un caso en un congreso, además de anonimizar…","ops":["Pides el consentimiento del paciente y sigues las reglas del congreso","Basta con cambiar el nombre","Subes la grabación de la sesión"],"correcta":0},{"p":"¿Cuál es una buena pregunta para supervisión?","ops":["«¿Qué hago con este paciente?»","«¿Qué diagnóstico le pongo?»","Una concreta sobre una situación observada en sesiones"],"correcta":2},{"p":"¿Cómo conviene empezar tu plan de 30 días?","ops":["Pegando todas tus notas en la IA para ordenarlas","Con una sola tarea de bajo riesgo y midiendo el ahorro","Automatizando todo el consultorio la primera semana"],"correcta":1}]}}]});
window.CURSOS_MARA.push({"id":"c-fotografia-producto","nombre":"Fotografía de Producto con el Celular","color":"#E11D48","nivel":"Cursos libres de capacitación","familia":"Negocios y finanzas","periodoTipo":null,"periodoNum":null,"desc":"Aprende a tomar fotos que venden con tu celular y materiales baratos de casa o de la papelería: luz de ventana, difusor y rebotador caseros, fondo infinito, reflejos en perfumes y joyería, composición, fotos para Mercado Libre, el catálogo de WhatsApp, Instagram y Facebook, edición básica y una sesión de 20 fotos en una hora. Es para emprendedores, artesanos y vendedores de perfumes, joyería, ropa, postres, cosméticos o refacciones. No necesitas cámara profesional ni experiencia.","horas":10,"precio":690,"publicado":true,"proximamente":false,"modulos":[{"id":"c-fotografia-producto-m1","titulo":"Módulo 1 — Lo básico: tu celular ya es tu cámara","resumen":"Por qué la foto vende, cómo limpiar el lente, enfocar y exponer tocando la pantalla, bloquear el enfoque, evitar el zoom digital y usar bien el modo retrato, el HDR y la cuadrícula. Tres lecciones y una evaluación.","lecciones":[{"id":"c-fotografia-producto-m1-l1","titulo":"Lección 1 — Por qué la foto vende","objetivo":"explicar por qué la foto es tu mejor vendedor en línea y detectar los errores que hacen que un cliente no pregunte ni compre.","bloques":[{"tipo":"destacado","texto":"<b>Antes de empezar.</b> Este es un <b>curso libre de capacitación</b> con constancia de Instituto Mara: no tiene validez oficial de la SEP ni es una certificación de CONOCER. Aquí aprendes técnicas prácticas para fotografiar tus productos con el celular; no necesitas cámara profesional, y ninguna foto garantiza ventas por sí sola: también cuentan tu precio, tu atención y tu producto."},{"tipo":"texto","texto":"Cuando vendes por WhatsApp, Mercado Libre, Instagram o Facebook, el cliente <b>no puede tocar, oler ni probar</b> tu producto. La foto hace el trabajo de tu mostrador: en un segundo decide si se detiene o sigue deslizando el dedo.<br><br>Piensa en Rocío, que hace perfumes artesanales en Puebla. Sus fragancias son buenas, pero las fotografiaba de noche, sobre el mantel de la cocina y con luz amarilla. Nadie preguntaba. Cuando empezó a tomarlas junto a la ventana, sobre una cartulina blanca, los mensajes de «¿precio?» se multiplicaron. El perfume era el mismo; cambió la foto."},{"tipo":"tabla","titulo":"Lo que el cliente busca en una foto","encabezados":["Pregunta del cliente","Qué debe resolver tu foto","Ejemplo"],"filas":[["¿Qué es exactamente?","Producto completo, nítido y reconocible","Frasco de perfume de frente, con la tapa y la etiqueta legibles"],["¿De qué color es de verdad?","Color fiel, sin filtros que lo cambien","Blusa color vino que se vea vino, no rojo ni café"],["¿De qué tamaño es?","Referencia de escala","Arete junto a una moneda o puesto en una oreja"],["¿Cómo está hecho?","Foto de detalle","Acercamiento a la costura o al broche de la pulsera"],["¿Me puedo fiar de este vendedor?","Fotos limpias, parejas y propias","Catálogo con el mismo fondo y la misma luz en todos los productos"]],"nota":"Una buena foto responde las dudas antes de que el cliente tenga que escribirte."},{"tipo":"comparar","titulo":"La misma pulsera, dos fotos","malTitulo":"Foto que no vende","mal":"Pulsera sobre la cama destendida, de noche, con el foco amarillo del techo. Sale borrosa porque la mano se movió, hay una sombra negra encima y al fondo se ven un control remoto y un calcetín.","bienTitulo":"Foto que vende","bien":"Pulsera sobre una cartulina blanca junto a la ventana, de día. Está nítida, la luz es suave, el color de las piedras se ve real y no hay nada más en la foto que distraiga."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"¿Por qué la foto pesa tanto en una venta en línea?","ops":["Porque la descripción no se lee nunca","Porque el cliente no puede tocar ni ver el producto en persona","Porque las plataformas cobran por foto"],"correcta":1,"explica":"La foto sustituye al mostrador: es lo primero y a veces lo único que el cliente mira con atención."},{"p":"Una foto de catálogo con el mismo fondo y la misma luz transmite…","ops":["Orden y confianza en el vendedor","Que el vendedor no tiene variedad","Que las fotos son de internet"],"correcta":0},{"p":"Si tu foto hace que el color se vea distinto al real, lo más probable es que…","ops":["Vendas más sin problema","La plataforma lo corrija sola","Tengas devoluciones y clientes molestos"],"correcta":2}]},{"tipo":"relacionar","rotulo":"¿Qué duda resuelve cada foto?","pares":[["Anillo puesto en una mano","Tamaño real"],["Acercamiento al cierre de una bolsa","Calidad del acabado"],["Pastel completo de frente con buena luz","Qué es y cómo se ve"],["Refacción junto a su empaque con el número de parte visible","Compatibilidad del producto"]]},{"tipo":"reflexion","rotulo":"Tu foto de hoy","pregunta":"Abre tu catálogo o tus publicaciones y elige la foto de tu producto que menos te guste. ¿Qué dudas le deja al cliente? ¿Qué distrae? ¿La luz es buena? Escríbelo: al final del curso la volverás a tomar.","ayuda":"La foto de… no vende porque…"},{"tipo":"clave","items":["El cliente no puede tocar tu producto: la foto hace el trabajo del mostrador.","Una buena foto responde qué es, de qué color, de qué tamaño y cómo está hecho.","Fotos limpias, fieles y parejas generan confianza en ti como vendedor."]}]},{"id":"c-fotografia-producto-m1-l2","titulo":"Lección 2 — Conoce la cámara de tu celular","objetivo":"limpiar el lente, enfocar y ajustar la exposición tocando la pantalla, bloquear el enfoque y evitar el zoom digital para lograr fotos nítidas.","bloques":[{"tipo":"texto","texto":"No necesitas el celular más caro. Casi cualquier celular de los últimos años toma fotos suficientes para vender, <b>si lo sabes usar</b>. La mayoría de las fotos malas no son culpa de la cámara, sino de un lente sucio, un enfoque en el lugar equivocado o poca luz."},{"tipo":"pasos","rotulo":"Antes de cada sesión y en cada foto","pasos":["<b>Limpia el lente</b> con un paño de microfibra (el de los lentes sirve) o una playera de algodón limpia. El lente vive en tu bolsillo y en tu mano: la grasa de los dedos hace que todo se vea lechoso y con halos alrededor de las luces.","<b>Toca la pantalla sobre el producto</b> para enfocar ahí. Si no lo haces, el celular puede enfocar el fondo.","<b>Ajusta la exposición</b> (qué tan clara u oscura sale la foto): después de tocar, casi todos los celulares muestran un solito o una barra; deslízala hacia arriba o hacia abajo.","<b>Bloquea enfoque y exposición (AE/AF)</b>: deja el dedo presionado un par de segundos sobre el producto hasta que aparezca un aviso como «Bloqueo AE/AF». Así, si te mueves un poco, no se desenfoca ni cambia la luz.","<b>Sostén firme</b>: codos pegados al cuerpo o apoyados en la mesa, y dispara con suavidad. Si tienes tripié o un soporte, mejor."]},{"tipo":"destacado","texto":"<b>Evita el zoom digital.</b> Al pellizcar la pantalla para acercar, el celular solo recorta y agranda la imagen, y pierde calidad. Mejor <b>acércate tú</b> con el celular. Algunos celulares tienen un lente de acercamiento real (botones como 2x, 3x o 5x); esos sí conservan calidad, pero todo lo que esté más allá de ese número vuelve a ser digital."},{"tipo":"tabla","titulo":"Dónde encontrar cada función","encabezados":["Función","En muchos Android","En iPhone"],"filas":[["Enfocar y exponer","Tocar el producto y deslizar el solito o la barra que aparece","Tocar el producto y deslizar el solito hacia arriba o abajo"],["Bloqueo AE/AF","Dejar el dedo presionado sobre el producto; en algunos modelos aparece un candado","Dejar el dedo presionado hasta que aparezca «Bloqueo AE/AF»"],["Cuadrícula","Ajustes de la cámara (el engrane) → Cuadrícula o Líneas guía","Configuración del teléfono → Cámara → Cuadrícula"],["Lentes de acercamiento","Botones 0.5x, 1x, 2x o similares","Botones 0.5x, 1x, 2x, 3x o 5x según el modelo"]],"nota":"Al momento de escribir, estos son los nombres más comunes. Cada marca y cada actualización cambian los menús: si no lo encuentras, busca en la ayuda de tu modelo."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Tu foto sale lechosa y con halos alrededor de las luces. Lo primero que revisas es…","ops":["Si el celular está en modo avión","Si el lente está sucio","Si tienes suficiente memoria"],"correcta":1,"explica":"Un lente con grasa de dedos es la causa más común de fotos lechosas."},{"p":"Quieres un acercamiento a unos aretes. Lo mejor es…","ops":["Acercar el celular tú mismo o usar el botón de un lente real como 2x","Pellizcar la pantalla hasta 10x","Tomar la foto de lejos y recortarla mucho después"],"correcta":0},{"p":"El bloqueo AE/AF sirve para…","ops":["Quitar el fondo automáticamente","Tomar fotos en blanco y negro","Que el enfoque y la luz no cambien si te mueves un poco"],"correcta":2}]},{"tipo":"completar","rotulo":"Completa","items":[{"frase":"Para enfocar el producto, ___ la pantalla justo encima de él.","resp":["toca","tocas","presiona","toque"],"es":"Así el celular sabe qué es lo importante."},{"frase":"Si deslizas el solito hacia arriba, la foto sale más ___.","resp":["clara","iluminada","brillante"]},{"frase":"Para acercarte sin perder calidad, mueve el ___ hacia el producto en lugar de usar el zoom digital.","resp":["celular","teléfono","cel"]}]},{"tipo":"clave","items":["Limpia el lente antes de cada sesión: es gratis y cambia todo.","Toca para enfocar, ajusta la exposición y bloquea con AE/AF.","Acércate con el celular; el zoom digital solo recorta y pierde calidad."]}]},{"id":"c-fotografia-producto-m1-l3","titulo":"Lección 3 — Modo retrato, HDR, cuadrícula y tu primer reto","objetivo":"decidir cuándo conviene el modo retrato, el HDR y la cuadrícula y evaluar tus primeras tres fotos con una lista de verificación.","bloques":[{"tipo":"texto","texto":"Tu celular trae modos que pueden ayudarte o estorbarte. No se trata de activarlos todos, sino de saber <b>para qué sirve cada uno</b> y cuándo apagarlo."},{"tipo":"tarjetas","rotulo":"Tres funciones que conviene conocer","tarjetas":[{"frente":"Modo retrato","reverso":"Desenfoca el fondo para que el producto destaque. Útil en fotos de ambiente (un postre en una mesa con plantas atrás). Cuidado: a veces desenfoca también bordes del producto, como el aro de un arete o las patitas de una tacita. Revisa la foto con zoom."},{"frente":"HDR","reverso":"Combina varias tomas para que no se quemen las partes claras ni se hundan las oscuras. Ayuda con una ventana brillante detrás, pero puede dar colores exagerados. Al momento de escribir, en muchos celulares viene automático; pruébalo encendido y apagado."},{"frente":"Cuadrícula","reverso":"Líneas que dividen la pantalla en nueve partes. Te ayuda a que el producto quede derecho y bien acomodado. No aparece en la foto final: déjala siempre encendida."},{"frente":"Flash","reverso":"En fotos de producto casi siempre conviene apagarlo: da brillos duros, sombras negras y aplana el color. Mejor busca luz de ventana."}]},{"tipo":"comparar","titulo":"Modo retrato bien y mal usado","malTitulo":"Así no","mal":"Foto de una cadena delgada en modo retrato: el celular confunde la cadena con el fondo y la mitad sale borrosa. El cliente no ve bien el eslabón.","bienTitulo":"Así sí","bien":"La cadena se toma en modo foto normal, sobre fondo liso. El modo retrato se deja para una foto de ambiente de la cadena puesta en el cuello, donde el fondo borroso sí ayuda."},{"tipo":"ordenar","rotulo":"Ordena la rutina antes de disparar","items":[{"frase":"limpia el lente enfoca ajusta la luz y dispara","es":"Primero el lente limpio; luego enfocar, exponer y disparar con pulso firme."}]},{"tipo":"plantilla","rotulo":"Lista de verificación de una foto de producto","texto":"1. ¿El lente estaba limpio? (sin halos ni aspecto lechoso)\n2. ¿El producto está nítido donde importa? (revisa con zoom en la galería)\n3. ¿La foto no está ni muy oscura ni quemada?\n4. ¿El color se parece al producto real?\n5. ¿El producto está derecho y completo?\n6. ¿El fondo está limpio y sin objetos que distraigan?\n7. ¿Usé el lente normal o uno real (1x, 2x) en lugar del zoom digital?\n8. ¿El flash estaba apagado?\nCalificación: cuenta cuántos «sí» tienes de 8.","nota":"Guárdala en tus notas del celular: la usarás en todo el curso."},{"tipo":"reflexion","rotulo":"Reto práctico: tus primeras 3 fotos","pregunta":"Elige un producto que vendas. Toma 3 fotos: 1) como lo hacías antes; 2) con el lente limpio, tocando para enfocar y ajustando la exposición; 3) igual que la 2, pero con la cuadrícula para dejarlo derecho y centrado. Califica cada una con la lista de verificación (de 0 a 8). ¿Cuál ganó y por qué?","ayuda":"Foto 1: …/8. Foto 2: …/8. Foto 3: …/8. Lo que más cambió fue…"},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Vas a fotografiar una cadena muy delgada sobre fondo liso. ¿Qué modo conviene?","ops":["Modo nocturno con flash","Foto normal","Modo retrato con el máximo desenfoque"],"correcta":1,"explica":"El modo retrato puede confundir objetos delgados con el fondo."},{"p":"¿Aparece la cuadrícula en la foto que guardas?","ops":["No, solo se ve en la pantalla mientras tomas la foto","Sí, siempre","Solo en iPhone"],"correcta":0}]},{"tipo":"clave","items":["El modo retrato sirve para fotos de ambiente; revisa los bordes con zoom.","Deja la cuadrícula siempre encendida y el flash casi siempre apagado.","Califica tus fotos con una lista de verificación: así mejoras de forma medible."]}]}],"quiz":{"titulo":"Evaluación del módulo 1","preguntas":[{"p":"¿Por qué una buena foto es clave para vender en línea?","ops":["Porque las plataformas solo aceptan fotos profesionales","Porque así no necesitas descripción","Porque sustituye a tener buen precio","Porque el cliente no puede tocar ni ver el producto en persona"],"correcta":3},{"p":"¿Qué haces primero si tus fotos salen lechosas?","ops":["Subir el zoom digital","Limpiar el lente con un paño suave","Comprar un celular nuevo"],"correcta":1},{"p":"¿Para qué sirve tocar la pantalla sobre el producto?","ops":["Para enfocar y medir la luz en ese punto","Para aplicar un filtro","Para activar el flash"],"correcta":0},{"p":"¿Qué hace el bloqueo AE/AF?","ops":["Borra el fondo","Cambia la foto a formato cuadrado","Fija el enfoque y la exposición aunque te muevas un poco"],"correcta":2},{"p":"¿Por qué conviene evitar el zoom digital?","ops":["Porque cambia los colores a blanco y negro","Porque recorta y agranda la imagen y pierde calidad","Porque gasta más batería que el flash"],"correcta":1},{"p":"¿Cuándo es más útil el modo retrato?","ops":["En fotos de ambiente donde quieres desenfocar el fondo","En objetos muy delgados sobre fondo liso","En fotos de etiquetas con números de parte"],"correcta":0},{"p":"¿Qué pasa con el flash en fotos de producto?","ops":["Siempre mejora el color","Es obligatorio en Mercado Libre","Suele dar brillos duros y sombras negras, así que conviene apagarlo"],"correcta":2},{"p":"¿Para qué sirve la cuadrícula?","ops":["Para acomodar el producto derecho y bien encuadrado","Para que la foto pese menos","Para poner marca de agua","Para activar el HDR"],"correcta":0}]}},{"id":"c-fotografia-producto-m2","titulo":"Módulo 2 — Luz y fondo con materiales baratos","resumen":"Luz natural de ventana y la mejor hora del día, sombras duras y suaves, difusor de papel albanene, rebotador de cartulina o unicel, fondo infinito, caja de luz casera, reflejos en vidrio y metal y balance de blancos. Tres lecciones y una evaluación.","lecciones":[{"id":"c-fotografia-producto-m2-l1","titulo":"Lección 1 — La ventana es tu mejor lámpara","objetivo":"aprovechar la luz natural de una ventana, elegir la hora del día y distinguir sombras duras de sombras suaves.","bloques":[{"tipo":"texto","texto":"La luz es lo que más cambia una foto, más que el celular. La buena noticia: la mejor luz para empezar es <b>gratis</b>. Una ventana de día da una luz amplia y suave que hace ver los productos con volumen y color real.<br><br>La clave está en la palabra <b>suave</b>. Cuando la luz viene de una fuente pequeña o muy directa (el sol pegando de lleno, un foco desnudo, el flash), las sombras salen negras y con bordes marcados: son <b>sombras duras</b>. Cuando la luz viene de una fuente grande o tamizada (una ventana sin sol directo, un día nublado, una cortina blanca), las sombras son claras y con bordes difuminados: son <b>sombras suaves</b>."},{"tipo":"comparar","titulo":"Un frasco de crema, dos luces","malTitulo":"Sol directo a mediodía","mal":"El sol entra de lleno por la ventana. El frasco tiene un brillo blanco que borra la etiqueta, una sombra negra y afilada a un lado y la tapa se ve casi sin detalle.","bienTitulo":"Luz de ventana sin sol directo","bien":"La misma ventana a otra hora o con una cortina blanca. El frasco se ve con volumen, la etiqueta se lee, la sombra es suave y gris claro, y el color de la crema es fiel."},{"tipo":"pasos","rotulo":"Arma tu rincón de ventana","pasos":["Elige la ventana más grande de tu casa donde <b>no entre sol directo</b> a la hora en que vas a fotografiar. Si entra sol, espera a otra hora o tápala con tela blanca delgada.","Pon una mesa pegada a la ventana, de lado. La luz debe llegarle al producto <b>de costado</b> o un poco de frente, nunca desde atrás del producto hacia ti.","Apaga los focos del cuarto. Mezclar luz de ventana con luz amarilla de foco da colores raros.","Coloca el producto a unos 50 cm a 1 m de la ventana: más cerca, más luz y más contraste; más lejos, más pareja pero más oscura.","Toma una foto de prueba, revisa sombras y color, y mueve el producto hasta que te guste."]},{"tipo":"tabla","titulo":"¿A qué hora conviene?","encabezados":["Momento","Cómo es la luz","Para qué sirve"],"filas":[["Media mañana o media tarde en una ventana sin sol directo","Suave y pareja","La mayoría de los productos: tu opción de todos los días"],["Día nublado","Muy suave, casi sin sombras","Joyería, cosméticos, ropa; puede verse un poco fría"],["Mediodía con sol directo","Dura, sombras negras","Evítala, o tamízala con un difusor"],["Atardecer","Cálida y dorada, cambia rápido","Fotos de ambiente; no para mostrar el color exacto"],["De noche con focos del cuarto","Amarillenta o verdosa y débil","Evítala; si no hay de otra, usa una lámpara blanca y difusor"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Las sombras suaves se logran con…","ops":["El flash del celular","El sol directo a mediodía","Una fuente de luz grande o tamizada"],"correcta":2,"explica":"Entre más grande sea la fuente de luz respecto al producto, más suave es la sombra."},{"p":"Tienes luz de ventana y el foco amarillo del cuarto prendido. Lo mejor es…","ops":["Usar el flash también","Apagar el foco para no mezclar colores de luz","Prender más focos"],"correcta":1},{"p":"¿Desde dónde conviene que llegue la luz de la ventana al producto?","ops":["De costado o un poco de frente","Desde atrás del producto hacia la cámara","Desde abajo"],"correcta":0,"explica":"Con la luz a contraluz, el frente del producto queda oscuro."}]},{"tipo":"tarjetas","rotulo":"¿Dura o suave?","tarjetas":[{"frente":"Sol directo de mediodía","reverso":"Dura: sombras negras y bordes marcados."},{"frente":"Ventana grande sin sol directo","reverso":"Suave: sombras claras y difuminadas."},{"frente":"Flash del celular","reverso":"Dura y de frente: aplana el producto y da brillos."},{"frente":"Día nublado","reverso":"Muy suave: casi sin sombras."}]},{"tipo":"clave","items":["La luz de ventana sin sol directo es la mejor opción gratis.","Fuente grande o tamizada = sombras suaves; fuente pequeña o directa = sombras duras.","Apaga los focos del cuarto y pon la luz de costado."]}]},{"id":"c-fotografia-producto-m2-l2","titulo":"Lección 2 — Difusor, rebotador, fondo infinito y caja de luz caseros","objetivo":"armar con materiales de papelería un difusor, un rebotador, un fondo infinito y una caja de luz para fotos limpias y parejas.","bloques":[{"tipo":"texto","texto":"Los fotógrafos profesionales usan equipo caro, pero lo que hace cada aparato se puede imitar con materiales de papelería. Con menos de lo que cuesta una comida puedes armar un set que te sirva por meses."},{"tipo":"tabla","titulo":"Tu set casero","encabezados":["Herramienta","Qué hace","Material barato"],"filas":[["<b>Difusor</b>","Tamiza la luz para suavizar sombras y brillos","Papel albanene (el de dibujo técnico), cortina blanca delgada, tela de forro blanca o bolsa de plástico blanca translúcida"],["<b>Rebotador</b>","Refleja luz hacia el lado oscuro del producto","Cartulina blanca, placa de unicel, cartón forrado con papel aluminio (da un rebote más fuerte)"],["<b>Fondo infinito</b>","Fondo sin línea de horizonte, limpio y parejo","Cartulina o pliego de papel blanco en curva, de la pared a la mesa"],["<b>Caja de luz</b>","Encierra el producto en luz suave por varios lados","Caja de cartón con ventanas tapadas con albanene y fondo de cartulina"],["<b>Soporte</b>","Mantiene el celular firme","Tripié sencillo, soporte de celular o una pila de libros"]],"nota":"Si no tienes algo, usa lo que haya en casa: una sábana blanca delgada puede ser difusor y una caja de zapatos forrada de blanco, rebotador."},{"tipo":"pasos","rotulo":"Fondo infinito en 5 minutos","pasos":["Pega con cinta masking la parte de arriba de una cartulina blanca a la pared o a una caja, detrás de tu mesa.","Deja que la cartulina baje <b>en curva</b>, sin doblarla, hasta la mesa, y pega el otro extremo en la mesa.","Coloca el producto en la parte plana, lejos de la curva, para que no se vea el borde.","Pon la ventana de un lado y el rebotador (otra cartulina blanca o unicel) del otro lado, sin salir en la foto.","Toma la foto un poco desde arriba para que el fondo llene todo el cuadro."]},{"tipo":"pasos","rotulo":"Caja de luz casera","pasos":["Consigue una caja de cartón en la que quepa tu producto con espacio de sobra.","Recorta ventanas grandes en los dos costados y en la tapa, dejando un marco de 3 a 4 cm.","Tapa las ventanas con papel albanene o tela blanca delgada pegada con cinta.","Pon dentro una cartulina blanca en curva como fondo infinito.","Coloca la caja junto a la ventana o ilumina los costados con lámparas del mismo color de luz. Fotografía desde el lado abierto."]},{"tipo":"relacionar","rotulo":"¿Qué material para qué función?","pares":[["Papel albanene frente a la ventana","Difusor"],["Placa de unicel del lado oscuro","Rebotador"],["Cartulina en curva de la pared a la mesa","Fondo infinito"],["Caja de cartón con ventanas tapadas","Caja de luz"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Un lado de tu producto sale muy oscuro. ¿Qué agregas?","ops":["Un fondo negro","El flash","Un rebotador blanco del lado oscuro"],"correcta":2,"explica":"El rebotador devuelve luz hacia la sombra sin cambiar el color."},{"p":"¿Por qué la cartulina del fondo infinito va en curva y no doblada?","ops":["Para que pese menos","Para que no se vea la línea entre mesa y pared","Para que la cartulina dure más"],"correcta":1}]},{"tipo":"plantilla","rotulo":"Lista de compras del set casero","texto":"Papelería:\n- 2 o 3 cartulinas blancas (fondo y rebotador)\n- 1 o 2 pliegos de papel albanene (difusor)\n- 1 placa de unicel delgada (rebotador)\n- Cinta masking\n- Pinzas o clips grandes\nCasa:\n- Caja de cartón mediana (caja de luz)\n- Paño de microfibra (lente)\n- Soporte, tripié o pila de libros\nOpcional:\n- Cartulina negra o de color para variar fondos","nota":"Revisa precios en tu papelería: al momento de escribir, todo esto suele caber en un presupuesto de pocos cientos de pesos."},{"tipo":"clave","items":["Difusor suaviza, rebotador rellena sombras y fondo infinito limpia.","Una caja de cartón con albanene se vuelve una caja de luz.","Con materiales de papelería imitas equipo profesional."]}]},{"id":"c-fotografia-producto-m2-l3","titulo":"Lección 3 — Reflejos en vidrio y metal, y balance de blancos","objetivo":"controlar reflejos en perfumes, joyería y metal y corregir el balance de blancos para que el color se vea real.","bloques":[{"tipo":"texto","texto":"El vidrio y el metal son <b>espejos</b>: no muestran la luz, muestran lo que tienen enfrente. Por eso en un frasco de perfume o un anillo aparecen tu mano, el celular, la ventana y hasta el techo. La solución no es quitar la luz, sino <b>controlar qué se refleja</b>: que el producto refleje superficies blancas y limpias en lugar de tu cocina."},{"tipo":"comparar","titulo":"Un perfume de vidrio","malTitulo":"Así no","mal":"El frasco está frente a la ventana con luz dura. Se ve la silueta del celular reflejada al centro, un brillo blanco tapa la marca y detrás se reflejan la alacena y la estufa.","bienTitulo":"Así sí","bien":"El frasco está en una caja de luz o rodeado de cartulinas blancas. Un difusor de albanene suaviza la ventana y deja una franja de luz alargada y limpia a un costado. La etiqueta se lee y el líquido se ve de su color."},{"tipo":"pasos","rotulo":"Receta para joyería y metal","pasos":["Usa luz suave: difusor grande o caja de luz. La luz dura en metal da puntos blancos quemados.","Rodea la pieza de cartulina blanca por los lados y arriba, para que el metal refleje blanco limpio.","Si quieres dar profundidad, pon una tira de cartulina <b>negra</b> a un costado: en la plata y el acero se ve como una línea oscura elegante que marca la forma.","Toma la foto a través de un hueco en la cartulina o un poco de lado para que no se refleje el celular.","Limpia la pieza con un paño antes de la foto: en un acercamiento se notan huellas y polvo."]},{"tipo":"titulo","texto":"Balance de blancos: que el blanco se vea blanco"},{"tipo":"texto","texto":"Cada luz tiene un color: el foco amarillo tiñe todo de naranja, la sombra en un día nublado lo tiñe de azul y algunas lámparas dan un tono verdoso. Tus ojos se acostumbran, pero la cámara no siempre. El <b>balance de blancos</b> es el ajuste que corrige ese tono para que la cartulina blanca salga blanca y el producto tenga su color real. Al momento de escribir, casi todos los celulares lo hacen solos, y en el modo profesional o manual de muchos Android aparece como <b>WB</b>; en iPhone se corrige mejor al editar, con el ajuste de <b>calidez</b>."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"En el frasco de perfume se ve reflejado tu celular. ¿Qué haces?","ops":["Rodear el frasco de cartulina blanca y tomar la foto un poco de lado o por un hueco","Subir el brillo al máximo","Usar el flash para taparlo"],"correcta":0,"explica":"El vidrio refleja lo que tiene enfrente: controla qué hay enfrente."},{"p":"Tu cartulina blanca sale naranja en la foto. El problema es…","ops":["El lente sucio","La cuadrícula encendida","El balance de blancos por la luz amarilla del foco"],"correcta":2},{"p":"¿Para qué sirve una tira de cartulina negra junto a un anillo de plata?","ops":["Para ocultar el precio","Para marcar la forma con una línea oscura en el reflejo","Para que la foto pese menos"],"correcta":1}]},{"tipo":"completar","rotulo":"Completa","items":[{"frase":"El vidrio y el metal funcionan como ___: muestran lo que tienen enfrente.","resp":["espejos","espejo"],"es":"Por eso controlas qué se refleja."},{"frase":"Si la foto sale azulada o naranja, ajusta el balance de ___.","resp":["blancos","blanco"]}]},{"tipo":"reflexion","rotulo":"Reto práctico: el producto más difícil","pregunta":"Elige tu producto más brillante (un frasco, una joya, una refacción cromada). Toma 3 fotos: 1) sin nada especial; 2) con difusor; 3) con difusor, cartulinas blancas alrededor y sin reflejo del celular. Califica cada una con tu lista de verificación y anota qué cambió en los reflejos.","ayuda":"Foto 1: …/8. Foto 2: …/8. Foto 3: …/8. El reflejo que más me costó quitar fue…"},{"tipo":"clave","items":["El vidrio y el metal reflejan su entorno: rodéalos de blanco limpio.","La luz suave evita puntos quemados en joyería y frascos.","El balance de blancos asegura que el color de la foto sea el real."]}]}],"quiz":{"titulo":"Evaluación del módulo 2","preguntas":[{"p":"¿Qué luz da sombras suaves?","ops":["El sol directo de mediodía","El flash del celular","Una ventana grande sin sol directo"],"correcta":2},{"p":"¿Por qué conviene apagar los focos del cuarto al fotografiar junto a la ventana?","ops":["Porque el celular no enfoca con focos prendidos","Para no mezclar luces de distinto color","Para ahorrar luz, nada más"],"correcta":1},{"p":"¿Qué hace un rebotador?","ops":["Quita reflejos del vidrio","Refleja luz hacia el lado oscuro del producto","Tamiza la luz del sol","Desenfoca el fondo"],"correcta":1},{"p":"¿Qué material sirve como difusor?","ops":["Cartulina negra","Papel aluminio sin arrugar","Papel albanene"],"correcta":2},{"p":"¿Cómo se coloca la cartulina de un fondo infinito?","ops":["Solo en la pared, sin tocar la mesa","En curva, de la pared a la mesa, sin doblez","Doblada en ángulo recto"],"correcta":1},{"p":"En un anillo aparece reflejada tu mano con el celular. ¿Qué haces?","ops":["Rodear el anillo de blanco y tomar la foto de lado o por un hueco","Poner el flash","Tomar la foto de más lejos con zoom digital"],"correcta":0},{"p":"Tu fondo blanco sale azulado. ¿Qué ajustas?","ops":["La cuadrícula","El modo retrato","El balance de blancos"],"correcta":2},{"p":"¿Qué pasa con la joyería bajo luz dura?","ops":["Desaparecen los reflejos","Aparecen puntos blancos quemados y sombras duras","Se ve más real"],"correcta":1}]}},{"id":"c-fotografia-producto-m3","titulo":"Módulo 3 — Composición y estilo","resumen":"Regla de tercios, ángulos según el producto, escala y detalle, props que no distraen, consistencia de catálogo, fotos en uso y de ambiente, y el formato correcto para Mercado Libre, el catálogo de WhatsApp y las historias. Tres lecciones y una evaluación.","lecciones":[{"id":"c-fotografia-producto-m3-l1","titulo":"Lección 1 — Regla de tercios y el ángulo correcto","objetivo":"aplicar la regla de tercios y elegir el ángulo cenital, a 45° o frontal según la forma de cada producto.","bloques":[{"tipo":"texto","texto":"Componer es decidir <b>dónde va el producto dentro del cuadro</b> y desde dónde lo miras. La cuadrícula que activaste en el módulo 1 divide la pantalla en tres partes a lo ancho y tres a lo alto. La <b>regla de tercios</b> dice que las fotos se ven más dinámicas cuando el producto o su parte más importante cae sobre una de esas líneas o sus cruces.<br><br>Ojo: no es una ley. Para la foto principal de un marketplace o de tu catálogo, el producto <b>centrado</b> es lo correcto porque el cliente compara productos lado a lado. La regla de tercios brilla en fotos de ambiente y redes sociales, donde dejas espacio para texto o para respirar."},{"tipo":"tabla","titulo":"El ángulo según el producto","encabezados":["Ángulo","Cómo se toma","Ideal para"],"filas":[["<b>Cenital</b> (desde arriba)","Celular paralelo a la mesa, mirando hacia abajo","Productos planos o que se acomodan en conjunto: ropa doblada, galletas, estuches de maquillaje, sets de aretes"],["<b>45°</b>","Celular inclinado, como mirarías el producto sentado a la mesa","Postres, tazas, cajas, jabones, cosméticos: muestra la parte de arriba y el frente"],["<b>Frontal</b> (a la altura del producto)","Celular a la altura del producto, de frente","Productos altos o con etiqueta: frascos de perfume, botellas, veladoras, refacciones con número de parte"]],"nota":"Si dudas, toma los tres ángulos y compara: tu mejor ángulo es el que mejor responde «qué es y cómo es»."},{"tipo":"relacionar","rotulo":"¿Qué ángulo conviene?","pares":[["Frasco de perfume de 100 ml con etiqueta","Frontal"],["Seis galletas decoradas acomodadas en una charola","Cenital"],["Rebanada de pastel de tres leches","45°"]]},{"tipo":"comparar","titulo":"Un pastel a la altura equivocada","malTitulo":"Así no","mal":"Pastel fotografiado de pie, desde muy arriba y algo chueco: parece una mancha redonda, no se ven las capas ni la altura, y la mesa está inclinada en el cuadro.","bienTitulo":"Así sí","bien":"Pastel a 45°, con la cuadrícula para que la mesa quede derecha. Se ven la cobertura y el costado con las capas; la rebanada cortada al frente muestra el relleno."},{"tipo":"ordenar","rotulo":"Ordena el consejo","items":[{"frase":"producto alto con etiqueta se fotografía de frente","es":"Así la etiqueta se lee sin deformarse."}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Para la foto principal de un marketplace, el producto conviene…","ops":["Centrado y llenando buena parte del cuadro","Pegado a una esquina","Pequeño, con mucho fondo alrededor"],"correcta":0,"explica":"El cliente compara productos lado a lado; centrado y grande se ve mejor en la miniatura."},{"p":"Al tomar una foto frontal de una botella, el celular debe ir…","ops":["Muy arriba, inclinado hacia abajo","En el piso","A la altura de la botella"],"correcta":2},{"p":"La regla de tercios se aprovecha mejor en…","ops":["Fotos para identificación oficial","Fotos de ambiente y redes sociales","Fotos de números de serie"],"correcta":1}]},{"tipo":"clave","items":["La cuadrícula te ayuda a aplicar la regla de tercios y a enderezar.","Cenital para planos, 45° para postres y cajas, frontal para frascos y botellas.","En la foto principal de marketplace, producto centrado y grande."]}]},{"id":"c-fotografia-producto-m3-l2","titulo":"Lección 2 — Escala, detalle, props y fotos en uso","objetivo":"mostrar tamaño y detalle, elegir props que no distraigan, mantener un catálogo parejo y tomar fotos del producto en uso.","bloques":[{"tipo":"texto","texto":"Una sola foto rara vez basta. Piensa en un <b>juego de fotos</b> que conteste todas las dudas: la foto principal limpia, una de escala para el tamaño, una de detalle para la calidad y una de producto en uso para que el cliente se imagine con él."},{"tipo":"tarjetas","rotulo":"Las cuatro fotos que no fallan","tarjetas":[{"frente":"Principal","reverso":"Producto completo, fondo limpio, bien iluminado. Es la que aparece en la búsqueda o la miniatura."},{"frente":"Escala","reverso":"Algo que todos conocen junto al producto: una mano, una moneda, una taza. Evita el reclamo de «lo imaginaba más grande»."},{"frente":"Detalle","reverso":"Acercamiento a la textura, costura, broche, acabado o número de parte. Demuestra calidad."},{"frente":"En uso o de ambiente","reverso":"La blusa puesta, el arete en la oreja, el postre servido en la mesa de una fiesta, la refacción instalada. Ayuda al cliente a imaginarse usándolo."}]},{"tipo":"comparar","titulo":"Props: acompañar sin robar","malTitulo":"Props que distraen","mal":"Jabón artesanal de lavanda rodeado de flores de plástico de colores, conchas de mar, velas, un peluche y un letrero con frase. El ojo no sabe dónde mirar y el jabón queda chiquito.","bienTitulo":"Props que ayudan","bien":"El mismo jabón con dos ramitas de lavanda y un paño de lino a un lado, en colores que combinan. Los props cuentan de qué está hecho y el jabón sigue siendo el protagonista."},{"tipo":"lista","items":["<b>Pocos props:</b> uno o dos, relacionados con el producto (ingredientes, uso, temporada).","<b>Colores que combinen</b> con el producto, no que compitan.","<b>Más pequeños o más desenfocados</b> que el producto.","<b>Nada que el cliente pueda creer que viene incluido</b>, o acláralo en la descripción: si la taza de la foto no se vende con el café, dilo.","<b>Consistencia:</b> mismo fondo, misma luz, mismo ángulo y misma distancia en todos los productos de una línea. Tu catálogo se ve como tienda, no como bazar."]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Un cliente reclama que el collar «se veía más grande». ¿Qué foto faltó?","ops":["Una foto de escala, puesto o junto a un objeto conocido","Una foto con más props","Una foto con filtro"],"correcta":0,"explica":"La escala evita malentendidos sobre el tamaño."},{"p":"¿Qué significa tener un catálogo consistente?","ops":["Que cada foto tenga un estilo distinto","Tomar todas las fotos el mismo día","Mismo fondo, luz, ángulo y distancia en los productos de una línea"],"correcta":2},{"p":"En una foto de ambiente aparece una taza que no vendes junto a tu café en grano. ¿Qué haces?","ops":["Cobrarla aparte si la pide","Aclarar en la descripción qué incluye la compra","Nada, el cliente ya sabrá"],"correcta":1}]},{"tipo":"completar","rotulo":"Completa","items":[{"frase":"Una foto de ___ muestra la costura, la textura o el acabado de cerca.","resp":["detalle"],"es":"Demuestra calidad."},{"frase":"Los props deben acompañar sin robarle protagonismo al ___.","resp":["producto"]}]},{"tipo":"reflexion","rotulo":"Reto práctico: tu juego de fotos","pregunta":"Con un producto que vendas, toma el juego completo: principal, escala, detalle y en uso. Califica cada foto con tu lista de verificación. ¿Cuál te costó más trabajo y qué usarías de prop?","ayuda":"Principal …/8, escala …/8, detalle …/8, en uso …/8. Mi prop fue…"},{"tipo":"clave","items":["Planea un juego de fotos: principal, escala, detalle y en uso.","Uno o dos props relacionados y de colores que combinen.","Un catálogo parejo en fondo, luz y ángulo transmite profesionalismo."]}]},{"id":"c-fotografia-producto-m3-l3","titulo":"Lección 3 — La foto correcta para cada plataforma","objetivo":"adaptar tus fotos a Mercado Libre, al catálogo de WhatsApp y a las historias, y calcular cuántas fotos necesitas por producto.","bloques":[{"tipo":"texto","texto":"Cada plataforma muestra las fotos de forma distinta. Si subes una foto vertical al catálogo cuadrado de WhatsApp, se recorta; si subes una foto con textos a la portada de un marketplace, te la pueden rechazar. Por eso conviene tomar la foto <b>con aire alrededor</b> del producto: así puedes recortarla en cuadrado o vertical sin cortarlo."},{"tipo":"tabla","titulo":"Formatos más usados","encabezados":["Dónde","Forma","Recomendación"],"filas":[["Foto principal de marketplace (Mercado Libre y similares)","Cuadrada","Fondo blanco, producto centrado y grande, sin textos ni logos agregados"],["Catálogo de WhatsApp Business","Cuadrada","El producto al centro; en la miniatura se ve pequeño, así que evita detalles diminutos"],["Publicación de Instagram o Facebook","Cuadrada o vertical","Puedes usar fotos de ambiente y la regla de tercios"],["Historias y estados","Vertical (9:16)","Deja espacio arriba y abajo para texto y botones; el producto al centro"]],"nota":"Al momento de escribir, estas son las proporciones más comunes. Las plataformas cambian sus diseños: revisa cómo se ve tu foto después de subirla."},{"tipo":"destacado","texto":"<b>Mercado Libre, foto principal.</b> Al momento de escribir, las guías para vendedores de Mercado Libre México piden en general: <b>fondo blanco</b> liso, el producto completo, centrado y ocupando la mayor parte de la imagen, buena nitidez y resolución, y <b>sin logos, marcas de agua, textos, bordes ni datos de contacto</b>. Algunas categorías (como ropa) tienen reglas propias. Las fotos secundarias pueden mostrar detalle y uso. Las reglas cambian: verifica los requisitos vigentes en el Centro de vendedores de Mercado Libre antes de publicar."},{"tipo":"excel","rotulo":"¿Cuántas fotos necesitas? Tienda de Rocío","datos":[["Producto","Fotos principales","Fotos de detalle","Fotos en uso","Fotos por variante","Variantes (colores o aromas)","Total a tomar"],["Perfume 30 ml",2,2,1,"",3,""],["Aretes de chaquira",2,2,1,5,4,20],["Blusa bordada",3,1,2,6,2,12],["Pastel de tres leches",2,1,1,4,1,4],["","","","","","",""],["Total de fotos","","","","","",""],["Minutos (3 por foto)","","","","","",""],["Horas de sesión","","","","","",""]],"retos":[{"celda":"E2","formula":"=SUMA(B2:D2)","esperado":5,"requiere":"SUMA(","texto":"<b>E2</b>: suma las fotos principales, de detalle y en uso del perfume.","pista":"=SUMA(B2:D2)"},{"celda":"G2","formula":"=E2*F2","esperado":15,"texto":"<b>G2</b>: multiplica las fotos por variante por el número de variantes (aromas).","explica":"Tres aromas por cinco fotos cada uno: 15 fotos solo de perfume."},{"celda":"G7","formula":"=SUMA(G2:G5)","esperado":51,"requiere":"SUMA(","texto":"<b>G7</b>: suma el total de fotos de todos los productos."},{"celda":"G8","formula":"=G7*3","esperado":153,"texto":"<b>G8</b>: calcula los minutos si cada foto (con acomodo y pruebas) toma 3 minutos."},{"celda":"G9","formula":"=REDONDEAR(G8/60,1)","esperado":2.6,"requiere":"REDONDEAR(","texto":"<b>G9</b>: convierte los minutos a horas, redondeando a un decimal.","pista":"=REDONDEAR(G8/60,1)","explica":"Rocío necesita casi tres horas: le conviene dividir la sesión en dos días o empezar con los productos que más vende."}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"¿Por qué conviene dejar aire alrededor del producto al tomar la foto?","ops":["Para poder recortarla en cuadrado o vertical sin cortarlo","Para que el archivo pese menos","Para que se vea más pequeño"],"correcta":0,"explica":"Una sola toma te sirve para varias plataformas."},{"p":"Para la foto principal de Mercado Libre, ¿qué evitas?","ops":["El fondo blanco","Centrar el producto","Textos, logos y marcas de agua"],"correcta":2},{"p":"Una historia de Instagram o un estado de WhatsApp es…","ops":["Horizontal panorámica","Vertical","Cuadrada"],"correcta":1}]},{"tipo":"plantilla","rotulo":"Guía rápida por plataforma","texto":"Mercado Libre, foto principal: cuadrada, fondo blanco, producto completo y centrado, sin textos ni logos.\nMercado Libre, fotos extra: detalle, escala, en uso, etiqueta o medidas.\nCatálogo de WhatsApp: cuadrada, producto al centro, fondo limpio.\nInstagram o Facebook: cuadrada o vertical, puede ser de ambiente.\nHistorias y estados: vertical, espacio libre arriba y abajo para texto.","nota":"Al momento de escribir. Revisa los requisitos vigentes de cada plataforma."},{"tipo":"clave","items":["Toma la foto con aire alrededor para recortarla a cada formato.","Foto principal de marketplace: fondo blanco, centrada y sin textos ni logos.","Calcula cuántas fotos necesitas antes de la sesión para organizar tu tiempo."]}]}],"quiz":{"titulo":"Evaluación del módulo 3","preguntas":[{"p":"¿Qué ángulo conviene para un frasco de perfume con etiqueta?","ops":["Cenital, desde arriba","Desde el piso hacia arriba","Frontal, a la altura del frasco"],"correcta":2},{"p":"¿Qué ángulo es ideal para ropa doblada o un set de galletas?","ops":["A contraluz","Cenital","Frontal"],"correcta":1},{"p":"¿Para qué sirve una foto de escala?","ops":["Para mostrar el tamaño real del producto","Para mostrar el precio","Para ocultar defectos"],"correcta":0},{"p":"¿Cuál es un buen uso de props?","ops":["Uno o dos objetos relacionados y de colores que combinen","Muchos objetos para llenar la foto","Objetos más grandes y llamativos que el producto","Ninguno nunca, bajo ninguna circunstancia"],"correcta":0},{"p":"¿Qué transmite un catálogo con el mismo fondo, luz y ángulo?","ops":["Que las fotos son de internet","Orden y profesionalismo","Poca variedad"],"correcta":1},{"p":"¿Cómo debe ser en general la foto principal en Mercado Libre, al momento de escribir?","ops":["Fondo blanco, producto centrado, sin textos ni logos","Fondo de color con el teléfono del vendedor","Collage de varios productos con precio"],"correcta":0},{"p":"¿Qué formato usan las historias y los estados?","ops":["Cuadrado","Panorámico horizontal","Vertical"],"correcta":2},{"p":"Si un producto tiene 4 colores y quieres 5 fotos por color, ¿cuántas fotos tomas?","ops":["5","20","9"],"correcta":1}]}},{"id":"c-fotografia-producto-m4","titulo":"Módulo 4 — Edición y flujo de trabajo","resumen":"Edición básica en el celular sin exagerar, quitar el fondo cuidando los bordes, colores honestos, nombres de archivo y orden, derechos de las fotos, una sesión de 20 fotos en una hora y el costo de tu set casero. Tres lecciones y una evaluación.","lecciones":[{"id":"c-fotografia-producto-m4-l1","titulo":"Lección 1 — Edición básica en el celular, sin exagerar","objetivo":"editar una foto en el celular en el orden correcto (recorte, enderezar, exposición, contraste, blancos y nitidez) sin cambiar el color real del producto.","bloques":[{"tipo":"texto","texto":"La edición no rescata una foto mal tomada, pero sí convierte una foto buena en una foto lista para vender. La galería de tu celular ya trae casi todo lo que necesitas; al momento de escribir, tanto la app Fotos de iPhone como Google Fotos y las galerías de muchos Android tienen recorte, enderezado y ajustes de luz y color. También hay apps gratuitas de edición, pero no necesitas más."},{"tipo":"pasos","rotulo":"El orden que funciona","pasos":["<b>Recorta</b> al formato que necesitas (cuadrado o vertical) y quita lo que sobra alrededor.","<b>Endereza</b>: usa la cuadrícula del editor para que la mesa y los bordes del producto queden derechos.","<b>Exposición o brillo</b>: aclara si quedó oscura, sin que el blanco se queme (que pierda detalle).","<b>Contraste</b>: un poco da fuerza; mucho hace que las sombras se vuelvan negras.","<b>Blancos y calidez</b>: ajusta hasta que el fondo blanco se vea blanco, no amarillo ni azul. Compara con el producto real en la mano.","<b>Nitidez</b>: solo un toque. Si ves bordes con halos o granito, te pasaste."]},{"tipo":"comparar","titulo":"Nitidez y saturación","malTitulo":"Editada de más","mal":"Aretes de chaquira con saturación al máximo y nitidez alta: los colores brillan de forma irreal, las orillas tienen un halo blanco y se nota granito en el fondo. Parecen de plástico.","bienTitulo":"Editada a punto","bien":"Los mismos aretes con el fondo aclarado, blancos corregidos y un toque de nitidez. Los colores son los que el cliente va a recibir y los bordes se ven limpios."},{"tipo":"destacado","texto":"<b>No engañes al cliente.</b> Corregir la luz y el color para que la foto se parezca a la realidad es correcto. Cambiar el color del producto, borrar defectos, adelgazar una prenda o hacer que un postre se vea más grande de lo que es, no. Además de devoluciones y malas calificaciones, la publicidad engañosa puede traerte problemas con PROFECO. Regla sencilla: <b>la foto debe parecerse a lo que llega a la casa del cliente.</b>"},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"¿Qué haces primero al editar?","ops":["Recortar y enderezar","Subir la saturación","Aplicar un filtro de moda"],"correcta":0,"explica":"Primero defines el cuadro; después ajustas luz y color."},{"p":"Al aplicar nitidez aparecen halos blancos en los bordes. Significa que…","ops":["Falta contraste","El lente está limpio","Te pasaste de nitidez"],"correcta":2},{"p":"Tu labial rojo se ve rosa en la foto. Lo correcto es…","ops":["Poner en la descripción que es rosa","Ajustar blancos y color hasta que se parezca al real","Dejarlo así porque se ve bonito"],"correcta":1}]},{"tipo":"completar","rotulo":"Completa","items":[{"frase":"El ajuste de ___ corrige que el fondo blanco se vea amarillo o azul.","resp":["blancos","calidez","balance de blancos"],"es":"Cada editor le llama distinto."},{"frase":"La foto debe parecerse a lo que ___ a la casa del cliente.","resp":["llega","recibe"]}]},{"tipo":"clave","items":["Edita en orden: recorte, enderezar, luz, contraste, blancos y un toque de nitidez.","Compara la foto con el producto en la mano: el color debe ser el real.","Mejorar la foto está bien; engañar al cliente, no."]}]},{"id":"c-fotografia-producto-m4-l2","titulo":"Lección 2 — Quitar fondo, ordenar archivos y respetar derechos","objetivo":"quitar el fondo de una foto cuidando los bordes, nombrar y organizar tus archivos y usar solo fotos propias o con permiso.","bloques":[{"tipo":"texto","texto":"Quitar el fondo sirve para lograr el fondo blanco de un marketplace o para poner tu producto en una plantilla de catálogo. Al momento de escribir, muchas herramientas lo hacen casi en automático: en iPhone puedes mantener presionado el producto en una foto para separarlo del fondo; en varios Android la galería tiene una opción similar, y hay apps y sitios que lo hacen, como las funciones de quitar fondo de Canva o de apps de fotos de producto. Los nombres y las funciones cambian seguido, así que prueba la que tengas."},{"tipo":"comparar","titulo":"Los bordes delatan","malTitulo":"Recorte descuidado","mal":"Perfume recortado en automático: se comió parte del atomizador, alrededor del frasco quedó un borde gris del fondo viejo y el vidrio transparente salió blanco sólido.","bienTitulo":"Recorte cuidado","bien":"El recorte se revisó con zoom; se corrigieron el atomizador y el borde con la herramienta de borrar y restaurar, y se agregó una sombra suave debajo para que el frasco no parezca flotando."},{"tipo":"lista","items":["<b>Toma bien la foto desde el principio:</b> fondo liso y claro, con buen contraste con el producto, facilita el recorte.","<b>Revisa con zoom</b> las orillas: cabellos de brochas, cadenas, encajes, flecos y vidrio son lo más difícil.","<b>Productos transparentes</b> (perfumes, vasos) casi siempre se ven mejor fotografiados directamente sobre fondo blanco que recortados.","<b>No cambies la forma</b> del producto al recortar."]},{"tipo":"plantilla","rotulo":"Nombres de archivo que sí sirven","texto":"Formato: producto_variante_tipo_número\nEjemplos:\nperfume-vainilla_30ml_principal_01.jpg\nperfume-vainilla_30ml_detalle_02.jpg\naretes-chaquira_azul_escala_01.jpg\nblusa-bordada_talla-m_uso_01.jpg\nCarpetas sugeridas:\n1-originales (lo que sale del celular, sin tocar)\n2-editadas\n3-listas-para-publicar (por plataforma)","nota":"Sin acentos, sin espacios y siempre con el mismo orden. Respalda tus originales en la nube o en una memoria."},{"tipo":"relacionar","rotulo":"Relaciona cada situación con la decisión correcta","pares":[["Encontraste en internet una foto preciosa de un perfume igual al tuyo","No usarla y tomar la tuya"],["Una clienta te mandó una foto usando tu blusa","Pedirle permiso antes de publicarla"],["El proveedor te da fotos oficiales del producto que revendes","Revisar que te autorice usarlas"],["Tomaste tú la foto de tu producto","Puedes usarla libremente"]]},{"tipo":"destacado","texto":"<b>Derechos de las fotos.</b> Que una foto esté en internet no significa que sea libre: casi siempre tiene autor y derechos. Usar fotos ajenas puede provocar que te bajen la publicación o la cuenta, y además es engañoso, porque el cliente espera recibir lo que ve. Usa tus propias fotos; si usas fotos de un proveedor o de un cliente, pide permiso por escrito (un mensaje basta como constancia)."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"¿Qué productos suelen verse mejor fotografiados sobre fondo blanco que recortados?","ops":["Los transparentes, como perfumes y vasos","Las cajas de cartón","Los libros"],"correcta":0,"explica":"El recorte automático suele fallar con el vidrio."},{"p":"¿Para qué guardas una carpeta de originales sin editar?","ops":["Para ocupar más memoria","Porque las plataformas la piden","Para volver a editar sin perder calidad si algo sale mal"],"correcta":2},{"p":"¿Puedes usar una foto de internet de un producto igual al tuyo?","ops":["Sí, si la recortas","No, tiene autor y el cliente espera recibir lo que ve","Sí, si le pones tu logo"],"correcta":1}]},{"tipo":"clave","items":["Al quitar el fondo, revisa los bordes con zoom y no deformes el producto.","Nombra tus archivos siempre igual y guarda los originales aparte.","Usa solo tus fotos o las que tengas permiso de usar."]}]},{"id":"c-fotografia-producto-m4-l3","titulo":"Lección 3 — Sesión de 20 fotos en una hora y el costo de tu set","objetivo":"planear y realizar una sesión de 20 fotos en una hora con una lista de tomas y calcular en hoja de cálculo cuánto te cuesta tu set casero.","bloques":[{"tipo":"texto","texto":"El secreto de los que publican fotos bonitas todas las semanas no es el talento: es el <b>método</b>. Si preparas todo antes, en una hora puedes sacar unas 20 fotos buenas. Si improvisas, en una hora sacas tres y te desesperas."},{"tipo":"pasos","rotulo":"Tu sesión de una hora","pasos":["<b>Antes (el día anterior):</b> haz tu lista de tomas, limpia los productos, carga el celular y libera memoria.","<b>Minutos 0 a 10:</b> arma el set junto a la ventana: fondo infinito, difusor y rebotador. Limpia el lente. Toma una foto de prueba y ajusta.","<b>Minutos 10 a 45:</b> fotografía producto por producto siguiendo la lista. No muevas el set entre productos para que el catálogo quede parejo. Marca cada toma hecha.","<b>Minutos 45 a 55:</b> revisa en la galería con zoom. Repite solo las que fallaron la lista de verificación.","<b>Minutos 55 a 60:</b> pasa las fotos a tu carpeta de originales y respáldalas. La edición va en otro momento."]},{"tipo":"plantilla","rotulo":"Lista de tomas (ejemplo para 20 fotos)","texto":"Perfume vainilla 30 ml: principal frontal, detalle del atomizador, escala en la mano, ambiente con props (4)\nPerfume rosa 30 ml: principal frontal, detalle, escala, ambiente (4)\nAretes de chaquira azul: principal cenital, detalle, puestos (3)\nAretes de chaquira rojo: principal cenital, detalle, puestos (3)\nBlusa bordada: principal cenital doblada, detalle del bordado, puesta (3)\nSet completo de la marca: cenital, 45 grados, vertical para historias (3)\nTotal: 20 fotos. Marca con una palomita cada toma hecha.","nota":"Adáptala a tus productos. Pon primero los que más vendes."},{"tipo":"excel","rotulo":"¿Cuánto cuesta tu set casero?","datos":[["Concepto","Cantidad","Precio unitario","Subtotal"],["Cartulina blanca",3,12,""],["Papel albanene (pliego)",2,15,30],["Placa de unicel",1,35,35],["Cinta masking",1,28,28],["Pinzas o clips grandes",1,30,30],["Paño de microfibra",1,25,25],["Soporte para celular",1,120,120],["Total del set","","",""],["Productos que fotografías al mes","","",20],["Costo del set por producto (primer mes)","","",""],["Cobro de un fotógrafo por producto (ejemplo)","","",80],["¿Conviene hacerlo tú?","","",""]],"retos":[{"celda":"D2","formula":"=B2*C2","esperado":36,"texto":"<b>D2</b>: calcula el subtotal de las cartulinas: cantidad por precio unitario.","pista":"=B2*C2"},{"celda":"D9","formula":"=SUMA(D2:D8)","esperado":304,"requiere":"SUMA(","texto":"<b>D9</b>: suma todos los subtotales para saber el costo del set."},{"celda":"D11","formula":"=D9/D10","esperado":15.2,"texto":"<b>D11</b>: divide el costo del set entre los productos que fotografías al mes.","explica":"Y eso solo el primer mes: el set te dura muchos meses más, así que el costo por producto baja cada mes."},{"celda":"D13","formula":"=SI(D11<D12,\"Sí\",\"No\")","esperado":"Sí","requiere":"SI(","texto":"<b>D13</b>: con SI, escribe «Sí» si el costo por producto de tu set es menor que el cobro del fotógrafo, y «No» si no.","pista":"=SI(D11<D12,\"Sí\",\"No\")","explica":"Contratar a un fotógrafo no es malo: tiene sentido para una campaña especial. Pero para el día a día, tu set casero se paga solo."}]},{"tipo":"destacado","texto":"Los precios de la hoja son <b>de ejemplo</b>. Al momento de escribir, cambian mucho según la ciudad y la papelería: pon los tuyos para saber tu costo real."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"¿Qué haces el día anterior a la sesión?","ops":["La lista de tomas, limpiar productos y cargar el celular","Editar las fotos","Comprar un celular nuevo"],"correcta":0,"explica":"La preparación es lo que te permite sacar 20 fotos en una hora."},{"p":"¿Por qué no conviene mover el set entre productos?","ops":["Porque se rompe la cartulina","Porque el celular pierde el enfoque para siempre","Para que todo el catálogo tenga la misma luz y fondo"],"correcta":2},{"p":"En la sesión, ¿cuándo editas?","ops":["Nunca","Después, en otro momento","Entre cada foto"],"correcta":1}]},{"tipo":"reflexion","rotulo":"Reto final: antes y después","pregunta":"Regresa a la foto que elegiste en la primera lección. Vuelve a tomar ese producto con todo lo aprendido (luz de ventana, difusor, fondo, ángulo, edición). Luego toma otras 2 fotos del mismo producto para completar su juego (detalle y escala o en uso). Califica las 3 con tu lista de verificación y compáralas con la foto original.","ayuda":"Foto original: …/8. Nuevas: …/8, …/8, …/8. Lo que más me ayudó fue…"},{"tipo":"clave","items":["Con lista de tomas y el set armado, 20 fotos en una hora es posible.","Toma en una sesión, edita en otra y respalda siempre los originales.","Tu set casero cuesta poco por producto y te sirve por meses."]}]}],"quiz":{"titulo":"Evaluación del módulo 4","preguntas":[{"p":"¿Cuál es el primer paso al editar?","ops":["Subir la nitidez","Aplicar filtro","Recortar y enderezar"],"correcta":2},{"p":"¿Qué indica que te pasaste de nitidez?","ops":["Fondo más blanco","Halos en los bordes y granito","Colores más fieles"],"correcta":1},{"p":"¿Qué edición es engañosa?","ops":["Recortar a cuadrado","Cambiar el color real del producto","Corregir el balance de blancos","Enderezar la foto"],"correcta":1},{"p":"Al quitar el fondo de una foto, ¿qué revisas con zoom?","ops":["El nombre del archivo","La hora de la foto","Los bordes del producto"],"correcta":2},{"p":"¿Cuál es un buen nombre de archivo?","ops":["foto bonita.jpg","aretes-chaquira_azul_detalle_01.jpg","IMG_4587 final final (2).jpg"],"correcta":1},{"p":"¿Qué haces si quieres publicar una foto que te mandó una clienta?","ops":["Pedirle permiso antes","Publicarla sin avisar","Recortarla para que no se note"],"correcta":0},{"p":"¿Qué te permite sacar unas 20 fotos en una hora?","ops":["Editar entre cada foto","Cambiar de fondo en cada producto","Preparar el set y una lista de tomas antes"],"correcta":2},{"p":"Si tu set cuesta $300 y fotografías 20 productos, ¿cuánto te cuesta por producto el primer mes?","ops":["$300","$15","$6"],"correcta":1}]}}]});
